-- ============================================================================
-- Eve of Giants — campaign site seed
-- Lost Mine of Phandelver (levels 1–5) → Storm King's Thunder (5–11)
-- → Vecna: Eve of Ruin (10/11–20), following "Eve of Giants - Campaign Guide".
--
-- Act I is the Lost Mine library module (Phandelver and Below, chapters 1–4), written as
-- reveal blocks, plus this campaign's seeds. Acts II and III are one block per entry for now.
-- "(ours)" in GM notes marks our additions; OPTIONAL marks book content the guide skips.
--
-- Everything starts hidden. Make an entry visible when the party meets it, then reveal its
-- blocks and links as they learn more.
--
-- Needs progressive_reveal.sql first. Safe to re-run: it only adds what's missing and never
-- touches anything you've edited.
-- ============================================================================

BEGIN;

DO $chk$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.campaigns WHERE slug = 'eve-of-giants') THEN
    RAISE EXCEPTION 'Campaign eve-of-giants not found. Run dashboard_campaigns.sql first.';
  END IF;
  IF to_regclass('public.the8_reveal_blocks') IS NULL THEN
    RAISE EXCEPTION 'Run progressive_reveal.sql first: this seed writes reveal blocks.';
  END IF;
END $chk$;


-- ---------------------------------------------------------------------------
-- 1. HISTORY  (26 entries, 44 blocks)
-- ---------------------------------------------------------------------------
WITH c AS (SELECT id FROM public.campaigns WHERE slug = 'eve-of-giants'),
seed(category, title, gm_notes, preferred_habitat) AS (VALUES
  ($c$history$c$, $t$The Phandelver Pact$t$, $g$The pact's history is common knowledge in outline (DC 10 History). The Rockseekers are dwarves of the same tradition reopening the mine; Gundren talks about it constantly.$g$, NULL::text),
  ($c$history$c$, $t$The Forge of Spells$t$, $g$Wave Echo Cave area W15, guarded by a spectator bound to serve 101 years. Brazier of green flame: nonmagical weapon or armour bathed 1 minute becomes +1 for 1d12 hours. Removing the brazier kills the flame forever. Items kept there: Lightbringer (+1 mace) and Tergon's +1 breastplate. Eve seed (ours): a fragment of the Vonindod, the dragon-slaying colossus Duke Zalto's fire giants are hunting (SKT ch. 2 and 8).$g$, NULL::text),
  ($c$history$c$, $t$The Fall of Wave Echo Cave$t$, $g$Undead in Wave Echo Cave are the battle's dead: dwarf and ogre zombies, ghouls, the flameskull, and Mormesk the wraith, the last wizard to die there. The battle's damage is visible in the Starry Cavern (W13). Note: in the 2014 Lost Mine this was an orc host; Phandelver and Below makes it bandits, and we follow PaB.$g$, NULL::text),
  ($c$history$c$, $t$The Resettling of Phandalin$t$, $g$The town's lack of authority is the root of the Redbrand problem and of Halia Thornton's ambitions. Sildar wants the Lords' Alliance to fill that gap.$g$, NULL::text),
  ($c$history$c$, $t$The Coming of the Redbrands$t$, $g$Iarno Albrek founded the Redbrands about two months ago under the name Glasstaff, after he was sent to set up a constabulary. Their base is under Tresendar Manor.$g$, NULL::text),
  ($c$history$c$, $t$The Destruction of Thundertree$t$, $g$Ash zombies remain in some buildings; blights in the gardens. Mirna Dendrar's family fled from here when she was a girl.$g$, NULL::text),
  ($c$history$c$, $t$The Fall of Conyberry$t$, $g$Agatha's presence is one reason nobody resettled. The Triboar Trail still runs through the ruins, which makes them the landmark for finding her lair.$g$, NULL::text),
  ($c$history$c$, $t$Netheril$t$, $g$Hamun Kost is digging at Old Owl Well for Netherese lore. His best find so far: a ring of protection made from a single piece of green glass stronger than steel. The tower's builder was a wizard named Dresina (Agatha knows).$g$, NULL::text),
  ($c$history$c$, $t$Phalorm$t$, $g$Cragmaw Castle was built by a wizard of old Phalorm: seven overlapping towers, the upper floors long since collapsed.$g$, NULL::text),
  ($c$history$c$, $t$Illefarn$t$, $g$The Redbrand password for the skeletons in the Tresendar crypts (area R4) is "Illefarn".$g$, NULL::text),
  ($c$history$c$, $t$The Tresendar Family$t$, $g$The cellars and crypt are now the Redbrand hideout. Six skeletons guard the crypt and ignore anyone in a scarlet cloak or who speaks the password "Illefarn".$g$, NULL::text),
  ($c$history$c$, $t$The Ordning$t$, $g$The idea that holds Act II together. Fire giants rank by forging, frost giants by battle, stone giants by sculpture, hill giants by bulk. Every giant lord's plan is the same move in different clothes: impress the gods and remake the order. Say that out loud through an NPC once and the act clicks.$g$, NULL::text),
  ($c$history$c$, $t$The Shattering of the Ordning$t$, $g$Annam the All-Father broke the ordning to shake his children out of their complacency after the small folk and the dragons' war over Tiamat. Each giant kind keeps its internal order but competes with the others for the top. Small folk can only guess at the cause. Seeded in Act I through Agatha (ours). Its answer in this campaign is the alliance between storm giants and small folk at the end of SKT ch. 12.$g$, NULL::text),
  ($c$history$c$, $t$Ostoria and the War of Giants and Dragons$t$, $g$The war was some forty thousand years ago. It's why Zalto wants the Vonindod, why Sansuri hunts an Ostorian trove of dragon magic, why Kayalithica thinks the small folk's towns sit on Ostoria's bones, and why Mirran dreams of restoring the empire. It's also why the dragons (Iymrith, Klauth, Claugiyliamatar) are watching so closely: they won't allow another giant empire.$g$, NULL::text),
  ($c$history$c$, $t$The Vonindod$t$, $g$Duke Zalto's fire giants are digging up the fragments with rods of the Vonindod that pull toward them. Planted in Act I (ours) as the runed plate beside the Forge of Spells; grows at Triboar, where a fragment lies under the north campground (SKT ch. 2); pays off at Ironslag (ch. 8). Echoed in Eve of Ruin ch. 4 by the colossus Landro.$g$, NULL::text),
  ($c$history$c$, $t$The Murder of Queen Neri$t$, $g$Mirran and Nym, Hekaton's elder daughters, plotted it with Iymrith's help, blaming their mother for their father naming Serissa heir (Neri had in fact argued against that announcement). Iymrith put them in touch with the Kraken Society, whose agents ambushed and killed Neri, then spread the Lords' Alliance rumour. The only clue left is a wooden gambling chip painted with a golden goose, found by the body (SKT ch. 10).$g$, NULL::text),
  ($c$history$c$, $t$The Disappearance of King Hekaton$t$, $g$Mirran and Nym fed Hekaton false information about the assassins and sent him into a Kraken Society ambush. He's alive, chained aboard the ship Morkoth, which circles the islands of the Trackless Sea and is shielded from scrying. Iymrith wants him alive so he can't be resurrected and can be ransomed if her plans fail (SKT ch. 11).$g$, NULL::text),
  ($c$history$c$, $t$The Tyranny of Dragons$t$, $g$Background only: it's what upset the giant gods enough to break the ordning. It returns in Eve of Ruin ch. 8, where Tiamat in Avernus holds the last piece of the Rod of Seven Parts.$g$, NULL::text),
  ($c$history$c$, $t$The Ring of Winter$t$, $g$Jarl Storvald wants it to bring the Age of Everlasting Ice. He bought a drop of Cimber's blood from a Zhentarim wizard named Nilraun to power his runes of tracking, but the runes lead his raiders to Artus's living relatives instead, such as Sirac of Suzail in Bryn Shander (OPTIONAL).$g$, NULL::text),
  ($c$history$c$, $t$Vecna and Kas$t$, $g$Vecna made the Sword of Kas for his lieutenant; the sword urged Kas to kill and replace him. Kas struck Vecna down in his tower, but Vecna flung him across the multiverse first. Kas became a vampire, ruler and prisoner of Tovag, a Domain of Dread. Vecna rose again as a god of secrets and magic. Each still wants the other annihilated.$g$, NULL::text),
  ($c$history$c$, $t$The Ritual of Remaking$t$, $g$Vecna, already a god, means to gather enough secrets, weave them with his own essence in the Cave of Shattered Reflection on Pandemonium, and detonate the result. Pandemonium is destroyed, the multiverse unravels, and Vecna, preserved in a singularity, reknits it as he likes: everyone serves him, he has never been defeated, and his enemies live in torment. Campaign theme (guide): the same ambition as the giant lords, at the largest scale there is.$g$, NULL::text),
  ($c$history$c$, $t$The Rod of Seven Parts$t$, $g$In a war between the primordials and the gods, the demon lord Miska the Wolf-Spider nearly won. Seven Wind Dukes of Aaqa wove the Rod of Law and imprisoned Miska on Pandemonium; the rod shattered. Each piece senses the next and casts one spell (commune, arcane gate, reverse gravity, regenerate, find the path, mirage arcane, simulacrum). Whole, it's a +3 quarterstaff with seven charges. 'Mordenkainen' claims it can stop Vecna; Kas really wants it to free Miska.$g$, NULL::text),
  ($c$history$c$, $t$The Crown of Lies$t$, $g$The Dark Powers gave it to Kas in exchange for his vow to deliver Vecna to them, and released him from Tovag. It lets him become any creature he has seen, lies told in that form always seem true, and only a wish can reveal him. If the wearer is killed by the creature he's disguised as, the crown is destroyed. Fail, and the Dark Powers take Kas back.$g$, NULL::text),
  ($c$history$c$, $t$The Power of Secrets$t$, $g$Mechanic to explain early (guide). Once the party has Vecna's Link, a secret can be whispered into the wind as an action: the whole party gains advantage on d20 rolls for 1 minute, and the secret is gone. Telling a secret to an NPC wastes it. Secrets kept unspent weaken Vecna in the final chapter. Track them with the book's Secrets Tracker (appendix C); Kas's secret about Vecna's location is still known after it's spent.$g$, NULL::text),
  ($c$history$c$, $t$Vecna's Link$t$, $g$Received in Eve of Ruin ch. 1 when the party disrupts the cult's ritual. It lets them spend secrets and is why the wizards' botched wish pulls them to Sigil in ch. 2. Use the visions to keep the urgency up between rod pieces.$g$, NULL::text),
  ($c$history$c$, $t$Neverwinter's Lost Crown$t$, $g$Crown thread (guide). Act I: Neverember's agents quietly pay off, or worse, anyone claiming the old blood (ours). Act II: the Lords' Alliance is framed for Neri's murder. Act III: Indrina Lamsensettle knows his claim isn't legitimate (ch. 1), and in Vecna's 'Neverwinter's New King' unreality Neverember is a death knight tyrant (ch. 11).$g$, NULL::text)
)
INSERT INTO public.the8_lore_entries (campaign_id, category, title, gm_notes, preferred_habitat, is_secret)
SELECT c.id, s.category, s.title, s.gm_notes, s.preferred_habitat, true
FROM seed s CROSS JOIN c
WHERE NOT EXISTS (SELECT 1 FROM public.the8_lore_entries e WHERE e.campaign_id = c.id AND e.title = s.title);
-- blocks: all hidden; only added to entries that have none yet, so your edits are never overwritten
WITH c AS (SELECT id FROM public.campaigns WHERE slug = 'eve-of-giants'),
seed(title, sort_order, body) AS (VALUES
  ($t$The Phandelver Pact$t$, 0, $b$More than five hundred years ago, clans of dwarves and gnomes made an agreement to share a rich mine in a wondrous cavern. They called it the Phandelver Pact.$b$),
  ($t$The Phandelver Pact$t$, 1, $b$The cavern was Wave Echo Cave. Its wealth was more than ore: the place was full of magic, and human spellcasters joined the pact to bind that power into a great forge.$b$),
  ($t$The Phandelver Pact$t$, 2, $b$Old Phandalin grew rich alongside the mine. Its people were firm allies of the dwarves and gnomes.$b$),
  ($t$The Forge of Spells$t$, 0, $b$Legend says the pact's wizards built a forge in the heart of Wave Echo Cave where magic weapons, armour and gnome gadgets could be made.$b$),
  ($t$The Forge of Spells$t$, 1, $b$The Spider wants it. He has been searching the mine for the forge, not for its gold.$b$),
  ($t$The Forge of Spells$t$, 2, $b$The forge survived, but its magic has faded. Its green flame no longer makes lasting enchantments: weapons or armour bathed in it for a minute become magic for a few hours only.$b$),
  ($t$The Forge of Spells$t$, 3, $b$Beside the forge lies a giant-sized plate of adamantine carved with runes. The old miners were studying it. Gundren can't name it.$b$),
  ($t$The Fall of Wave Echo Cave$t$, 0, $b$Five hundred years ago, bandits swept through the North. A powerful bandit force, backed by evil mercenary wizards, attacked Wave Echo Cave for its riches.$b$),
  ($t$The Fall of Wave Echo Cave$t$, 1, $b$Human wizards fought beside the dwarves and gnomes to defend the forge. The spell battle that followed brought much of the cavern down. Few survived, and the mine's location was lost.$b$),
  ($t$The Fall of Wave Echo Cave$t$, 2, $b$The same bandits sacked old Phandalin, which lay abandoned for centuries afterwards.$b$),
  ($t$The Fall of Wave Echo Cave$t$, 3, $b$The dead of that battle still lie in the mine, and not all of them rest.$b$),
  ($t$The Resettling of Phandalin$t$, 0, $b$Phandalin was abandoned for centuries. In the last three or four years, hardy folk from Neverwinter and Waterdeep have begun building a new town on top of the ruins.$b$),
  ($t$The Resettling of Phandalin$t$, 1, $b$Farmers, woodcutters, fur traders and prospectors live there now, drawn by stories of gold and platinum in the foothills of the Sword Mountains.$b$),
  ($t$The Resettling of Phandalin$t$, 2, $b$The town has no lord, no walls and no watch. It elects a townmaster each year, but nobody enforces anything, and ruffians have noticed.$b$),
  ($t$The Coming of the Redbrands$t$, 0, $b$For months, a gang in scarlet cloaks called the Redbrands has been bullying Phandalin: shaking down businesses, threatening miners and fur traders, and laughing at the townmaster.$b$),
  ($t$The Coming of the Redbrands$t$, 1, $b$Their leader is someone the townsfolk know only as Glasstaff.$b$),
  ($t$The Coming of the Redbrands$t$, 2, $b$A tenday ago, Thel Dendrar, a woodcarver, stood up to them when they bullied his wife. They murdered him in front of witnesses and took his body. His wife, daughter and son vanished the same day.$b$),
  ($t$The Coming of the Redbrands$t$, 3, $b$The Redbrands leave only one business alone: the Miner's Exchange.$b$),
  ($t$The Destruction of Thundertree$t$, 0, $b$Thundertree was a prosperous village of woodcutters and trappers, where the Neverwinter River leaves Neverwinter Wood.$b$),
  ($t$The Destruction of Thundertree$t$, 1, $b$Thirty years ago, Mount Hotenow to the north erupted and devastated it. In the wake of the eruption, a plague of strange zombies swept the area and killed or drove off the survivors.$b$),
  ($t$The Destruction of Thundertree$t$, 2, $b$Most of the zombies have crumbled to dust, but the magic that lingers has twisted the plants there into something dangerous. Few people go there, and fewer stay.$b$),
  ($t$The Fall of Conyberry$t$, 0, $b$Conyberry was a village on the Triboar Trail. It has been abandoned for years and lies in ruins.$b$),
  ($t$The Fall of Conyberry$t$, 1, $b$Something old haunts the woods a few miles outside it: a banshee named Agatha.$b$),
  ($t$Netheril$t$, 0, $b$Thousands of years ago, an empire of mages called Netheril held lands that are now ruins. Old Owl Well is one of its watchtowers.$b$),
  ($t$Netheril$t$, 1, $b$Its wizards left magic behind in the places they built, and scholars and treasure-hunters still dig for it.$b$),
  ($t$Phalorm$t$, 0, $b$An ancient realm called Phalorm once controlled much of the North. Its wizards built castles that still stand in pieces in the wilds.$b$),
  ($t$Illefarn$t$, 0, $b$Illefarn was an ancient elven nation that once spread across much of the Sword Coast.$b$),
  ($t$The Tresendar Family$t$, 0, $b$The Tresendars were the noble family whose manor, more castle than house, still stands in ruins at the east edge of Phandalin.$b$),
  ($t$The Tresendar Family$t$, 1, $b$Their elders are laid to rest in a crypt under the manor.$b$),
  ($t$The Ordning$t$, 0, $b$Among giants, an order set by their gods ranks every giant kind: storm giants at the top, then cloud, fire, frost and stone giants, with hill giants at the bottom. Within each kind there is a ranking too, by forging, fighting, sculpting or sheer size.$b$),
  ($t$The Shattering of the Ordning$t$, 0, $b$Months ago, every giant in the North felt the old order break at once. Since then giants of every kind have come down from their strongholds, and the small folk have no idea why.$b$),
  ($t$Ostoria and the War of Giants and Dragons$t$, 0, $b$Thousands of years ago the last great empire of giants, Ostoria, ruled the lands that are now the North. It fell after a long and brutal war with the dragons. Little of it remains.$b$),
  ($t$The Vonindod$t$, 0, $b$Giant legends speak of the Vonindod, the 'titan of death', a colossus of adamantine built to slay dragons in the old war. It was broken in battle and dismantled afterwards, and its pieces scattered.$b$),
  ($t$The Murder of Queen Neri$t$, 0, $b$Queen Neri of the storm giants loved the small folk and often rose from the sea to meet them on the Sword Coast. Some months ago she was found dead on a small island where she was known to meet humans. Storm giant rumour says the Lords' Alliance killed her.$b$),
  ($t$The Disappearance of King Hekaton$t$, 0, $b$The storm giant king set out to find his wife's killers and never came back. After a month of waiting, his youngest daughter, Serissa, took the Wyrmskull Throne as regent.$b$),
  ($t$The Tyranny of Dragons$t$, 0, $b$Not long ago, evil dragons stirred by their dark queen, Tiamat, threatened the North until they were defeated and Tiamat was banished to the Nine Hells. That fear faded fast once the giants came.$b$),
  ($t$The Ring of Winter$t$, 0, $b$An old legend among frost giants tells of the Ice That Never Melts, a frost-coated golden ring that can freeze the oceans and bury the world in snow. Small folk call it the Ring of Winter. It was last known to be carried by a human adventurer named Artus Cimber.$b$),
  ($t$Vecna and Kas$t$, 0, $b$On the world of Oerth, centuries ago, the lich Vecna ruled an empire, and the warlord Kas led his armies. Kas betrayed him. All that was left of Vecna was a hand and an eye.$b$),
  ($t$The Ritual of Remaking$t$, 0, $b$Rumours among scholars of the planes speak of something vast being woven somewhere far away, fed by stolen secrets.$b$),
  ($t$The Rod of Seven Parts$t$, 0, $b$A legendary artifact, broken long ago into seven pieces scattered across the multiverse.$b$),
  ($t$The Crown of Lies$t$, 0, $b$A crown of burnished, entwined metal rods, spoken of only in the darkest corners of the Shadowfell.$b$),
  ($t$The Power of Secrets$t$, 0, $b$Cults of Vecna across the worlds are kidnapping people who know shameful or dangerous things, and draining what they know.$b$),
  ($t$Vecna's Link$t$, 0, $b$A mark on the soul that can't be removed or researched. Those who carry it sometimes see a robed, withered figure weaving something in a cave full of crystal.$b$),
  ($t$Neverwinter's Lost Crown$t$, 0, $b$Neverwinter's old royal line ended generations ago. Lord Protector Dagult Neverember rules on a claim of descent from one of the city's past heroes.$b$)
)
INSERT INTO public.the8_reveal_blocks (campaign_id, lore_entry_id, body, is_revealed, sort_order)
SELECT c.id, e.id, s.body, false, s.sort_order
FROM seed s CROSS JOIN c
JOIN public.the8_lore_entries e ON e.campaign_id = c.id AND e.title = s.title
WHERE NOT EXISTS (SELECT 1 FROM public.the8_reveal_blocks b WHERE b.lore_entry_id = e.id);

-- ---------------------------------------------------------------------------
-- 2. LOCATIONS  (104 entries, 166 blocks)
-- ---------------------------------------------------------------------------
WITH c AS (SELECT id FROM public.campaigns WHERE slug = 'eve-of-giants'),
seed(category, title, gm_notes, preferred_habitat) AS (VALUES
  ($c$locations$c$, $t$Neverwinter$t$, $g$Gundren hires the party here. Sildar met Gundren here. Glasstaff is sent here for trial if captured. Eve seeds (ours), at most twice in Act I: the Vecna cult under Neverdeath Graveyard (Eve of Ruin ch. 1). Neverwinter is where Act III begins.$g$, NULL::text),
  ($c$locations$c$, $t$The Triboar Trail$t$, $g$Random encounters (PaB ch. 3): stirges, ghouls at night, an ogre, Cragmaw bands (who know the way to the castle), hobgoblin squads hunting the party for the Spider's bounty, bugbear scouts from Wyvern Tor, wolves, an owlbear. Travel: about 24 miles a day. Eve seeds (ours): Countess Sansuri's castle Lyn Armaal; Cryovain, held by Jarl Storvald through his eggs (SKT ch. 7).$g$, NULL::text),
  ($c$locations$c$, $t$The Goblin Ambush$t$, $g$Four goblins wait in the woods, two each side, until someone approaches the horses. The last one flees down the trail. The trail runs five miles north-west to the Cragmaw Hideout. Snare and pit: DC 15 Perception to spot, DC 10 Dex save.$g$, NULL::text),
  ($c$locations$c$, $t$Cragmaw Hideout$t$, $g$H1 cave mouth; H2 guard post (2 goblins, goblin boss); H3 kennel (3 wolves; DC 15 Animal Handling, 10 with food; chimney up to H8); H4–H5 steep passage and bridge; H6 den (5 goblins, goblin bosses Yeemik and Errk, Sildar at 1 hp); H8 Klarg, 2 goblin honour guards, wolf Ripper, about 30 days of plunder, Lionshield crates. About fifteen goblins in all. Finishing the hideout: level 2.$g$, NULL::text),
  ($c$locations$c$, $t$Phandalin$t$, $g$Home base for the whole module. The town's mood tracks the Redbrands: after the hideout is cleared, people talk freely and Halia Thornton starts angling to be in charge. Arrival is in the evening; the Stonehill Inn is the natural first stop.$g$, NULL::text),
  ($c$locations$c$, $t$Stonehill Inn$t$, $g$Rumours (PaB ch. 2): Elsa, Daran Edermath is a former adventurer. Freda, the Redbrands leave the Miner's Exchange alone (they don't want trouble with Halia). Lanar, marauders on the east end of the Triboar Trail, the townmaster wants them gone. Narth, Sister Garaele left town for a few days and came back wounded. Pip, Carp Alderleaf found a secret tunnel in the woods and the Redbrands nearly caught him. Toblen, the murder of Thel Dendrar. Anyone: the Redbrands drink at the Sleeping Giant. Sildar takes one of the six rooms. (Elsa's sister Gwyn belongs to PaB chapter 5 on: left out.)$g$, NULL::text),
  ($c$locations$c$, $t$Barthen's Provisions$t$, $g$Elmina's clerks are Ander and Thistle. She expects the other Rockseeker brothers back "any day now" to resupply.$g$, NULL::text),
  ($c$locations$c$, $t$Edermath Orchard$t$, $g$Daran gives the Old Owl Well quest and knows the Redbrand safe house is under Tresendar Manor. Farmers like Daran may let the party sleep in a hayloft.$g$, NULL::text),
  ($c$locations$c$, $t$Lionshield Coster$t$, $g$The missing caravan's crates are in Klarg's cave at the Cragmaw Hideout. Returning them (or saying where they are): 50 gp reward and Linene's goodwill.$g$, NULL::text),
  ($c$locations$c$, $t$The Miner's Exchange$t$, $g$Halia is a Zhentarim agent using the Exchange to become the town's real authority.$g$, NULL::text),
  ($c$locations$c$, $t$Alderleaf Farm$t$, $g$Carp's secret tunnel (to Redbrand hideout area R8) and Qelline's pointer to Reidoth both start here.$g$, NULL::text),
  ($c$locations$c$, $t$Shrine of Luck$t$, $g$Garaele's Harper work and the Agatha errand start here.$g$, NULL::text),
  ($c$locations$c$, $t$The Sleeping Giant$t$, $g$The natural place to pick a fight with the Redbrands: four ruffians, who flee when three are down.$g$, NULL::text),
  ($c$locations$c$, $t$Townmaster's Hall$t$, $g$After he recovers, Sildar sets himself up here. Prisoners (Redbrands, later Glasstaff or Nezznar) are held here; unguarded, Nezznar is broken out by Halia.$g$, NULL::text),
  ($c$locations$c$, $t$Tresendar Manor$t$, $g$R1 cellar (cistern hides Glasstaff's escape satchel with a potion of invisibility); R2 barrack, 3 bandits; R3 pit trap; R4 crypt, 6 skeletons (password Illefarn or a scarlet cloak); R5 cells, 3 ruffians, the Dendrars; R6 armoury; R7 storeroom (40 beaver pelts); R8 crevasse cave, Ssarnak the nothic, Thel Dendrar's body, rigged bridge, south tunnel; R9 Nosk and three bugbears, Droop; R10 common room, knucklebones; R11 workshop, Zeond the quasit; R12 Glasstaff. Finishing the hideout: level 3.$g$, NULL::text),
  ($c$locations$c$, $t$Conyberry$t$, $g$Agatha's lair is a few miles along that trail. Old Owl Well is 18 miles south-east.$g$, NULL::text),
  ($c$locations$c$, $t$Agatha's Lair$t$, $g$Rude or threatening visitors get her Horrifying Visage, then a fight. Polite visitors: DC 15 Persuasion (advantage for good roleplay; automatic success with Garaele's jeweled silver comb). She answers ONE question, truthfully; she's a capable diviner and can answer almost anything about the adventure.$g$, NULL::text),
  ($c$locations$c$, $t$Old Owl Well$t$, $g$A Red Wizard, Hamun Kost, camps in a tent beside the tower; twelve zombies lurk inside the tower shell (DC 15 Perception smells them). Treasure in his tent includes the Netherese green-glass ring of protection.$g$, NULL::text),
  ($c$locations$c$, $t$Thundertree$t$, $g$Areas: U1–U2 twig blights; U3 Brown Horse, 6 ash zombies; U4 Reidoth's watch post (she placed the sign); U5 blight thicket; U6 ruined store, 2 giant spiders, dead elf adventurer (+1 leather armour); U7 tower, Venomfang; U8 smithy, 4 ash zombies, brass dragon scales (75 gp); U9 Dendrar herb and alchemy shop, emerald necklace; U10 square, statue of Palien; U11 garrison, 5 ash zombies; U12 blights; U13 Favric's dragon cultists. About 50 miles north-west of Phandalin.$g$, NULL::text),
  ($c$locations$c$, $t$Wyvern Tor$t$, $g$Finding the hidden camp: DC 15 Perception or DC 10 Survival per hour. A lone bugbear sentry; in the cave, Brughor Axe-Biter (orc, 18 hp), four bugbears and the ogre Gog. Gog fights to the death; the rest flee if Brughor dies. Plunder from homesteads further north (180 sp, 15 ep, perfume). Clearing it pays Harbin's 100 gp and satisfies Hamun Kost. Eve seed (ours): giants are pushing everything below them out of the hills.$g$, NULL::text),
  ($c$locations$c$, $t$Neverwinter Wood$t$, $g$Contains Cragmaw Castle (about twenty miles north-east of the Cragmaw Hideout) and borders Thundertree. Reidoth knows it better than anyone.$g$, NULL::text),
  ($c$locations$c$, $t$Cragmaw Castle$t$, $g$C1–C2 entrance and tripwire cave-in (DC 20 to spot); C3 archer goblin bosses; C4 goblins; C5 storeroom (dwarven brandy, Sildar's gear); C6 hobgoblins (plan to oust the bugbears one day); C7 Yegg the cook and goblins; C8 dark hall, Lhupo's grick, gold elf statuette (augury once); C9 shrine, Lhupo and acolytes; C10 postern; C11 hidden canvas entrance; C12 hobgoblins loyal to Grol; C13 'haunted' tower is a grell's lair (old library; chest with scroll of revivify); C14 King Grol, Snarl the dire wolf, Vyerith, Gundren. Confronting Grol and learning the mine's location: level 4.$g$, NULL::text),
  ($c$locations$c$, $t$Wave Echo Cave$t$, $g$W1 Rockseeker camp, Tharden dead (cloak of protection); W2 mine tunnels, ochre jelly; W3 old entrance, stirges; W4 dwarf and ogre zombies; W5 assayers' office, pay chest; W6 ghouls; W7 safe storeroom; W8 fungi cavern (violet fungi); W9 great cavern, ghouls; W10 dark pool, giant constrictor snake, dead wizard with wand of magic missiles; W11 six bugbears behind a barricade; W12 smelter, dwarf zombies and the flameskull; W13 starry cavern; W14 Mormesk; W15 Forge of Spells and spectator; W16 booming cavern, giant octopus, underground lake; W17 old streambed (bypasses W12; the Spider hasn't found it); W18 collapsed cavern, Vhalak and bugbears digging (gauntlets of ogre power in the rift); W19 temple of Dumathoin, Nezznar (emerald eyes on the statue: prying one out can bring the room down); W20 Nundro. Defeating Nezznar: level 5. Eve seeds (ours): the Vonindod fragment, and the Act I cliffhanger.$g$, NULL::text),
  ($c$locations$c$, $t$The Sword Mountains$t$, $g$Wave Echo Cave lies in their deep vales; Wyvern Tor in the hills to their north-east.$g$, NULL::text),
  ($c$locations$c$, $t$The Long Road$t$, $g$Eve seed (ours), via Toblen's cousin: fire giants on the Long Road, one 'swinging a rod like a dowser': Okssort and Ildmane tracking a buried Vonindod fragment toward Triboar. In SKT ch. 3, Xantharl's Keep stands on its loneliest stretch.$g$, NULL::text),
  ($c$locations$c$, $t$Triboar$t$, $g$Act II opens here (SKT ch. 2, level 5). The fire giants Okssort and Ildmane attack from the north-east with orogs, orcs on axe beaks and magmins, looking for the Vonindod fragment buried under the north campground. If either giant drops to 81 hit points or fewer, both retreat. Each player can run one Triboar NPC during the battle, and every NPC who survives offers a quest. Defending the town earns level 6.$g$, NULL::text),
  ($c$locations$c$, $t$Moongleam Tower$t$, $g$Darathra's quest ends here: her badge goes to Dral Thelev at Danivarr's House in Everlund, whose elven wine teleports the drinker into the tower's parlour (full of harmless tressym). Krowen gives the party free use of the Harper teleportation circles 'until the Harpers decide otherwise', which is the cure for chapter 3's travel.$g$, NULL::text),
  ($c$locations$c$, $t$The Harper Teleportation Circles$t$, $g$Each circle has a Harper mage ready to cast teleportation circle. Everlund's is in Moongleam Tower (a brusque day apprentice, a sleepy night one); Loudwater's is in the cellar of the Smiling Satyr tavern, whose mage Revil Slombarr is out half the time. Krowen gives the party a sheet with all six sigil addresses.$g$, NULL::text),
  ($c$locations$c$, $t$Yartar$t$, $g$Twice important. Urgala's quest leads here through the thieves' guild, the Hand of Yartar. In SKT ch. 11, Lord Khaspere Drylund's gambling riverboat, the Grand Dame, is moored here. Planting Yartar early (guide thread) makes ch. 11 feel earned. One of the six Harper circles is here.$g$, NULL::text),
  ($c$locations$c$, $t$Zymorven Hall$t$, $g$Lord Harthos Zymorven's home; the suits of armour in its halls aren't all empty decoration. He reports that his disowned son Harthal stole the giant slayer greatsword after marrying a thief from Yartar.$g$, NULL::text),
  ($c$locations$c$, $t$Noanar's Hold$t$, $g$Narth Tezrin's harness delivery ends at the keep with castellan Amrath Mulnobar. The real story is at the White Hart Inn: three noble brothers from Neverwinter, Rantharl, Marthun and Lezryk Daerivoss, ride out to hunt hill giants, which leads into a murder mystery over a 10,000 gp inheritance. Old rumours say the hold's five Hunt Lords let guests hunt one another.$g$, NULL::text),
  ($c$locations$c$, $t$Xantharl's Keep$t$, $g$Darz Helgar's lead: a merchant saw a dwarf cleaning stables here who matches the wanted poster for the brigand called the Weevil. Deliver him alive to the authorities in Mirabar (the Axe of Mirabar) for 5,000 gp.$g$, NULL::text),
  ($c$locations$c$, $t$Silverymoon$t$, $g$Othovir's quest: the Margaster family's emergency stash is hidden under the seat of a carriage in their carriage house, guarded by two cambions disguised as human guards, with an alarm that brings Xamlyn Margaster from the tower. Act III link: Alustriel herself is Eve of Ruin's patron in Sigil.$g$, NULL::text),
  ($c$locations$c$, $t$Citadel Felbarr$t$, $g$Ghelryn Foehammer's letter of recommendation, shown here, earns two figurines of wondrous power (golden lions) for the war on giants.$g$, NULL::text),
  ($c$locations$c$, $t$Waterdeep$t$, $g$Harshnag counts it as his home and walks right in. Optional quest endings here: the Roaringhorn villa (Sirac), Captain Osk Thunderhale at the Hanging Lantern (Duvessa), Chazlauth Yarghorn's tower with a hidden silver wyrmling (Naxene), House Thann's butler Cauldar (Zi Liang). One of the six Harper circles is here.$g$, NULL::text),
  ($c$locations$c$, $t$Calling Horns$t$, $g$Tamalin gives free room and board to adventurers. Her letter of recommendation gets the Hand of Yartar to help with Urgala's quest without the 500 gp fee.$g$, NULL::text),
  ($c$locations$c$, $t$Old Tower$t$, $g$Moog, a heartbroken hill giant, has barricaded herself inside because Chief Guh took her husband, Hruk. Four blood hawks guard the roof. A halfling adventurer, Keltar Dardragon, buried a chest under a cracked floor tile long ago (300 sp and two magic items). Use it as a breather on any road (guide).$g$, NULL::text),
  ($c$locations$c$, $t$Klauthen Vale$t$, $g$The domain of Klauth, 'Old Snarl', the ancient red dragon. He scries on the giants for amusement and keeps Cult of the Dragon members in the vale; in ch. 4 he sends them with an airship as a gift for the party. Visiting the vale itself is suicide at these levels.$g$, NULL::text),
  ($c$locations$c$, $t$Kryptgarden Forest$t$, $g$OPTIONAL cameo (guide): Claugiyliamatar, 'Old Gnawbone', the ancient green dragon, lairs here and rarely meddles with small folk. Her interest in the giants' chaos sets up Klauth in ch. 4.$g$, NULL::text),
  ($c$locations$c$, $t$Eye of the All-Father$t$, $g$SKT ch. 4 (level 7 on arrival). The oracle answers six questions a day, in Giant only. Its key answers: find one of King Hekaton's conchs and 'root out the evil therein'; Mirran and Nym are pawns of Iymrith, 'a blue dragon in the guise of a storm giant'; the conch is 'in the clutches of a giant lord'. It then demands tribute: relics from the Uthgardt spirit mounds, each revealing a lord. Eigeron, a cloud giant ghost, haunts the oracle chamber. On a later visit Iymrith arrives, and Harshnag holds her off (see Harshnag).$g$, NULL::text),
  ($c$locations$c$, $t$Grudd Haug$t$, $g$SKT ch. 5. Chief Guh's lair, crowded with her husbands and with orcs, goblins, hobgoblins and ogres. Her conch of teleportation and some magic items are hidden under her bulk. Wake the whole den before the key threats are down and the party gets swamped. OPTIONAL unless the vote picks Guh.$g$, NULL::text),
  ($c$locations$c$, $t$Deadstone Cleft$t$, $g$SKT ch. 6. Thane Kayalithica's sanctuary, where her stone giants worship Skoraeus Stonebones and carve their deeds for the gods to see. The Blue Bear tribe of Uthgardt camps here as her allies. Her conch is in a pouch on her mithral belt, next to a pouch holding a captive rock gnome clockmaker, Elister Noggins. OPTIONAL unless the vote picks Kayalithica.$g$, NULL::text),
  ($c$locations$c$, $t$Svardborg$t$, $g$SKT ch. 7. When the party arrives, Jarl Storvald is away aboard the Krigvind hunting whales, and he's on his way back. The conch lies on his ice throne. The adult white dragon Isendraug is confined here. The alternative pick if the white-dragon seed landed in Act I (guide).$g$, NULL::text),
  ($c$locations$c$, $t$The Krigvind$t$, $g$Cryovain, an adult white dragon, is chained aboard. Storvald holds him and his mate Isendraug by their eggs. Pays off the Act I seed of a white dragon flying north 'as if called home' (ours).$g$, NULL::text),
  ($c$locations$c$, $t$Ironslag$t$, $g$SKT ch. 8, the guide's recommended lord. Duke Zalto, Duchess Brimskarda, their teenage children Cinderhild and Zaltember, ogres, goblins, hobgoblins, an iron golem and drow of House Xorlarrin. The adamantine forge isn't hot enough to reforge the Vonindod, so Zalto plans to steal Maegera from Gauntlgrym. The yakfolk tend crops for the giants, keep humanoid prisoners and feign hospitality to strangers.$g$, NULL::text),
  ($c$locations$c$, $t$Gauntlgrym$t$, $g$Zalto has given House Xorlarrin an iron flask to steal Maegera and bring it to Ironslag. If it succeeds, Gauntlgrym's forges go cold and Ironslag can remake the Vonindod.$g$, NULL::text),
  ($c$locations$c$, $t$Lyn Armaal$t$, $g$SKT ch. 9. Countess Sansuri's castle, with her castellan Cressaro, her brother Count Thullen, her infant twins Alastrah and Kaaltar, and the bronze dragon Felgolos, imprisoned and tortured for clues to an Ostorian trove. Sansuri gives up the conch to save her life or her children. OPTIONAL unless the vote picks her; the moving cloud with towers seen in Act I is this castle (ours).$g$, NULL::text),
  ($c$locations$c$, $t$Maelstrom$t$, $g$SKT ch. 10 (no level). Princess Serissa rules from the Wyrmskull Throne as regent, advised by Imperator Uthor and the 'storm giant' Iymrith. Representatives of the other giant kinds still attend. Iymrith slips: 'they're the ones who murdered your mother and abducted your father!' Nobody had said 'abducted'. A DC 15 Insight check catches it. Serissa hands over the golden goose chip.$g$, NULL::text),
  ($c$locations$c$, $t$The Grand Dame$t$, $g$SKT ch. 11. The golden goose chip is one of the Grand Dame's. The wizard Pow Ming runs security. Under pressure Drylund reveals Hekaton's prison, the Morkoth, and then Slarkrethel kills him telepathically mid-sentence.$g$, NULL::text),
  ($c$locations$c$, $t$The Morkoth$t$, $g$Captain Tholtz Daggerdark has turned it into a floating prison for King Hekaton; Rool, an orc assassin, is first mate. If the party stays aboard more than an hour after freeing Hekaton, Slarkrethel tears the ship apart. The attempt to free him earns level 10, whatever the outcome.$g$, NULL::text),
  ($c$locations$c$, $t$Iymrith's Lair$t$, $g$SKT ch. 12 (level 11 at the end). The 'statues' are gargoyles. Hekaton (or Serissa, if he died) comes with storm giant warriors riding whales and rocs, and each hero gets a potion of giant size from the royal treasury: tiny heroes growing to giant height to kill a dragon is the payoff of the whole act.$g$, NULL::text),
  ($c$locations$c$, $t$The Purple Rocks$t$, $g$Where worship of Slarkrethel began centuries ago. The islanders live quietly and know nothing of the Kraken Society's spy network on the mainland.$g$, NULL::text),
  ($c$locations$c$, $t$Morgur's Mound$t$, $g$Relic: a gold-plated tooth, which reveals Duke Zalto. The tribe hasn't visited in years.$g$, NULL::text),
  ($c$locations$c$, $t$Raven Rock$t$, $g$Two relics: a magma ring (reveals Zalto) and a bone greatclub (reveals Guh). Giant ravens feast on offerings here at dusk, and Black Raven warriors sometimes ride them.$g$, NULL::text),
  ($c$locations$c$, $t$Great Worm Cavern$t$, $g$Relic: a broken shield, which reveals Jarl Storvald. The ice floor is slippery and the walls can't be climbed without gear.$g$, NULL::text),
  ($c$locations$c$, $t$Stone Stand$t$, $g$Relic: a frost giant skull, which reveals Storvald. The Blue Bears aren't extinct: they visit only at night, and in ch. 6 they're Kayalithica's allies.$g$, NULL::text),
  ($c$locations$c$, $t$Flint Rock$t$, $g$Relic: a mithral spear tip under the altar, which reveals Countess Sansuri.$g$, NULL::text),
  ($c$locations$c$, $t$Shining White$t$, $g$Relic: a porcelain mask, which reveals Sansuri. Three stone giants recently desecrated the mound, knocking over its menhirs and cairns.$g$, NULL::text),
  ($c$locations$c$, $t$Beorunna's Well$t$, $g$Relic: a cracked horn, which reveals Thane Kayalithica. Expect Black Lion or Red Tiger hunting parties on the way.$g$, NULL::text),
  ($c$locations$c$, $t$One Stone$t$, $g$Relic: the magic boulder itself, which reveals Kayalithica.$g$, NULL::text),
  ($c$locations$c$, $t$Grandfather Tree$t$, $g$Relic: an electrum nose-ring, which reveals Chief Guh. Tree Ghost patrols guard the woods around it.$g$, NULL::text),
  ($c$locations$c$, $t$Nightstone$t$, $g$OPTIONAL (SKT ch. 1, levels 1–4; the guide starts Act II at Triboar). Cloud giants bombarded the village and carried off the Nightstone; the survivors fled to the Dripping Caves and goblins took them. High Steward Lady Velrosa Nandar died in the attack. A Zhentarim spy, Kella Darkhope, hides in the Nightstone Inn waiting for the Seven Snakes bandits to seize the village. A good one-shot for a short-handed session at low level.$g$, NULL::text),
  ($c$locations$c$, $t$The Dripping Caves$t$, $g$OPTIONAL (SKT ch. 1). Where Nightstone's survivors were taken. Morak Ur'gray, the innkeeper, is imprisoned here; once rescued he sends the party on to Bryn Shander, Goldenfields or Triboar.$g$, NULL::text),
  ($c$locations$c$, $t$Tower of Zephyros$t$, $g$OPTIONAL (SKT ch. 1). Zephyros, an eccentric cloud giant wizard, gives the party a lift to their chapter 2 town (3 days to Goldenfields, 11½ to Triboar, 26 to Bryn Shander). Useful in this campaign as a deus ex machina for travel, or a breather between giant lords.$g$, NULL::text),
  ($c$locations$c$, $t$Bryn Shander$t$, $g$OPTIONAL (SKT ch. 2). Frost giants attack, hunting Sirac of Suzail, a son of Artus Cimber, guided by Storvald's blood-powered runes. Six townsfolk offer quests if they survive: Augrek Brighthelm, Beldora, Duvessa Shane, Markham Southwell, Sir Baric Nylef and Sirac.$g$, NULL::text),
  ($c$locations$c$, $t$Goldenfields$t$, $g$OPTIONAL (SKT ch. 2). Chief Guh's hill giants attack for food. Six townsfolk offer quests if they survive: Lifferlas the awakened tree, Miros Xelbrin, Naxene Drathkala, Oren Yogilvy, Shalvus Martholio and Zi Liang.$g$, NULL::text),
  ($c$locations$c$, $t$Shadowtop Cathedral$t$, $g$OPTIONAL (Lifferlas's quest). A morose satyr, Greenwhistle, insists the treant Turlang 'will be along any time now'; he arrives on the third night with the druid Tharra Shyndle.$g$, NULL::text),
  ($c$locations$c$, $t$Challidax's Ice Caves$t$, $g$OPTIONAL finale side quest (guide): Dragon Delves ch. 8, 'Shivering Death' (level 11). Frost giant siblings feud inside the adult white dragon Challidax's caves. One more giant story before the cosmic turn. Note it's written for the 2024 rules, which our table uses anyway.$g$, NULL::text),
  ($c$locations$c$, $t$Neverdeath Graveyard$t$, $g$Eve of Ruin ch. 1 (level 10). A Vecna cult works in the catacombs beneath Hallix Mausoleum, draining kidnap victims' secrets and souls for Vecna's ritual. The priests of Oghma's divinations end at the mausoleum and can't see inside. Demons and nothics lurk in the catacombs.$g$, NULL::text),
  ($c$locations$c$, $t$Hallix Mausoleum$t$, $g$The way into the Neverdeath Catacombs, where the cult prepares four kidnap victims for its ritual. Indrina is held in area C20, Sarcelle in C5, Umberto's secret is learned in C11. Disrupting the ritual hurls the party and Eldon Keyward into Evernight.$g$, NULL::text),
  ($c$locations$c$, $t$Evernight$t$, $g$The party arrives here with Eldon and Vecna's Link. To get home they need a Crevice of Dusk, a rift back to Neverwinter, which leads them to the Dolindar family's tomb.$g$, NULL::text),
  ($c$locations$c$, $t$The Corpse Market$t$, $g$The vampire merchant Sangora approaches the party; Eldon blurts out a question about a Crevice of Dusk if they don't. Everyone assumes living visitors have powerful protection.$g$, NULL::text),
  ($c$locations$c$, $t$Dolindar Tomb$t$, $g$The ghost Newmy keeps it tidy. Four of Sangora's vampire spawn follow the party here to make a meal of them behind her back. The way home to Neverwinter is through the lonely legacy of the Dolindar family.$g$, NULL::text),
  ($c$locations$c$, $t$Sigil$t$, $g$Eve of Ruin's home base (guide): use Alustriel's sanctum for the quiet scenes between rod pieces.$g$, NULL::text),
  ($c$locations$c$, $t$Alustriel's Sanctum$t$, $g$Where the botched wish drags the party in ch. 2. The sanctum's portal leads to the general area of each rod piece. Kas steals the rod here in ch. 9 and wounds Alustriel and Tasha. The party can rest here before the final chapter.$g$, NULL::text),
  ($c$locations$c$, $t$Web's Edge$t$, $g$Eve of Ruin ch. 2 (level 11). A secret base of Lolth's cultists. The door is invisible, arcane-locked (DC 22 thieves' tools) and carved with eight symbols with Undercommon letters. Gertrude, sole survivor of an ambushed caravan, is in area W6a. The first rod piece is in W12.$g$, NULL::text),
  ($c$locations$c$, $t$The Astral Sea$t$, $g$Eve of Ruin ch. 3 (level 12). Travellers move by thought (flying speed of 5 × Intelligence in feet). Star anglers, night scavvers and eye mongers hunt here.$g$, NULL::text),
  ($c$locations$c$, $t$Wreck of the Lambent Zenith$t$, $g$Segments joined by arcane portals. Figaro's secret is in area Z8, Ikasa's in Z12. The rod piece the ship carried was swallowed by a hertilod.$g$, NULL::text),
  ($c$locations$c$, $t$The Heart of Havock$t$, $g$The hertilod retreated here with the second rod piece (area A2).$g$, NULL::text),
  ($c$locations$c$, $t$The Mournland$t$, $g$Eve of Ruin ch. 4 (level 13). Magic is unreliable here. Remnants of the Last War litter the land, including fire-spewing colossi, and warforged wander it.$g$, NULL::text),
  ($c$locations$c$, $t$Mount Ironrot$t$, $g$The third rod piece lies somewhere on its slopes. Two camps are here: Mercy's warforged pilgrims and Kalyth's band of veterans, in a dispute. The party needs a docent to tune the rod and find the exact spot.$g$, NULL::text),
  ($c$locations$c$, $t$Landro$t$, $g$The third rod piece is in its graymatter engine (area L28), watched by a graymatter guardian. The Lord of Blades' strike squad is after it too. Taking the piece sets off its self-destruct (guide). Echo of the Vonindod: another colossus (guide).$g$, NULL::text),
  ($c$locations$c$, $t$Barovia$t$, $g$Eve of Ruin ch. 5 (level 14), a Domain of Dread. A mob of frightened peasants meets the party on the way to Death House.$g$, NULL::text),
  ($c$locations$c$, $t$Death House$t$, $g$The Dursts run a small cult devoted to Strahd. The fourth rod piece is in the dungeon (area D38); priests of Osybus and the Strahd cult both want it. Haunted zones throughout. Once the party takes the piece, Strahd arrives to toy with them and block the way out.$g$, NULL::text),
  ($c$locations$c$, $t$Krynn$t$, $g$Eve of Ruin ch. 6 (level 15), in the Northern Dargaard Mountains, where the death knight Lord Soth's forces hold sway.$g$, NULL::text),
  ($c$locations$c$, $t$The Peylon Tree$t$, $g$Where the fifth rod piece rested until Teremini's soldiers stole the shard at its heart. The tree and its dryad, Gazaia, were corrupted afterwards; she's now a deadbark dryad.$g$, NULL::text),
  ($c$locations$c$, $t$Bittergrass Fen$t$, $g$A borthak prowls it. The party meets the Blue Fire Wardens here.$g$, NULL::text),
  ($c$locations$c$, $t$Three Moons Vault$t$, $g$Archmage Teremini Nightsedge holds it for Lord Soth. Her ritual's crimson moonlight warps the rod, which is why the piece's location seems vague. Valendar, leader of the Blue Fire Wardens, is captive in area V7; the fifth piece is in U5 on the upper level. Disrupting the ritual frees the piece.$g$, NULL::text),
  ($c$locations$c$, $t$The Isle of Serpents$t$, $g$Eve of Ruin ch. 7 (level 16). The party arrives as a kraken attacks a crew of archaeologists.$g$, NULL::text),
  ($c$locations$c$, $t$The Tomb of Wayward Souls$t$, $g$Acererak's creation, guarded by Rerak, a false lich. The sixth rod piece is in the crypt vault.$g$, NULL::text),
  ($c$locations$c$, $t$Avernus$t$, $g$Eve of Ruin ch. 8 (level 17). It can't be mapped. The party hitches a ride on an infernal war machine (expect a goristro raid). Tiamat's lair is nearby. No secrets can be learned here: fiends feel no shame.$g$, NULL::text),
  ($c$locations$c$, $t$The Red Belvedere$t$, $g$Hosted by Windfall. Five themed rooms (Alabaster Racetrack, Cerulean Hall, Scarlet Coliseum, Stygian Maze, Viridian Den), each with a pit master, and casino currency. The members-only Dragon's Pride holds the Ruby Sanctum, where the seventh piece sits (area N5).$g$, NULL::text),
  ($c$locations$c$, $t$Pandemonium$t$, $g$Eve of Ruin ch. 9–11. Kas flees here with the rod; Miska's prison, the war between Kas's and Lolth's forces, and Vecna's ritual are all on Pandesmos.$g$, NULL::text),
  ($c$locations$c$, $t$Carapace Ridge$t$, $g$Arriving here earns level 19. Vaeve, a neutral drow mage, offers the party information about the battlefield.$g$, NULL::text),
  ($c$locations$c$, $t$The Ruinous Sea$t$, $g$The war between Kas's demons and Lolth's forces is fought along its coast.$g$, NULL::text),
  ($c$locations$c$, $t$Hurricane Tower$t$, $g$Lolth's forces marshal here: giant spiders and driders, directed by Camlash. It's ready to fall over.$g$, NULL::text),
  ($c$locations$c$, $t$The Ruinous Citadel$t$, $g$Miska the Wolf-Spider's prison, which Kas forced open with the rod. Naxa and her sister are in the vault (area Y4) after a cloak.$g$, NULL::text),
  ($c$locations$c$, $t$The Cliffside Redoubt$t$, $g$Where Kas retreats to plan. One possible place to fight him.$g$, NULL::text),
  ($c$locations$c$, $t$Vecna's Grasp$t$, $g$Eve of Ruin ch. 11 (level 20). Three thresholds lead to demiplanar unrealities, Vecna's drafts of his new multiverse. Dismantle all three (any order) to open the way to the Cave of Shattered Reflection.$g$, NULL::text),
  ($c$locations$c$, $t$Torment of Kas$t$, $g$First unreality (area E2a): in Vecna's new world, Kas suffers forever in his own homeland.$g$, NULL::text),
  ($c$locations$c$, $t$Neverwinter's New King$t$, $g$Second unreality (area E2b), where the crown thread lands (guide). Vecna has made Lord Neverember a loyal death knight and tyrant; servants turned to wights, opponents to dust. If the party shows itself, he orders twelve wights to put them in the gallows and fights only if the wights fall or he's attacked.$g$, NULL::text),
  ($c$locations$c$, $t$Dead Gods$t$, $g$Third unreality (area E2c): Vecna has usurped every other god. A dying astral dreadnought (150 hp left, no Legendary Resistance) is being eaten by six eye mongers; Arekanz's Donjon and the Blue Feather of Habbakuk are here.$g$, NULL::text),
  ($c$locations$c$, $t$The Cave of Shattered Reflection$t$, $g$Vecna weaves his Ritual of Remaking here, alone and weakened by the effort. Unspent secrets help the party here. The end of the campaign.$g$, NULL::text),
  ($c$locations$c$, $t$Tovag$t$, $g$Kas's prison as a vampire. The Chime of Exile can send him back, once he's weakened enough.$g$, NULL::text)
)
INSERT INTO public.the8_lore_entries (campaign_id, category, title, gm_notes, preferred_habitat, is_secret)
SELECT c.id, s.category, s.title, s.gm_notes, s.preferred_habitat, true
FROM seed s CROSS JOIN c
WHERE NOT EXISTS (SELECT 1 FROM public.the8_lore_entries e WHERE e.campaign_id = c.id AND e.title = s.title);
-- blocks: all hidden; only added to entries that have none yet, so your edits are never overwritten
WITH c AS (SELECT id FROM public.campaigns WHERE slug = 'eve-of-giants'),
seed(title, sort_order, body) AS (VALUES
  ($t$Neverwinter$t$, 0, $b$The great city of the north-west coast, where the journey to Phandalin begins.$b$),
  ($t$Neverwinter$t$, 1, $b$Many of Phandalin's new settlers came from here, and Neverwinter is where the town sends its prisoners for real justice.$b$),
  ($t$Neverwinter$t$, 2, $b$People "who knew things" have been going missing in Neverwinter.$b$),
  ($t$Neverwinter$t$, 3, $b$Neverwinter is ruled by its Lord Protector, Dagult Neverember.$b$),
  ($t$The Triboar Trail$t$, 0, $b$An old trail that runs from the town of Triboar in the east, about a hundred miles west through the ruins of Conyberry, then passes north of Phandalin on its way to the High Road along the coast.$b$),
  ($t$The Triboar Trail$t$, 1, $b$The country around it is foothills and sparse plains, between the Sword Mountains to the south and Neverwinter Wood to the north.$b$),
  ($t$The Triboar Trail$t$, 2, $b$Travellers have been attacked on it lately: goblins near the turn-off to Phandalin, and marauders on the eastern stretch near Wyvern Tor.$b$),
  ($t$The Triboar Trail$t$, 3, $b$Someone has put a price on the party's heads. Hobgoblins on the trail carry a crude sketch of one of them, with "25 gold pieces for this one" and a spider scrawled beneath.$b$),
  ($t$The Triboar Trail$t$, 4, $b$At sunset, a cloud with towers on it drifted against the wind.$b$),
  ($t$The Triboar Trail$t$, 5, $b$Days later, a white dragon flew north, fast, as if called home.$b$),
  ($t$The Goblin Ambush$t$, 0, $b$Half a day from Phandalin, on the Triboar Trail, two dead horses lie across the road, shot full of black-feathered arrows.$b$),
  ($t$The Goblin Ambush$t$, 1, $b$They are Gundren Rockseeker's and Sildar Hallwinter's horses. Gundren's saddlebags have been torn open and searched.$b$),
  ($t$The Goblin Ambush$t$, 2, $b$Behind the thickets on the north side, a trail leads north-west: about a dozen goblins have come and gone, dragging two human-sized bodies.$b$),
  ($t$The Goblin Ambush$t$, 3, $b$The trail is trapped: a snare, then a hidden pit.$b$),
  ($t$Cragmaw Hideout$t$, 0, $b$A cave at the foot of a good-sized hill, five miles off the Triboar Trail, with a cold stream running out of its mouth and thickets screening the bank.$b$),
  ($t$Cragmaw Hideout$t$, 1, $b$The goblins who ambushed the trail live here. The caves climb steeply inside the hill, loud with running water.$b$),
  ($t$Cragmaw Hideout$t$, 2, $b$Their leader is a bugbear named Klarg, who answers to a King Grol at Cragmaw Castle.$b$),
  ($t$Cragmaw Hideout$t$, 3, $b$Inside: a kennel of half-trained wolves, a rope bridge over the stream, a den where Sildar Hallwinter was held, and Klarg's cave full of stolen crates marked with a blue lion.$b$),
  ($t$Phandalin$t$, 0, $b$A rough-and-tumble frontier town of farmers, woodcutters, fur traders and prospectors, built over the ruins of a much older settlement in the foothills of the Sword Mountains.$b$),
  ($t$Phandalin$t$, 1, $b$It has no walls and no watch. A townmaster is elected each year, but nobody enforces anything.$b$),
  ($t$Phandalin$t$, 2, $b$A gang in scarlet cloaks, the Redbrands, has the whole town frightened.$b$),
  ($t$Phandalin$t$, 3, $b$Old stone from the ruins is everywhere: in walls, in the shrine, in the foundations of the new houses.$b$),
  ($t$Stonehill Inn$t$, 0, $b$A modest inn in the middle of town, newer than most buildings in Phandalin, with six rooms and a busy common room.$b$),
  ($t$Stonehill Inn$t$, 1, $b$The innkeeper, Toblen Stonehill, is friendly and talkative, and the common room is the best place in town to hear what's going on.$b$),
  ($t$Stonehill Inn$t$, 2, $b$Regulars: Elsa, the dwarf bartender; Freda, a gnome weaver; Lanar, a miner; Narth, a farmer; and Toblen's son Pip.$b$),
  ($t$Barthen's Provisions$t$, 0, $b$The biggest trading post in Phandalin: rope, rations, lanterns, tools and everyday goods, open sunup to sundown.$b$),
  ($t$Barthen's Provisions$t$, 1, $b$It doesn't sell weapons or armour, or anything very expensive. For those, the clerks point people to the Lionshield Coster.$b$),
  ($t$Barthen's Provisions$t$, 2, $b$The owner, Elmina Barthen, is the person the supply wagon from Neverwinter is meant for, and she pays 10 gold pieces a head for its safe delivery.$b$),
  ($t$Edermath Orchard$t$, 0, $b$A tidy little cottage beside an apple orchard that went wild long ago. Its owner is slowly clearing the undergrowth and bringing the trees back.$b$),
  ($t$Edermath Orchard$t$, 1, $b$The owner is Daran Edermath, a retired adventurer.$b$),
  ($t$Lionshield Coster$t$, 0, $b$A trading post with a wooden sign shaped like a shield and painted with a blue lion, run by Linene Graywind.$b$),
  ($t$Lionshield Coster$t$, 1, $b$The Lionshields are a merchant company based in Yartar, more than a hundred miles east. They ship goods to small settlements across the region.$b$),
  ($t$Lionshield Coster$t$, 2, $b$Banditry has hit this post hard. Its latest caravan never arrived.$b$),
  ($t$Lionshield Coster$t$, 3, $b$In a back room, Linene keeps arms and armour for sale, but she won't sell to anyone she thinks is a danger to the town.$b$),
  ($t$The Miner's Exchange$t$, 0, $b$A trading post where local miners have their finds weighed, measured and paid out.$b$),
  ($t$The Miner's Exchange$t$, 1, $b$With no other authority in town, it also keeps the records of claims to streams and diggings around Phandalin. It's the best place to meet people who know the hills.$b$),
  ($t$The Miner's Exchange$t$, 2, $b$Its guild master is Halia Thornton. The Redbrands, who bully everyone else, leave the Exchange alone.$b$),
  ($t$Alderleaf Farm$t$, 0, $b$A farm on the edge of town run by Qelline Alderleaf, a halfling who seems to know everything that goes on in Phandalin.$b$),
  ($t$Alderleaf Farm$t$, 1, $b$She lets travellers sleep in her hayloft if they don't fancy the inn.$b$),
  ($t$Alderleaf Farm$t$, 2, $b$Her son, Carp, plays in the woods near Tresendar Manor.$b$),
  ($t$Shrine of Luck$t$, 0, $b$Phandalin's only temple: a small shrine of stones taken from the old ruins, dedicated to Tymora, goddess of luck.$b$),
  ($t$Shrine of Luck$t$, 1, $b$It is tended by Sister Garaele, a young elf priestess.$b$),
  ($t$The Sleeping Giant$t$, 0, $b$A run-down, dirty and dangerous tap house at the end of Phandalin's main street.$b$),
  ($t$The Sleeping Giant$t$, 1, $b$The Redbrands drink here, and most of the town avoids it.$b$),
  ($t$The Sleeping Giant$t$, 2, $b$It is run by a surly orc named Greska.$b$),
  ($t$Townmaster's Hall$t$, 0, $b$A small hall with a jail of two cells and a notice board beside the door, where the townmaster posts official business.$b$),
  ($t$Townmaster's Hall$t$, 1, $b$One notice offers a contract: marauders have attacked caravans on the Triboar Trail near Wyvern Tor, and the townmaster will pay 100 gold pieces to see them driven off.$b$),
  ($t$Tresendar Manor$t$, 0, $b$More a castle than a house: an ancient, long-abandoned manor on a low hill at the east edge of town, among woods and thickets.$b$),
  ($t$Tresendar Manor$t$, 1, $b$Plenty of tracks lead across the empty grounds to a stone stair beside the ruined kitchen.$b$),
  ($t$Tresendar Manor$t$, 2, $b$Under the manor, the Redbrands have turned the old cellars and the family crypt into their hideout: barracks, cells, an armoury and a wizard's workshop.$b$),
  ($t$Tresendar Manor$t$, 3, $b$A crevasse runs through the caves beneath, and a tunnel leads out to the woods south of the manor.$b$),
  ($t$Tresendar Manor$t$, 4, $b$Prisoners have been held in cells down there and ransomed.$b$),
  ($t$Conyberry$t$, 0, $b$An abandoned village on the Triboar Trail, in ruins for years. Only foundations and chimney stacks remain.$b$),
  ($t$Conyberry$t$, 1, $b$From the ruins, an old trail leads north-west into Neverwinter Wood.$b$),
  ($t$Agatha's Lair$t$, 0, $b$A small, ten-foot shelter in the woods a few miles from Conyberry, where the trees grow close and nothing sings.$b$),
  ($t$Agatha's Lair$t$, 1, $b$A banshee named Agatha lives here. She was beautiful once, and she hasn't forgotten.$b$),
  ($t$Old Owl Well$t$, 0, $b$A ruined watchtower and an adjoining building in the hills south of the Triboar Trail, eighteen miles south-east of Conyberry. Only crumbling walls and the broken stump of the tower remain.$b$),
  ($t$Old Owl Well$t$, 1, $b$The well in its courtyard still gives clean, fresh water.$b$),
  ($t$Old Owl Well$t$, 2, $b$It was built thousands of years ago by a vanished empire, Netheril.$b$),
  ($t$Old Owl Well$t$, 3, $b$Lately prospectors have seen a camp there, and undead guards that chase them off.$b$),
  ($t$Thundertree$t$, 0, $b$A dead village where the Neverwinter River leaves Neverwinter Wood, ruined thirty years ago by the eruption of Mount Hotenow and the zombie plague that followed.$b$),
  ($t$Thundertree$t$, 1, $b$A hand-painted warning sign stands on the road in.$b$),
  ($t$Thundertree$t$, 2, $b$The gardens have grown into twisted thickets, and some of them move. Ash-grey zombies still slump in the shadows of some houses.$b$),
  ($t$Thundertree$t$, 3, $b$Inside, among the ruins: the Brown Horse, an old taproom once famous for its ale; a leaning statue of Palien, an old hero of Neverwinter; the smithy; the old garrison; an herbalist's shop; and a tower on the hill.$b$),
  ($t$Thundertree$t$, 4, $b$A green dragon has taken the old tower.$b$),
  ($t$Thundertree$t$, 5, $b$People in black, winged cloaks and horned masks are hiding in a cottage on the east side of the village.$b$),
  ($t$Wyvern Tor$t$, 0, $b$A crag in the rugged hills north-east of the Sword Mountains, visible for twenty miles. Travellers on the Triboar Trail near Conyberry see it to the south.$b$),
  ($t$Wyvern Tor$t$, 1, $b$Wyverns nested there once, until adventurers dealt with them years ago.$b$),
  ($t$Wyvern Tor$t$, 2, $b$Marauders have been camping somewhere on its slopes for a couple of months, ambushing travellers on the trail.$b$),
  ($t$Wyvern Tor$t$, 3, $b$They are orcs and bugbears, with an ogre among them.$b$),
  ($t$Wyvern Tor$t$, 4, $b$A captured raider says they didn't come to raid: "We didn't come here. We ran here."$b$),
  ($t$Neverwinter Wood$t$, 0, $b$An old, deep forest north and east of Neverwinter, thick enough to swallow roads.$b$),
  ($t$Neverwinter Wood$t$, 1, $b$Goblin bands raid out of it, and somewhere inside stands the ruin the goblins call Cragmaw Castle.$b$),
  ($t$Cragmaw Castle$t$, 0, $b$A ruined castle hidden in Neverwinter Wood, made to look abandoned. The goblins of the Cragmaw tribe use it as their stronghold.$b$),
  ($t$Cragmaw Castle$t$, 1, $b$The goblins didn't build it: a wizard of old Phalorm did, with seven overlapping towers. The upper floors collapsed long ago, and the goblins have propped up the rest with crude timbers.$b$),
  ($t$Cragmaw Castle$t$, 2, $b$King Grol, the bugbear who rules every Cragmaw band, holds court here.$b$),
  ($t$Cragmaw Castle$t$, 3, $b$Inside: archer posts behind arrow slits, a trapped hall, a banquet hall run by a bad-tempered goblin cook, an old chapel to Oghma, Mystra, Lathander and Tymora, and a shrine to a goblin god called the Jagged Tooth.$b$),
  ($t$Cragmaw Castle$t$, 4, $b$The goblins believe one tower is haunted, and keep it boarded up.$b$),
  ($t$Wave Echo Cave$t$, 0, $b$The lost mine of the Phandelver Pact, fifteen miles east of Phandalin in the deep vales of the Sword Mountains. Its entrance is a narrow tunnel hidden in the foothills.$b$),
  ($t$Wave Echo Cave$t$, 1, $b$It's named for the sound of pounding surf that rolls through its deepest caverns.$b$),
  ($t$Wave Echo Cave$t$, 2, $b$The Rockseeker brothers found the entrance a month ago. Their camp is at the mouth of the cave.$b$),
  ($t$Wave Echo Cave$t$, 3, $b$The mine is cold, damp and drafty, overrun with monsters and with the dead of the battle that closed it.$b$),
  ($t$Wave Echo Cave$t$, 4, $b$Deeper in: an assayers' office with Dwarvish records, miners' barracks, a cavern of glowing green fungi, a great smelter with a waterwheel, a starry cavern scarred by spell fire, and a temple of Dumathoin, the dwarven god of mining.$b$),
  ($t$Wave Echo Cave$t$, 5, $b$A giant-sized adamantine plate carved with runes lies beside the Forge of Spells.$b$),
  ($t$Wave Echo Cave$t$, 6, $b$On the night of the victory feast, giants with a glowing rod circled the hills above the cave, found the entrance collapsed, and marched east.$b$),
  ($t$The Sword Mountains$t$, 0, $b$The mountains south and east of Phandalin. Prospectors pan their foothill streams for gold and platinum.$b$),
  ($t$The Long Road$t$, 0, $b$The great road running north from Waterdeep through Triboar to Mirabar. Caravans, patrols and, lately, rumours of giants walking it.$b$),
  ($t$Triboar$t$, 0, $b$A trade town where the Long Road meets the Evermoor Way, full of caravan yards, stables and campgrounds. Its lord protector is Darathra Shendrel.$b$),
  ($t$Moongleam Tower$t$, 0, $b$A wizard's tower in the city of Everlund, home to the archmage Krowen Valharrow.$b$),
  ($t$The Harper Teleportation Circles$t$, 0, $b$A secret network of six teleportation circles kept by Harper wizards, in Everlund, Loudwater, Mirabar, Neverwinter, Waterdeep and Yartar.$b$),
  ($t$Yartar$t$, 0, $b$A fortified, crowded city on the Dessarin River, with a walled citadel on the west bank and a wide stone bridge between. The Evermoor Way runs through its heart.$b$),
  ($t$Zymorven Hall$t$, 0, $b$A keep on a crag above the Rauvin Road, north-west of Silverymoon, with wooden statues of baying wolves on its roof peaks. It seems to have no guards.$b$),
  ($t$Noanar's Hold$t$, 0, $b$A village on the edge of the High Forest that grew around a famous old hunting lodge. Rich nobles once came for its wild hunts; some never came home.$b$),
  ($t$Xantharl's Keep$t$, 0, $b$A fortified village in the middle of nowhere on a rugged stretch of the Long Road: a keep, narrow stone houses, heavy crossbows on the walls, and the Falling Orc inn by the gate.$b$),
  ($t$Silverymoon$t$, 0, $b$The Gem of the North, a city of learning and magic on the Rauvin River, once ruled by the archmage Alustriel Silverhand.$b$),
  ($t$Citadel Felbarr$t$, 0, $b$A dwarven stronghold in the Silver Marches, ruled by King Morinn and Queen Tithmel.$b$),
  ($t$Waterdeep$t$, 0, $b$The City of Splendours, the greatest city on the Sword Coast, where several Act II errands end.$b$),
  ($t$Calling Horns$t$, 0, $b$A trailside inn that grew into a small village after a retired adventurer, Tamalin Zoar, bought it. She is 'the law' here, with nine deputies.$b$),
  ($t$Old Tower$t$, 0, $b$A lonely, half-ruined tower somewhere in the Dessarin Valley. A mournful song booms out of it, loud enough to hear from far away, and red-feathered hawks circle the roof.$b$),
  ($t$Klauthen Vale$t$, 0, $b$A narrow valley in the mountains west of Mirabar that stays warm all year through ancient magic. Herds stolen from across the North graze there among the burned bones of adventurers and orc hordes.$b$),
  ($t$Kryptgarden Forest$t$, 0, $b$A small forest near Westbridge hiding old dwarven ruins and an underground city called Southkrypt. Other dragons don't stay there long.$b$),
  ($t$Eye of the All-Father$t$, 0, $b$An ancient giant temple hidden under the Spine of the World. Giant legend says an oracle of the All-Father speaks there.$b$),
  ($t$Grudd Haug$t$, 0, $b$A hill giant den on a branch of the Dessarin River, in the hills north-east of Goldenfields. It smells of rot and roast meat from a mile away.$b$),
  ($t$Deadstone Cleft$t$, 0, $b$A remote canyon in the Graypeak Mountains, north-east of Llorkh, whose walls are carved with fresh images of destruction.$b$),
  ($t$Svardborg$t$, 0, $b$An ancient frost giant fortress of lodges and longships locked inside an iceberg in the Sea of Moving Ice.$b$),
  ($t$The Krigvind$t$, 0, $b$Jarl Storvald's flagship, a gigantic longship freed from the ice of Svardborg.$b$),
  ($t$Ironslag$t$, 0, $b$An ancient fire giant forge-fortress beneath the Ice Spires, north of the Silver Marches. A yakfolk village clings to the mountainside above it.$b$),
  ($t$Gauntlgrym$t$, 0, $b$An ancient dwarven fortress-city underground near Neverwinter, retaken by King Bruenor Battlehammer from the drow. Its forges burn with the trapped fire primordial Maegera.$b$),
  ($t$Lyn Armaal$t$, 0, $b$A cloud giant castle drifting through the sky, by default about a mile above the Evermoors. Terrible roars echo from it for miles.$b$),
  ($t$Maelstrom$t$, 0, $b$King Hekaton's citadel deep in the Trackless Sea, at the bottom of an enormous whirlpool. Giants of every kind once paid court here.$b$),
  ($t$The Grand Dame$t$, 0, $b$A gambling riverboat moored at Yartar, owned by Lord Khaspere Drylund. Wealthy guests, card tables, and very attentive security.$b$),
  ($t$The Morkoth$t$, 0, $b$A ship that sails the islands of the Trackless Sea and can't be found by scrying.$b$),
  ($t$Iymrith's Lair$t$, 0, $b$A ruined amphitheatre in the desert of Anauroch, watched over by stone statues.$b$),
  ($t$The Purple Rocks$t$, 0, $b$A cluster of islands in the Trackless Sea whose people cast their children into the sea as offerings. Years later the children walk back out, grown, with fishlike features.$b$),
  ($t$Morgur's Mound$t$, 0, $b$The spirit mound of the lost Thunderbeast tribe of Uthgardt, in the Crags: a mound shaped like a long-necked, wingless dragon with real dragon bones jutting from its ridge.$b$),
  ($t$Raven Rock$t$, 0, $b$The spirit mound of the Black Raven and Gray Wolf tribes, on the icy slopes of the Spine of the World, crowned by a 100-foot stone raven facing west.$b$),
  ($t$Great Worm Cavern$t$, 0, $b$The Great Worm tribe's spirit mound, an ice-glazed cavern at the north-east end of the Valley of Khedrun, deep in the Spine of the World.$b$),
  ($t$Stone Stand$t$, 0, $b$A lonely hill north of the High Forest, crowned by a huge oak grown from a branch of the Grandfather Tree. Folk say it's haunted and the Blue Bear tribe is extinct.$b$),
  ($t$Flint Rock$t$, 0, $b$The Elk tribe's spirit mound, a fog-shrouded knob of flinty stone in the Evermoors.$b$),
  ($t$Shining White$t$, 0, $b$The Griffon tribe's spirit mound on a hill south of the Lurkwood, named for a 280-foot spire of white chalk visible for miles.$b$),
  ($t$Beorunna's Well$t$, 0, $b$The spirit mound of the Black Lion and Red Tiger tribes in the Druarwood: an ice-cold cavern open to the sky, with a hot pool and a geyser where the hero Beorunna fell fighting a demon.$b$),
  ($t$One Stone$t$, 0, $b$The Sky Pony tribe's spirit mound in an oak grove of the Moonwood, shaped like a pegasus when seen from the air. A great engraved boulder forms its eye.$b$),
  ($t$Grandfather Tree$t$, 0, $b$An oak of immense size deep in the High Forest, over 350 feet tall, ringed by raised earth and the bones of the Tree Ghost tribe.$b$),
  ($t$Nightstone$t$, 0, $b$A fortified village a few miles south of the Ardeep Forest, between Waterdeep and Daggerford. Its stone obelisk, the Nightstone, gave the place its name.$b$),
  ($t$The Dripping Caves$t$, 0, $b$A damp cave complex north of Nightstone, home to goblins and worse.$b$),
  ($t$Tower of Zephyros$t$, 0, $b$A wizard's tower that sits on a cloud and flies.$b$),
  ($t$Bryn Shander$t$, 0, $b$The largest of the Ten-Towns of Icewind Dale, in the frozen far north.$b$),
  ($t$Goldenfields$t$, 0, $b$A huge walled temple-farm north of Waterdeep that feeds much of the city, run by the Harvesthome Abbey of Chauntea.$b$),
  ($t$Shadowtop Cathedral$t$, 0, $b$A grove of enormous trees in the High Forest whose canopy forms a natural cathedral.$b$),
  ($t$Challidax's Ice Caves$t$, 0, $b$Ice caves where a white dragon lairs among quarrelling frost giants.$b$),
  ($t$Neverdeath Graveyard$t$, 0, $b$Neverwinter's sprawling, walled graveyard, where the dead don't always stay quiet. Gravediggers work in pairs.$b$),
  ($t$Hallix Mausoleum$t$, 0, $b$A mausoleum in Neverdeath Graveyard where divination magic goes blind.$b$),
  ($t$Evernight$t$, 0, $b$A gloomy, dead reflection of Neverwinter in the Shadowfell, where the undead keep shops and the living are a curiosity.$b$),
  ($t$The Corpse Market$t$, 0, $b$A market in Evernight where the merchants and customers are mostly dead.$b$),
  ($t$Dolindar Tomb$t$, 0, $b$A lonely family tomb in Evernight, its portico swept clean.$b$),
  ($t$Sigil$t$, 0, $b$The City of Doors, a ring-shaped city at the centre of the multiverse with portals to everywhere.$b$),
  ($t$Alustriel's Sanctum$t$, 0, $b$A secret refuge in Sigil kept by the archmage Alustriel Silverhand, full of books, comforts and a portal that opens onto other worlds.$b$),
  ($t$Web's Edge$t$, 0, $b$A hidden haven deep in the Underdark, behind an invisible iron door carved with tiny symbols.$b$),
  ($t$The Astral Sea$t$, 0, $b$The silvery void of the Astral Plane, where time has no meaning, gods drift dead, and spelljammers sail between worlds.$b$),
  ($t$Wreck of the Lambent Zenith$t$, 0, $b$The scattered wreck of a spelljamming ship that crashed into the body of a dead god adrift in the Astral Sea.$b$),
  ($t$The Heart of Havock$t$, 0, $b$The heart of a dead god's body, still faintly pulsing.$b$),
  ($t$The Mournland$t$, 0, $b$A magical wasteland on the continent of Khorvaire, on the world of Eberron. Once it was the nation of Cyre, until the Day of Mourning ended it in a single day.$b$),
  ($t$Mount Ironrot$t$, 0, $b$A mountain in the Mournland whose slopes are scattered with war wreckage.$b$),
  ($t$Landro$t$, 0, $b$An enormous, deactivated colossus from the Last War, lying on Mount Ironrot.$b$),
  ($t$Barovia$t$, 0, $b$A grey, misty valley ruled by a vampire count, Strahd von Zarovich. Nobody leaves without his leave.$b$),
  ($t$Death House$t$, 0, $b$A tall, narrow old house in the village of Barovia, owned by Gustav and Elisabeth Durst.$b$),
  ($t$Krynn$t$, 0, $b$A war-torn world of knights, dragons and three moons.$b$),
  ($t$The Peylon Tree$t$, 0, $b$A gigantic magical tree in the Northern Dargaard Mountains, now withered and wrong.$b$),
  ($t$Bittergrass Fen$t$, 0, $b$A cold mountain fen where something huge and wolflike hunts.$b$),
  ($t$Three Moons Vault$t$, 0, $b$A heavily fortified keep in the mountains of Krynn, bathed in crimson moonlight.$b$),
  ($t$The Isle of Serpents$t$, 0, $b$A tropical island chain on the world of Oerth.$b$),
  ($t$The Tomb of Wayward Souls$t$, 0, $b$A labyrinth of deadly traps on the Isle of Serpents, built to lure treasure-seekers to their deaths.$b$),
  ($t$Avernus$t$, 0, $b$The first layer of the Nine Hells: a burning wasteland of war machines, fiends and ruin.$b$),
  ($t$The Red Belvedere$t$, 0, $b$A lavish casino in Avernus dedicated to Tiamat, Queen of Evil Dragons.$b$),
  ($t$Pandemonium$t$, 0, $b$A plane of howling winds and endless dark tunnels, where madness comes easily. Its first layer is called Pandesmos.$b$),
  ($t$Carapace Ridge$t$, 0, $b$A low dip in a cliff on Pandesmos, giving access to a beach below. A war rages on the shore.$b$),
  ($t$The Ruinous Sea$t$, 0, $b$An ocean of swirling, impassable, chaotic magic on Pandesmos.$b$),
  ($t$Hurricane Tower$t$, 0, $b$A tottering tower on Pandesmos, held upright only by the webbing inside its base.$b$),
  ($t$The Ruinous Citadel$t$, 0, $b$A citadel beside the Ruinous Sea where something enormous is breaking free.$b$),
  ($t$The Cliffside Redoubt$t$, 0, $b$A fortified hollow in the cliffs of Pandesmos.$b$),
  ($t$Vecna's Grasp$t$, 0, $b$A small cave network on Pandesmos, its walls opening onto places that shouldn't exist.$b$),
  ($t$Torment of Kas$t$, 0, $b$A hellscape version of Keoland on Oerth, with the ruin of a castle in the distance.$b$),
  ($t$Neverwinter's New King$t$, 0, $b$Neverwinter's square, but wrong: a gallows below a balcony, and wights standing guard.$b$),
  ($t$Dead Gods$t$, 0, $b$An Astral Sea strewn with the bones of gods.$b$),
  ($t$The Cave of Shattered Reflection$t$, 0, $b$A crystal-filled cave deep beneath Pandesmos, the one from the visions.$b$),
  ($t$Tovag$t$, 0, $b$A Domain of Dread in the Shadowfell, bordered by mists.$b$)
)
INSERT INTO public.the8_reveal_blocks (campaign_id, lore_entry_id, body, is_revealed, sort_order)
SELECT c.id, e.id, s.body, false, s.sort_order
FROM seed s CROSS JOIN c
JOIN public.the8_lore_entries e ON e.campaign_id = c.id AND e.title = s.title
WHERE NOT EXISTS (SELECT 1 FROM public.the8_reveal_blocks b WHERE b.lore_entry_id = e.id);

-- ---------------------------------------------------------------------------
-- 3. FACTIONS  (32 entries, 50 blocks)
-- ---------------------------------------------------------------------------
WITH c AS (SELECT id FROM public.campaigns WHERE slug = 'eve-of-giants'),
seed(category, title, gm_notes, preferred_habitat) AS (VALUES
  ($c$factions$c$, $t$The Cragmaw Tribe$t$, $g$Klarg runs the hideout band, Yeemik wants Klarg's job, the hobgoblins at the castle want the bugbears gone. Captured Cragmaws can give directions to the castle. (PaB's 'strange goblins' are chapter 5+ material and left out.)$g$, NULL::text),
  ($c$factions$c$, $t$The Redbrands$t$, $g$Iarno Albrek (Glasstaff) founded them. What captured Redbrands know: Glasstaff runs things from under the manor, there are bugbears and a monster in the caves, and the boss takes orders from someone else.$g$, NULL::text),
  ($c$factions$c$, $t$The Lords' Alliance$t$, $g$Sildar wants Phandalin safe and prosperous and the mine back in production. Glasstaff met the Spider through his Alliance contacts; no other Alliance member knows he turned. Eve thread (ours): in Act II Iymrith frames this same Alliance for Queen Neri's murder, and its leaders pay 200–500 gp per giant head. In Act III its Neverwinter lord, Dagult Neverember, turns out to sit on a borrowed crown.$g$, NULL::text),
  ($c$factions$c$, $t$The Harpers$t$, $g$The Agatha errand is a Harper operation: they're hunting Bowgentle's spellbook. Eve: in Act II, Darathra Shendrel of Triboar is a secret Harper, and Krowen Valharrow of Moongleam Tower gives the party the Harper teleportation circles.$g$, NULL::text),
  ($c$factions$c$, $t$The Zhentarim$t$, $g$Halia wants Glasstaff removed so she can take the Redbrands over. If Nezznar is jailed in Phandalin without a guard, she breaks him out and hands him to her Zhentarim superiors. Eve: in Act II the Black Network is all over the North (Kella Darkhope, Shalvus Martholio, the Daggerford loan sharks) and would happily bribe the giants to keep trade moving.$g$, NULL::text),
  ($c$factions$c$, $t$The Order of the Gauntlet$t$, $g$Eve: knights of the order hunt giants across the North in Act II (Sir Baric Nylef, Sir Lanniver Strayl).$g$, NULL::text),
  ($c$factions$c$, $t$The Emerald Enclave$t$, $g$Because of the Enclave's principles, Reidoth won't rile the goblins without good cause. Eve: furious about hill giants razing forests in Act II; Lifferlas and the treant Turlang are Enclave-aligned.$g$, NULL::text),
  ($c$factions$c$, $t$The Cult of the Dragon$t$, $g$Favric leads them; the others don't share his ambition and flee if he's taken. Eve: returns in Act II as the crew of Klauth's airship (eight cultists under Delsephine).$g$, NULL::text),
  ($c$factions$c$, $t$The Red Wizards of Thay$t$, $g$DC 15 History identifies Thayan garb; DC 10 Arcana reads Hamun's tattoo as necromantic.$g$, NULL::text),
  ($c$factions$c$, $t$The Rockseeker Brothers$t$, $g$Tharden is dead at the camp; Nundro is a prisoner in the temple of Dumathoin's priests' quarters (W20). Afterwards, Gundren and Nundro run the mine and give the party a 10% share.$g$, NULL::text),
  ($c$factions$c$, $t$The Scraptops$t$, $g$Droop's clan. The Cragmaws are pressuring him to join them.$g$, NULL::text),
  ($c$factions$c$, $t$The Court of King Hekaton$t$, $g$Serissa is regent, Uthor commands the garrison, and the elder princesses Mirran and Nym plot with Iymrith. Winning this court over is the goal of SKT ch. 10–12, and its alliance with the small folk is the campaign's answer to the shattered ordning.$g$, NULL::text),
  ($c$factions$c$, $t$The Kraken Society$t$, $g$Only its leaders know their founder is Slarkrethel, a spellcasting kraken that lures outcasts and lost souls to it by telepathy. It wants to rekindle the giant–dragon war and drown the Sword Coast's cities. It killed Queen Neri and holds Hekaton aboard the Morkoth for Iymrith. Known members: Tholtz Daggerdark, Lord Khaspere Drylund, Rool.$g$, NULL::text),
  ($c$factions$c$, $t$The Hill Giants of Grudd Haug$t$, $g$Chief Guh's tribe. Her husbands bring her every scrap of food they can carry so she can grow to immense size; they attack Goldenfields (OPTIONAL) and raid the farms near Triboar (the Act I seed via Daran, ours).$g$, NULL::text),
  ($c$factions$c$, $t$The Stone Giants of Deadstone Cleft$t$, $g$Thane Kayalithica's clan, convinced the small folk's towns corrupt the 'dream world' because they're built on Ostoria's bones. Allied with the Blue Bear Uthgardt.$g$, NULL::text),
  ($c$factions$c$, $t$The Frost Giants of Svardborg$t$, $g$Jarl Storvald's people, hunting the Ring of Winter. They hold two adult white dragons hostage through their eggs.$g$, NULL::text),
  ($c$factions$c$, $t$The Fire Giants of Ironslag$t$, $g$Duke Zalto's household and minions, searching for Vonindod fragments with rods that pull toward them. Okssort and Ildmane lead the Triboar attack.$g$, NULL::text),
  ($c$factions$c$, $t$The Cloud Giants of Lyn Armaal$t$, $g$Countess Sansuri's court, hunting Ostorian ruins for the lost trove of dragon magic.$g$, NULL::text),
  ($c$factions$c$, $t$House Xorlarrin$t$, $g$Zalto's allies: they know Gauntlgrym's layout and carry his iron flask to steal Maegera. Some are present at Ironslag.$g$, NULL::text),
  ($c$factions$c$, $t$The Uthgardt$t$, $g$The oracle's relics are buried under their mounds, so plundering them means trouble with the tribes (Harshnag warns the party). Tribes named in the book: Black Lion, Black Raven, Blue Bear, Elk, Gray Wolf, Great Worm, Griffon, Red Tiger, Sky Pony, Thunderbeast and Tree Ghost.$g$, NULL::text),
  ($c$factions$c$, $t$The Blue Bear Tribe$t$, $g$They still prowl the High Forest and eastern Delimbiyr Vale in secret, and have sworn allegiance to Thane Kayalithica; many camp in Deadstone Cleft.$g$, NULL::text),
  ($c$factions$c$, $t$The Hand of Yartar$t$, $g$Urgala's quest runs through them: 5 gp to a server at the Wink and Kiss names a member; they want 500 gp up front, or a letter from Tamalin Zoar. They report that Harthal is jailed for murder and the sword is with a corrupt watch captain, Tholzar Brenner.$g$, NULL::text),
  ($c$factions$c$, $t$Force Grey$t$, $g$Harshnag was its largest member. He doesn't like to talk about it.$g$, NULL::text),
  ($c$factions$c$, $t$The Cult of Vecna$t$, $g$Cells across the worlds drain victims' secrets for the Ritual of Remaking. The Neverwinter cell under Neverdeath Graveyard scatters after ch. 1, taking the loose treasure. Seed (ours): a small eye inside an open hand on Mormesk's map in Act I.$g$, NULL::text),
  ($c$factions$c$, $t$The Wizards Three$t$, $g$Really two wizards and an impostor: Kas wears Mordenkainen's face. He secretly lacks the magic, so their wish fails and pulls the party in. The real Mordenkainen is off travelling, unaware.$g$, NULL::text),
  ($c$factions$c$, $t$The Cult of Lolth$t$, $g$Web's Edge is theirs; they ambushed the caravan Gertrude survived. Lolth herself is Vecna's ally, and her forces fight Kas's in Pandesmos under Camlash.$g$, NULL::text),
  ($c$factions$c$, $t$The Lord of Blades' Forces$t$, $g$A cult of personality around the Lord of Blades. His strike squad is after Landro too (ch. 4).$g$, NULL::text),
  ($c$factions$c$, $t$The Ulmist Inquisition$t$, $g$Founded by Ulmed, who once hunted monsters beside a then-mortal Strahd. Sarusanda is one of its inquisitors of the Tome.$g$, NULL::text),
  ($c$factions$c$, $t$The Priests of Osybus$t$, $g$In Death House for the rod piece. Sarusanda's father Galias joined them.$g$, NULL::text),
  ($c$factions$c$, $t$The Blue Fire Wardens$t$, $g$Their attack on Three Moons Vault failed and their leader, Valendar, was captured. Riffel is one of them. They know where the fifth piece really went.$g$, NULL::text),
  ($c$factions$c$, $t$Lord Soth's Forces$t$, $g$Teremini Nightsedge's garrison at Three Moons Vault is part of them.$g$, NULL::text),
  ($c$factions$c$, $t$The Dark Powers$t$, $g$They told Kas of Vecna's plan, gave him the Crown of Lies and let him out of Tovag on his vow to deliver Vecna. If he fails, they take him back.$g$, NULL::text)
)
INSERT INTO public.the8_lore_entries (campaign_id, category, title, gm_notes, preferred_habitat, is_secret)
SELECT c.id, s.category, s.title, s.gm_notes, s.preferred_habitat, true
FROM seed s CROSS JOIN c
WHERE NOT EXISTS (SELECT 1 FROM public.the8_lore_entries e WHERE e.campaign_id = c.id AND e.title = s.title);
-- blocks: all hidden; only added to entries that have none yet, so your edits are never overwritten
WITH c AS (SELECT id FROM public.campaigns WHERE slug = 'eve-of-giants'),
seed(title, sort_order, body) AS (VALUES
  ($t$The Cragmaw Tribe$t$, 0, $b$Goblin raiders who prey on travellers along the Triboar Trail and in Neverwinter Wood. They file their teeth to jagged points to look fiercer.$b$),
  ($t$The Cragmaw Tribe$t$, 1, $b$Several bands answer to one king: King Grol, a bugbear, at Cragmaw Castle.$b$),
  ($t$The Cragmaw Tribe$t$, 2, $b$They're a mix: a handful of bugbears lording it over many miserable goblins and a few hobgoblins, who would like to be in charge.$b$),
  ($t$The Cragmaw Tribe$t$, 3, $b$Someone called the Spider is paying them.$b$),
  ($t$The Redbrands$t$, 0, $b$A gang of ruffians in scarlet cloaks who bully and extort Phandalin.$b$),
  ($t$The Redbrands$t$, 1, $b$They answer to a leader called Glasstaff and drink at the Sleeping Giant.$b$),
  ($t$The Redbrands$t$, 2, $b$Their hideout is under Tresendar Manor.$b$),
  ($t$The Redbrands$t$, 3, $b$They kidnap travellers and hold them for ransom.$b$),
  ($t$The Redbrands$t$, 4, $b$Four bugbears work with them, sent by someone called the Spider.$b$),
  ($t$The Lords' Alliance$t$, 0, $b$A league of cities and towns along the Sword Coast and in the North, working together for mutual security and prosperity. Its agents handle threats before they reach their cities.$b$),
  ($t$The Lords' Alliance$t$, 1, $b$Sildar Hallwinter is one of them. So was Iarno Albrek, who was sent to Phandalin to establish order and then went silent.$b$),
  ($t$The Harpers$t$, 0, $b$A scattered network of spies and adventurers who promote equality and quietly oppose the abuse of power. They gather information across the land and help the weak and the oppressed.$b$),
  ($t$The Harpers$t$, 1, $b$Sister Garaele reports to them.$b$),
  ($t$The Zhentarim$t$, 0, $b$A powerful network that seeks secret control of the North through wealth and influence.$b$),
  ($t$The Zhentarim$t$, 1, $b$Halia Thornton is one of their agents.$b$),
  ($t$The Order of the Gauntlet$t$, 0, $b$A devout and vigilant order that protects people from evildoers: always ready to smite evil, enforce justice and punish those who would harm others.$b$),
  ($t$The Order of the Gauntlet$t$, 1, $b$Daran Edermath is a member, though he's retired.$b$),
  ($t$The Emerald Enclave$t$, 0, $b$A widespread group of wilderness survivalists who preserve the natural order, root out unnatural threats, and help people survive the dangers of the wild.$b$),
  ($t$The Emerald Enclave$t$, 1, $b$Reidoth the druid is a member.$b$),
  ($t$The Cult of the Dragon$t$, 0, $b$A cult that seeks alliances with the powerful dragons of the Sword Coast.$b$),
  ($t$The Cult of the Dragon$t$, 1, $b$A small band of them is hiding in Thundertree, wearing black cloaks cut like dragon wings and black leather masks with horns. They speak Draconic among themselves.$b$),
  ($t$The Cult of the Dragon$t$, 2, $b$They've come to make an offering to the green dragon in the tower.$b$),
  ($t$The Red Wizards of Thay$t$, 0, $b$Necromancers from the land of Thay, far to the east, where wizards tattoo their skin. A Red Wizard's head tattoo marks his school of magic.$b$),
  ($t$The Red Wizards of Thay$t$, 1, $b$One of them, Hamun Kost, is digging at Old Owl Well.$b$),
  ($t$The Rockseeker Brothers$t$, 0, $b$Three dwarf brothers, Gundren, Tharden and Nundro, prospectors with a dream of reopening the lost mine of the Phandelver Pact.$b$),
  ($t$The Rockseeker Brothers$t$, 1, $b$They found the entrance to Wave Echo Cave a month ago.$b$),
  ($t$The Rockseeker Brothers$t$, 2, $b$Tharden and Nundro were camped at the cave mouth and haven't come back to town for supplies.$b$),
  ($t$The Rockseeker Brothers$t$, 3, $b$They were followed. The Spider's spies traced them to the mine.$b$),
  ($t$The Scraptops$t$, 0, $b$A goblin clan known for scavenging and tinkering, not raiding.$b$),
  ($t$The Court of King Hekaton$t$, 0, $b$The storm giants of Maelstrom, who once kept the lesser giants in line from the Wyrmskull Throne. With the king gone, their court is coming apart.$b$),
  ($t$The Kraken Society$t$, 0, $b$A secret network of spies, smugglers, slavers and assassins spread through the cities of the North. Its members don't advertise it.$b$),
  ($t$The Hill Giants of Grudd Haug$t$, 0, $b$Hill giants who have been stripping the farms and orchards of the Dessarin Valley bare for months.$b$),
  ($t$The Stone Giants of Deadstone Cleft$t$, 0, $b$A xenophobic clan of stone giants in the Graypeak Mountains, lately leaving ruined homesteads behind them.$b$),
  ($t$The Frost Giants of Svardborg$t$, 0, $b$Frost giant raiders whose huge longships attack ships along the coast and steal timber from the mainland.$b$),
  ($t$The Fire Giants of Ironslag$t$, 0, $b$Fire giants who round up slaves, burn grassland and dig up the ground across the North.$b$),
  ($t$The Cloud Giants of Lyn Armaal$t$, 0, $b$The aristocratic household of a cloud castle that drifts over the North, mapping the land below.$b$),
  ($t$House Xorlarrin$t$, 0, $b$A drow house that once held Gauntlgrym, until the dwarves drove it out.$b$),
  ($t$The Uthgardt$t$, 0, $b$Barbarian tribes of the North who honour their ancestors at sacred burial mounds. Each tribe guards its own spirit mound.$b$),
  ($t$The Blue Bear Tribe$t$, 0, $b$An Uthgardt tribe everyone believes extinct.$b$),
  ($t$The Hand of Yartar$t$, 0, $b$Yartar's thieves' guild. Its members are 'as common as rats'.$b$),
  ($t$Force Grey$t$, 0, $b$A notoriously destructive adventuring company that has defended Waterdeep more than once.$b$),
  ($t$The Cult of Vecna$t$, 0, $b$A secret cult that worships a god of secrets. Lately its people have been kidnapping citizens of Neverwinter who know things.$b$),
  ($t$The Wizards Three$t$, 0, $b$Alustriel Silverhand, Tasha and Mordenkainen, three of the most powerful wizards in the multiverse, working together against Vecna.$b$),
  ($t$The Cult of Lolth$t$, 0, $b$Worshippers of the Spider Queen, operating in secret havens in the Underdark.$b$),
  ($t$The Lord of Blades' Forces$t$, 0, $b$Warforged who follow the Lord of Blades, a warlord who rose in the Mournland after Eberron's Last War. They call themselves blades.$b$),
  ($t$The Ulmist Inquisition$t$, 0, $b$An order of inquisitors in Barovia who seek the origins of evil in people's hearts.$b$),
  ($t$The Priests of Osybus$t$, 0, $b$Necromancers of Barovia who once worshipped a lich and were betrayed by him. They steal souls to fuel their magic.$b$),
  ($t$The Blue Fire Wardens$t$, 0, $b$Benevolent lycanthropes and trackers on Krynn who oppose Lord Soth and worship the nature god Habbakuk.$b$),
  ($t$Lord Soth's Forces$t$, 0, $b$The armies of the death knight Lord Soth, feared across Krynn.$b$),
  ($t$The Dark Powers$t$, 0, $b$Nameless forces of the Shadowfell that shape the Domains of Dread and imprison their darklords.$b$)
)
INSERT INTO public.the8_reveal_blocks (campaign_id, lore_entry_id, body, is_revealed, sort_order)
SELECT c.id, e.id, s.body, false, s.sort_order
FROM seed s CROSS JOIN c
JOIN public.the8_lore_entries e ON e.campaign_id = c.id AND e.title = s.title
WHERE NOT EXISTS (SELECT 1 FROM public.the8_reveal_blocks b WHERE b.lore_entry_id = e.id);

-- ---------------------------------------------------------------------------
-- 4. FRIENDS (allies, neutrals, and some who only look like allies)  (86 entries, 151 blocks)
-- ---------------------------------------------------------------------------
WITH c AS (SELECT id FROM public.campaigns WHERE slug = 'eve-of-giants'),
seed(category, title, gm_notes, preferred_habitat) AS (VALUES
  ($c$friends$c$, $t$Gundren Rockseeker$t$, $g$Held unconscious (stable at 0 hp) in Grol's quarters at Cragmaw Castle. Vyerith means to question him, then kill him and destroy the map. Ask each player how their character knows Gundren (PaB ch. 1).$g$, NULL::text),
  ($c$friends$c$, $t$Sildar Hallwinter$t$, $g$Found at 1 hp in the Cragmaw Hideout den. Takes a room at the Stonehill Inn, then sets up at the Townmaster's Hall. He doesn't know Iarno is Glasstaff; once he does, he wants Iarno tried in Neverwinter. His gear (longsword with Neverwinter's emblem) is in Cragmaw Castle's storeroom. Eve seeds (ours): Queen Neri's murder, framed on the Lords' Alliance by Iymrith (SKT); the crown thread that pays off with Indrina's secret (Eve of Ruin ch. 1) and 'Neverwinter's New King' (ch. 11). Reveal the second block late in Act I.$g$, NULL::text),
  ($c$friends$c$, $t$Nundro Rockseeker$t$, $g$Locked in W20 (Nezznar has the anvil-headed key). Vhalak the doppelganger may take his shape to force a surrender. Knows no more of the layout than the party.$g$, NULL::text),
  ($c$friends$c$, $t$Tharden Rockseeker$t$, $g$The Spider killed him. He still wears a cloak of protection the Spider overlooked.$g$, NULL::text),
  ($c$friends$c$, $t$Elmina Barthen$t$, $g$Her clerks are Ander and Thistle. If the party skips the goblin trail, Elmina seeks them out and tells them Gundren never arrived.$g$, NULL::text),
  ($c$friends$c$, $t$Ander and Thistle$t$, NULL::text, NULL::text),
  ($c$friends$c$, $t$Toblen Stonehill$t$, $g$Tells the story of Thel Dendrar's murder. Eve seed (ours): Okssort and Ildmane tracking a Vonindod fragment with a rod of the Vonindod (SKT ch. 2).$g$, NULL::text),
  ($c$friends$c$, $t$Trilena Stonehill$t$, NULL::text, NULL::text),
  ($c$friends$c$, $t$Pip Stonehill$t$, NULL::text, NULL::text),
  ($c$friends$c$, $t$Elsa$t$, $g$In PaB she also brags about her sister Gwyn, a scholar in Neverwinter: that thread belongs to chapters 5+ and is left out.$g$, NULL::text),
  ($c$friends$c$, $t$Freda$t$, NULL::text, NULL::text),
  ($c$friends$c$, $t$Lanar$t$, NULL::text, NULL::text),
  ($c$friends$c$, $t$Narth$t$, NULL::text, NULL::text),
  ($c$friends$c$, $t$Linene Graywind$t$, $g$The crates are in Klarg's cave. Eve: SKT Appendix A hook into Act II.$g$, NULL::text),
  ($c$friends$c$, $t$Daran Edermath$t$, $g$Happy to trade news with adventurers who share the order's virtues. (In the 2014 Lost Mine he was a half-elf; PaB makes him a drow, which plays nicely against the Spider.) Eve seed (ours): Chief Guh's husbands stripping the Dessarin farms (SKT ch. 5).$g$, NULL::text),
  ($c$friends$c$, $t$Sister Garaele$t$, $g$Agatha spoke wistfully of the beautiful things she owned in life; the comb makes the Persuasion check automatic.$g$, NULL::text),
  ($c$friends$c$, $t$Qelline Alderleaf$t$, $g$Suggests Reidoth to anyone looking for Cragmaw Castle; gives directions.$g$, NULL::text),
  ($c$friends$c$, $t$Carp Alderleaf$t$, $g$The tunnel leads to area R8 (the crevasse cave).$g$, NULL::text),
  ($c$friends$c$, $t$Reidoth$t$, $g$She gives directions to Cragmaw Castle to people who respect her position, or in exchange for chasing off Venomfang. If attacked, she turns into a grey squirrel and slips away.$g$, NULL::text),
  ($c$friends$c$, $t$Mirna Dendrar$t$, $g$Her children are Nilsa (18) and Nars (13). Thel's body is in the Redbrand crevasse cave (R8). The Dendrars only know the boss is a wizard with 'tall, furry monsters with big ears' working for him.$g$, NULL::text),
  ($c$friends$c$, $t$Nilsa and Nars Dendrar$t$, $g$Held with Mirna in R5.$g$, NULL::text),
  ($c$friends$c$, $t$Droop$t$, $g$Found with Nosk's bugbears in R9. Doesn't remember where Cragmaw Castle is, only that it's up north in the forest.$g$, NULL::text),
  ($c$friends$c$, $t$Halia Thornton$t$, $g$Ruthless, and a valuable patron if not crossed. DC 15 Insight shows ulterior motives. If the party jails Nezznar in Phandalin and doesn't guard him, she breaks him out and delivers him to the Zhentarim.$g$, NULL::text),
  ($c$friends$c$, $t$Harbin Wester$t$, $g$Completely intimidated by the Redbrands. Will keep prisoners in his two cells for a few days; fears retaliation if Redbrands are killed. Eve: SKT Appendix A hook into Act II.$g$, NULL::text),
  ($c$friends$c$, $t$Greska$t$, NULL::text, NULL::text),
  ($c$friends$c$, $t$Agatha$t$, $g$Rude or threatening visitors: Horrifying Visage, then a fight. The name of Old Owl Well's builder, which Hamun Kost wants: Dresina. Eve seed (ours): the shattered ordning, two acts early. Use it whatever question she's asked, if the talk turns to the troubles.$g$, NULL::text),
  ($c$friends$c$, $t$Hamun Kost$t$, $g$Tight-lipped about why he's here: digging for Netherese lore. In return for either favour he'll share what he knows (the location of Cragmaw Castle or Wave Echo Cave). The answer to his question: Dresina. His tent: coin, agates, a potion of healing, a scroll of darkness, and the Netherese green-glass ring of protection in a jeweled box.$g$, NULL::text),
  ($c$friends$c$, $t$Iarno Albrek$t$, $g$Sildar's missing contact. Keep this entry and 'Glasstaff' as two separate entries until the party works it out; then reveal the last block in both.$g$, NULL::text),
  ($c$friends$c$, $t$Darathra Shendrel$t$, $g$A secret Harper. Her quest is the one to push (guide): her platinum badge goes to Dral Thelev in Everlund, which leads to Krowen Valharrow and the Harper teleportation circles. She thinks it odd that fire giants got this deep into the Dessarin Valley without warning. Harbin Wester's rude letter is addressed to her.$g$, NULL::text),
  ($c$friends$c$, $t$Urgala Meltimer$t$, $g$Her quest is the other one to push (guide): her old companion Lord Harthos Zymorven owns a giant slayer greatsword (make it a greataxe if that suits the party better). The trail runs through Yartar, planting the city for SKT ch. 11.$g$, NULL::text),
  ($c$friends$c$, $t$Narth Tezrin$t$, $g$Pays 100 gp to deliver five harnesses to Noanar's Hold and lets the party keep the cart and its horse, Boris. The harnesses are an excuse; the Daerivoss murder mystery is the adventure.$g$, NULL::text),
  ($c$friends$c$, $t$Darz Helgar$t$, $g$Tips the party that the Weevil, a wanted brigand worth 5,000 gp in Mirabar, is cleaning stables at Xantharl's Keep. Good filler (guide).$g$, NULL::text),
  ($c$friends$c$, $t$Othovir$t$, $g$He's related to the Margasters of Silverymoon and despises them; he tells the party about their emergency stash of magic items in a carriage house. He doesn't know the guards are cambions.$g$, NULL::text),
  ($c$friends$c$, $t$Ghelryn Foehammer$t$, $g$Writes a letter of recommendation to the king and queen of Citadel Felbarr, worth two figurines of wondrous power (golden lions).$g$, NULL::text),
  ($c$friends$c$, $t$Krowen Valharrow$t$, $g$Harper. He grants free use of the six teleportation circles and gives a coffer Darathra once sent him for his birthday. He suspects the dragons are somehow behind the giants' uprising.$g$, NULL::text),
  ($c$friends$c$, $t$Dral Thelev$t$, $g$Harper contact. He pockets Darathra's badge and pours an elven wine that teleports whoever drinks it to Moongleam Tower.$g$, NULL::text),
  ($c$friends$c$, $t$Lord Harthos Zymorven$t$, $g$Urgala's old companion. Sadly reports that his disowned son Harthal stole the giant slayer.$g$, NULL::text),
  ($c$friends$c$, $t$Tamalin Zoar$t$, $g$Gives adventurers free room and board, and a letter that opens doors with the Hand of Yartar.$g$, NULL::text),
  ($c$friends$c$, $t$Harshnag the Grim$t$, $g$Chaotic good, centuries old, once of Force Grey. He hunts evil giants and seeks adventurers who'll do the same. The steering wheel of Act II (guide): bring him in when chapter 3 drifts. He leads the party to the Eye of the All-Father. On the second visit Iymrith arrives; he charges her and shouts for the party to run, and if they won't leave he chips Annam's statue and brings the temple down on giant and dragon. Play it big. Gurt's greataxe; 204 hp, AC 21.$g$, NULL::text),
  ($c$friends$c$, $t$Moog$t$, $g$Chief Guh took her husband, Hruk. Calm words in Giant (DC 12 Persuasion, advantage with food) win her over; promise to reunite them and she'll guide the party to Grudd Haug, though she won't attack other hill giants. She's chaotic evil and forgets the party every time she sleeps.$g$, NULL::text),
  ($c$friends$c$, $t$Princess Serissa$t$, $g$Like her mother, she believes in the small folk and wants to use them to find her father, against her advisers' counsel. She holds the Korolnor Scepter. She suspects her sisters envy her, never that they killed their mother. Gives the party the golden goose chip.$g$, NULL::text),
  ($c$friends$c$, $t$King Hekaton$t$, $g$Distrustful of small folk, and lately convinced the age of giants is over. Chained aboard the Morkoth (SKT ch. 11). Once freed, he leads the strike on Iymrith and swears an alliance between storm giants and small folk against dragons.$g$, NULL::text),
  ($c$friends$c$, $t$Imperator Uthor$t$, $g$Loyal to Serissa but wary: he wrongly believes an alliance with small folk would anger Annam further. He found Neri's body.$g$, NULL::text),
  ($c$friends$c$, $t$Klauth$t$, $g$Not a friend; never trust him (guide). He wants the giants fought, so he gifts the party an airship crewed by Cult of the Dragon members. Afterwards he watches and waits.$g$, NULL::text),
  ($c$friends$c$, $t$Delsephine$t$, $g$Cult of the Dragon, serving Klauth. Her crew: Nyzroth, Brassik, Laz, Oriskus, Perella, Tralt and Zalthia, humourless but resolute. They'll fly the party anywhere; a character who watches them a full day can learn to crew the ship (DC 15 Intelligence).$g$, NULL::text),
  ($c$friends$c$, $t$Felgolos$t$, $g$Imprisoned and tortured by Countess Sansuri for clues to the Ostorian trove. A natural ally if freed.$g$, NULL::text),
  ($c$friends$c$, $t$Eigeron$t$, $g$Knows that relics are offered by placing them in the oracle chamber's mithral circle.$g$, NULL::text),
  ($c$friends$c$, $t$Cinderhild$t$, $g$She feels like a prisoner and wants to see the world. She'll pretend to be the party's hostage to force her father's hand, then asks to be released once far enough away, gives her fire opal pendant and keeps her word.$g$, NULL::text),
  ($c$friends$c$, $t$Elister Noggins$t$, $g$Carried in one of Kayalithica's belt pouches as a captive. Rescue optional, gratitude guaranteed.$g$, NULL::text),
  ($c$friends$c$, $t$Hekaton's Storm Giant Hunters$t$, $g$Sent to kill Iymrith in SKT ch. 12; they fight beside the party in Anauroch.$g$, NULL::text),
  ($c$friends$c$, $t$Lord Dagult Neverember$t$, $g$Act II → III bridge: grateful to the heroes who saved the North, he hires them in Eve of Ruin ch. 1. His claim to descend from one of Neverwinter's past heroes is tenuous, and Indrina knows it isn't legitimate. Crown thread (ours): his agents quietly deal with old-line claimants. In Vecna's 'Neverwinter's New King' unreality he's a death knight tyrant.$g$, NULL::text),
  ($c$friends$c$, $t$Morak Ur'gray$t$, $g$OPTIONAL (SKT ch. 1). Held in the Dripping Caves. Once home, he sends the party to Bryn Shander, Goldenfields or Triboar.$g$, NULL::text),
  ($c$friends$c$, $t$Zephyros$t$, $g$OPTIONAL (SKT ch. 1). Friendly, absent-minded, and happy to give travellers a lift.$g$, NULL::text),
  ($c$friends$c$, $t$Augrek Brighthelm$t$, $g$OPTIONAL. Asks the party to seek reinforcements from her clan in Ironmaster; her cousin Gwert pays each courier a 100 gp gem and suggests griffon training in Fireshear.$g$, NULL::text),
  ($c$friends$c$, $t$Beldora$t$, $g$OPTIONAL. Harper spy. Sends the party to the gnome Thwip Ironbottom in Hundelstone (a clockwork dog), who points them at Krowen Valharrow.$g$, NULL::text),
  ($c$friends$c$, $t$Duvessa Shane$t$, $g$OPTIONAL. Writes to her aunt, Captain Inirva Coldwater of the Dancing Wave, for passage. The ship is missing, and the trail leads to a fight with privateer Osk Thunderhale in Waterdeep.$g$, NULL::text),
  ($c$friends$c$, $t$Markham Southwell$t$, $g$OPTIONAL. Deputizes the party to patrol Icewind Dale; giant heads earn the title Defender of Icewind Dale. His sister Semile died in Nightstone.$g$, NULL::text),
  ($c$friends$c$, $t$Sir Baric Nylef$t$, $g$OPTIONAL. Hunting the Weevil. Sends the party to Sir Lanniver Strayl in Neverwinter, which opens a thread about the Order of the Gilded Eye.$g$, NULL::text),
  ($c$friends$c$, $t$Sirac of Suzail$t$, $g$OPTIONAL. Artus Cimber's son, hunted by Storvald's runes. Sends the party to the Roaringhorn family in Waterdeep.$g$, NULL::text),
  ($c$friends$c$, $t$Lifferlas$t$, $g$OPTIONAL. Sends the party after its creator, the giant-slaying druid Aerglas, via the treant Turlang at Shadowtop Cathedral.$g$, NULL::text),
  ($c$friends$c$, $t$Miros Xelbrin$t$, $g$OPTIONAL. Sends regards to Arleosa Starhenge in Amphail, who gives a wooden ring that summons the halfling Keltar Dardragon's apparition once.$g$, NULL::text),
  ($c$friends$c$, $t$Naxene Drathkala$t$, $g$OPTIONAL. Wants good dragons recruited against the giants (the Lords' Alliance would hate it). Sends the party to a 'dragon expert' in Waterdeep, Chazlauth Yarghorn.$g$, NULL::text),
  ($c$friends$c$, $t$Oren Yogilvy$t$, $g$OPTIONAL. Asks the party to check on his sister Lily at the Happy Cow in Daggerford, which leads to the Zhentarim loan shark Nelkin 'the Snail' Danniker.$g$, NULL::text),
  ($c$friends$c$, $t$Shalvus Martholio$t$, $g$OPTIONAL. Zhentarim spy. Wants an escort to Bargewright Inn and his boss Nalaskur Thaelond, whose beer-wagon errand is a test for the Black Network.$g$, NULL::text),
  ($c$friends$c$, $t$Zi Liang$t$, $g$OPTIONAL. Emerald Enclave sympathizer. Gives a black pearl pendant to bring to House Thann's butler in Waterdeep, who hands over her inheritance (two magic items).$g$, NULL::text),
  ($c$friends$c$, $t$Eldon Keyward$t$, $g$A cult captive; dragged into Evernight with the party, where his planar knowledge helps them find the way home.$g$, NULL::text),
  ($c$friends$c$, $t$Indrina Lamsensettle$t$, $g$Held in area C20. Her secret: Lord Neverember's claim to his title isn't legitimate. The crown thread's hinge (guide).$g$, NULL::text),
  ($c$friends$c$, $t$Sarcelle Malinosh$t$, $g$Held in area C5. Her secret: a recent vision of a desiccated man causing something terrible to happen.$g$, NULL::text),
  ($c$friends$c$, $t$Umberto Noblin$t$, $g$His secret (learned in C11): he's a historian of Vecna.$g$, NULL::text),
  ($c$friends$c$, $t$Sangora$t$, $g$Helpful, for a vampire. Her spawn are not, and follow the party to the Dolindar Tomb behind her back.$g$, NULL::text),
  ($c$friends$c$, $t$Alustriel Silverhand$t$, $g$Eve of Ruin's patron, with a sanctum in Sigil. She gathered Tasha and 'Mordenkainen' against Vecna. Kas gravely wounds her with the rod in ch. 9; she then explains the Chime of Exile. Act II link: Silverymoon's Moonbridge and Lady's College are hers.$g$, NULL::text),
  ($c$friends$c$, $t$Tasha$t$, $g$One of the Wizards Three. Wounded by Kas in ch. 9.$g$, NULL::text),
  ($c$friends$c$, $t$Malaina$t$, $g$Her secret (ch. 9): she suspected 'Mordenkainen' from the moment he arrived (cruel muttering when alone, defensiveness at simple questions) and said nothing. From ch. 2 on, let a player notice her unease (guide).$g$, NULL::text),
  ($c$friends$c$, $t$Gertrude$t$, $g$Found at Web's Edge (W6a). Her secret: she and her friend Rockzanna knew the Lolth cultists' attack was coming and warned no one.$g$, NULL::text),
  ($c$friends$c$, $t$Figaro$t$, $g$His secret (Z8): he knew the stretch of the Astral Sea they were crossing was dangerous and hid it from the captain.$g$, NULL::text),
  ($c$friends$c$, $t$Ikasa$t$, $g$His secret (Z12): there was another survivor of the pirate attack that stranded them.$g$, NULL::text),
  ($c$friends$c$, $t$Mercy$t$, $g$Their secret: separated from their best friend, the warforged Filch, after the Day of Mourning, they never truly searched.$g$, NULL::text),
  ($c$friends$c$, $t$Kalyth$t$, $g$Her secret: she lost the magic items and money that would have spared her band its hardship.$g$, NULL::text),
  ($c$friends$c$, $t$Sarusanda$t$, $g$Her secret: her father, Galias, joined the priests of Osybus, and she came to Death House expecting to find and kill him.$g$, NULL::text),
  ($c$friends$c$, $t$Riffel$t$, $g$Tells the party about Teremini, the stolen shard, and the wardens' failed attack.$g$, NULL::text),
  ($c$friends$c$, $t$Valendar$t$, $g$Captive in Three Moons Vault (V7). His secret: he led the assault without proper planning or scouting.$g$, NULL::text),
  ($c$friends$c$, $t$Gazaia$t$, $g$Corrupted into a deadbark dryad. Her secret: she hid while soldiers attacked her tree and looted the rod piece.$g$, NULL::text),
  ($c$friends$c$, $t$Marian Xavere$t$, $g$Her secret: a lifelong fascination with Acererak and his magic, and a temptation to study necromancy.$g$, NULL::text),
  ($c$friends$c$, $t$Rerak$t$, $g$A false lich, an empowered copy of Acererak. His secret: he resents his imprisonment and never wanted to do Acererak's will. He can become an ally (guide).$g$, NULL::text),
  ($c$friends$c$, $t$Vaeve$t$, $g$Offers the party information: where Miska is, who directs Lolth's troops, and that a vampire gives Miska orders.$g$, NULL::text),
  ($c$friends$c$, $t$Mordenkainen$t$, $g$The real one is off travelling the multiverse and has no idea someone is wearing his face. Kas has clashed with him before.$g$, NULL::text)
)
INSERT INTO public.the8_lore_entries (campaign_id, category, title, gm_notes, preferred_habitat, is_secret)
SELECT c.id, s.category, s.title, s.gm_notes, s.preferred_habitat, true
FROM seed s CROSS JOIN c
WHERE NOT EXISTS (SELECT 1 FROM public.the8_lore_entries e WHERE e.campaign_id = c.id AND e.title = s.title);
-- blocks: all hidden; only added to entries that have none yet, so your edits are never overwritten
WITH c AS (SELECT id FROM public.campaigns WHERE slug = 'eve-of-giants'),
seed(title, sort_order, body) AS (VALUES
  ($t$Gundren Rockseeker$t$, 0, $b$A dwarf prospector, talkative and relentlessly optimistic. He hired the party in Neverwinter to escort a wagon of supplies to Phandalin.$b$),
  ($t$Gundren Rockseeker$t$, 1, $b$He rode ahead with a warrior escort, Sildar Hallwinter, to see to business in town.$b$),
  ($t$Gundren Rockseeker$t$, 2, $b$He never arrived. His horse was found dead on the Triboar Trail, shot with goblin arrows.$b$),
  ($t$Gundren Rockseeker$t$, 3, $b$He and his brothers found the entrance to Wave Echo Cave, the lost mine of the Phandelver Pact, and he carried the only map.$b$),
  ($t$Gundren Rockseeker$t$, 4, $b$The goblins took him and his map to King Grol at Cragmaw Castle, on the orders of someone called the Spider.$b$),
  ($t$Gundren Rockseeker$t$, 5, $b$Rescued, he offers 25 gold pieces each and a tenth share of the mine's profits once it's running.$b$),
  ($t$Sildar Hallwinter$t$, 0, $b$A kindhearted human warrior of nearly fifty who rode with Gundren as his escort.$b$),
  ($t$Sildar Hallwinter$t$, 1, $b$He holds a place of honour in Waterdeep's famous griffon cavalry, and he's an agent of the Lords' Alliance.$b$),
  ($t$Sildar Hallwinter$t$, 2, $b$The goblins dragged him to their hideout, beat him, and kept him bound in their den.$b$),
  ($t$Sildar Hallwinter$t$, 3, $b$He came to Phandalin to find Iarno Albrek, a fellow Alliance member and wizard who vanished near Tresendar Manor about two months ago: a short, dark-bearded man in his thirties.$b$),
  ($t$Sildar Hallwinter$t$, 4, $b$He pays 500 gold pieces to whoever finds Cragmaw Castle and defeats or drives off its leader, and 200 for ending the Redbrands.$b$),
  ($t$Sildar Hallwinter$t$, 5, $b$He says the storms off Neverwinter have been strange lately: they fight the wind. And a storm giantess was found murdered on an island off the coast, with rumours saying Neverwinter's people did it.$b$),
  ($t$Sildar Hallwinter$t$, 6, $b$Lord Neverember's agents, he admits, quietly pay off anyone who claims descent from Neverwinter's old royal line. Sometimes they do worse.$b$),
  ($t$Nundro Rockseeker$t$, 0, $b$The youngest of the three Rockseeker brothers, last seen camped out at the brothers' secret find.$b$),
  ($t$Nundro Rockseeker$t$, 1, $b$He was taken prisoner in Wave Echo Cave.$b$),
  ($t$Nundro Rockseeker$t$, 2, $b$The Spider kept him alive and questioned him every day, sure he knew more about the mine than he admitted.$b$),
  ($t$Tharden Rockseeker$t$, 0, $b$One of the three Rockseeker brothers, last seen camped out at the brothers' secret find.$b$),
  ($t$Tharden Rockseeker$t$, 1, $b$He is dead, killed at the brothers' camp at the mouth of Wave Echo Cave.$b$),
  ($t$Elmina Barthen$t$, 0, $b$A young woman with a kindly manner who owns Barthen's Provisions, the biggest trading post in Phandalin.$b$),
  ($t$Elmina Barthen$t$, 1, $b$She pays the 10 gold pieces a head for delivering Gundren's wagon. Gundren is a friend, and his talk of finding the lost mine excited her.$b$),
  ($t$Elmina Barthen$t$, 2, $b$She says the two other Rockseeker brothers are camped somewhere outside town and haven't been in to resupply for a tenday.$b$),
  ($t$Ander and Thistle$t$, 0, $b$The two clerks at Barthen's Provisions, who load the wagons and mind the counter when Elmina is out.$b$),
  ($t$Toblen Stonehill$t$, 0, $b$The friendly young innkeeper of the Stonehill Inn, with a wife and children.$b$),
  ($t$Toblen Stonehill$t$, 1, $b$He's from Triboar, to the east. He came to Phandalin to prospect and found he knew far more about running an inn.$b$),
  ($t$Toblen Stonehill$t$, 2, $b$He hates the Redbrands but keeps his head down, afraid of what they'd do to his family.$b$),
  ($t$Toblen Stonehill$t$, 3, $b$He still gets letters from a cousin in Triboar. The latest says fire giants were seen on the Long Road, and one of them was swinging a rod like a dowser.$b$),
  ($t$Trilena Stonehill$t$, 0, $b$Toblen's wife, who runs the Stonehill Inn with him.$b$),
  ($t$Pip Stonehill$t$, 0, $b$Toblen's young son, and Carp Alderleaf's best friend.$b$),
  ($t$Pip Stonehill$t$, 1, $b$He says Carp found a secret tunnel in the woods and the Redbrands nearly caught him.$b$),
  ($t$Elsa$t$, 0, $b$The dwarf bartender at the Stonehill Inn.$b$),
  ($t$Elsa$t$, 1, $b$She says Daran Edermath, the orchard keeper, used to be an adventurer.$b$),
  ($t$Freda$t$, 0, $b$A gnome weaver who drinks at the Stonehill Inn.$b$),
  ($t$Freda$t$, 1, $b$She says the Redbrands hassle every business in town except the Miner's Exchange, because they don't want trouble with Halia Thornton.$b$),
  ($t$Lanar$t$, 0, $b$A miner who drinks at the Stonehill Inn.$b$),
  ($t$Lanar$t$, 1, $b$He says marauders have been attacking caravans on the eastern end of the Triboar Trail, and the townmaster wants someone to run them off.$b$),
  ($t$Narth$t$, 0, $b$A farmer who drinks at the Stonehill Inn.$b$),
  ($t$Narth$t$, 1, $b$He says Sister Garaele left town for a few days recently and came back wounded.$b$),
  ($t$Linene Graywind$t$, 0, $b$The woman who runs the Lionshield Coster's trading post in Phandalin.$b$),
  ($t$Linene Graywind$t$, 1, $b$Bandits have hit her company's caravans, and the latest one never arrived. She doesn't know who's responsible.$b$),
  ($t$Linene Graywind$t$, 2, $b$She sells arms and armour from a back room, but not to anyone she thinks is a danger to the town.$b$),
  ($t$Linene Graywind$t$, 3, $b$She pays 50 gold pieces for the return of her stolen goods, and warns people to stay away from the Sleeping Giant.$b$),
  ($t$Linene Graywind$t$, 4, $b$After the feast, she asks for a letter to be carried to Alaestra Ulgar in Triboar.$b$),
  ($t$Daran Edermath$t$, 0, $b$A drow, well over five hundred years old, who has retired to an orchard cottage outside Phandalin.$b$),
  ($t$Daran Edermath$t$, 1, $b$He served for many years as a marshal and herald on the Dragon Coast, far to the south, before coming back to the Neverwinter region, his original home.$b$),
  ($t$Daran Edermath$t$, 2, $b$He's a member of the Order of the Gauntlet, no longer active, but he keeps an eye on what happens around town.$b$),
  ($t$Daran Edermath$t$, 3, $b$He wants someone to stand up to the Redbrands and their leader, Glasstaff, and knows their safe house is under Tresendar Manor.$b$),
  ($t$Daran Edermath$t$, 4, $b$Prospectors have told him someone is digging at Old Owl Well and that undead chase them away. He'll give his boots of striding and springing to whoever finds out what's going on there.$b$),
  ($t$Daran Edermath$t$, 5, $b$He's heard that herds near Triboar vanish overnight: fences flattened, and footprints the size of a wagon.$b$),
  ($t$Sister Garaele$t$, 0, $b$A zealous young elf priestess who tends the Shrine of Luck.$b$),
  ($t$Sister Garaele$t$, 1, $b$She despairs of ever ridding Phandalin of the Redbrands.$b$),
  ($t$Sister Garaele$t$, 2, $b$She recently left town for a few days and came back wounded.$b$),
  ($t$Sister Garaele$t$, 3, $b$She's a Harper, and reports to her superiors on everything around Phandalin.$b$),
  ($t$Sister Garaele$t$, 4, $b$Her superiors sent her to ask a banshee, Agatha, about a spellbook. Agatha drove her off. She wants someone to take the banshee a jeweled silver comb and ask where the spellbook of the legendary mage Bowgentle is. She pays three potions of healing.$b$),
  ($t$Qelline Alderleaf$t$, 0, $b$A wise, practical halfling farmer who seems to know everything that happens in Phandalin.$b$),
  ($t$Qelline Alderleaf$t$, 1, $b$She's an old friend of the druid Reidoth, who knows every inch of the land. Reidoth has gone to the ruins of Thundertree, about fifty miles north-west.$b$),
  ($t$Carp Alderleaf$t$, 0, $b$Qelline's son: a spirited, precocious halfling boy who dreams of being an adventurer.$b$),
  ($t$Carp Alderleaf$t$, 1, $b$Playing in the woods near Tresendar Manor, he found a secret tunnel in a thicket. Two "big scary bandits" came out of it to meet two Redbrands, and nearly caught him.$b$),
  ($t$Carp Alderleaf$t$, 2, $b$He can show the way to the tunnel, but won't go in.$b$),
  ($t$Reidoth$t$, 0, $b$An elderly human druid with long white hair who doesn't use two words where one will do. Qelline Alderleaf says there isn't an inch of the land she doesn't know.$b$),
  ($t$Reidoth$t$, 1, $b$She keeps a watch post in Thundertree and visits from time to time to keep an eye on its dangers. She put up the warning sign on the road.$b$),
  ($t$Reidoth$t$, 2, $b$She warns of spiders at the foot of the hill, people in black masks and cloaks on the east side, and a young green dragon that has moved into the old tower.$b$),
  ($t$Reidoth$t$, 3, $b$She's a member of the Emerald Enclave, and won't stir up the goblins without good reason.$b$),
  ($t$Reidoth$t$, 4, $b$She knows where Cragmaw Castle is, and where the lost mine lies.$b$),
  ($t$Mirna Dendrar$t$, 0, $b$The widow of Thel Dendrar, a woodcarver the Redbrands murdered a tenday ago. She and her children disappeared the same day.$b$),
  ($t$Mirna Dendrar$t$, 1, $b$The Redbrands held her and her children in cells under Tresendar Manor, waiting on a ransom from rich relatives in Neverwinter she'd invented to keep them alive.$b$),
  ($t$Mirna Dendrar$t$, 2, $b$As a girl, she fled Thundertree with her family when undead overran it. Their herb and alchemy shop, in the south-east of the ruins, still hides an emerald necklace in a case under the storage shelves.$b$),
  ($t$Nilsa and Nars Dendrar$t$, 0, $b$Mirna Dendrar's children: Nilsa, eighteen, and Nars, thirteen. They vanished with their mother when the Redbrands murdered their father.$b$),
  ($t$Droop$t$, 0, $b$A small, terrified goblin who faints at the first sign of trouble.$b$),
  ($t$Droop$t$, 1, $b$He's from the Scraptops, a clan of goblin scavengers and tinkerers, and wandered into the Redbrand hideout looking for parts for a wagon he's fixing back home.$b$),
  ($t$Droop$t$, 2, $b$The bugbears there bully him, and the Cragmaws are demanding he join them. He just wants to go home.$b$),
  ($t$Droop$t$, 3, $b$He knows the hideout's layout, its secret doors and its traps.$b$),
  ($t$Halia Thornton$t$, 0, $b$The quick-witted guild master of the Miner's Exchange, who acts as if the Exchange were the closest thing Phandalin has to a government.$b$),
  ($t$Halia Thornton$t$, 1, $b$She offers 100 gold pieces to capture the Redbrands' leader, Glasstaff, and bring her any letters found in his quarters.$b$),
  ($t$Halia Thornton$t$, 2, $b$She's an agent of the Zhentarim.$b$),
  ($t$Halia Thornton$t$, 3, $b$She wants the Redbrands for herself.$b$),
  ($t$Harbin Wester$t$, 0, $b$Phandalin's townmaster: a cheerful, well-liked banker, and a timid one.$b$),
  ($t$Harbin Wester$t$, 1, $b$He insists the Redbrands are "just a mercenary guild, and not all that much trouble, really."$b$),
  ($t$Harbin Wester$t$, 2, $b$He's posted a 100 gold piece contract to drive the marauders away from Wyvern Tor.$b$),
  ($t$Harbin Wester$t$, 3, $b$Eventually he admits the Redbrands should be caught and tried, perhaps sent to Neverwinter for prison.$b$),
  ($t$Harbin Wester$t$, 4, $b$After the feast, he hands over a rude letter for Triboar's lord protector, Darathra Shendrel.$b$),
  ($t$Greska$t$, 0, $b$The surly orc who runs the Sleeping Giant.$b$),
  ($t$Agatha$t$, 0, $b$A banshee who haunts a shelter in the woods outside Conyberry: the spirit of an elf woman who was beautiful once, and as vain in death as she was in life.$b$),
  ($t$Agatha$t$, 1, $b$She is well informed, and a capable diviner. She will answer one question, and only one.$b$),
  ($t$Agatha$t$, 2, $b$She longs for the beautiful things she owned in life.$b$),
  ($t$Agatha$t$, 3, $b$She traded Bowgentle's spellbook to a necromancer named Tsernoth, from the city of Iriaebor, more than a hundred years ago. She doesn't know what became of it.$b$),
  ($t$Agatha$t$, 4, $b$Her warning about the troubles in the land: the old order of the giants is broken, and the small folk will be crushed in the shuffle.$b$),
  ($t$Hamun Kost$t$, 0, $b$A red-robed man with a shaved head and a tattoo on his forehead, camped among the ruins of Old Owl Well with silent, shambling labourers.$b$),
  ($t$Hamun Kost$t$, 1, $b$He's a Red Wizard of Thay; the tattoo marks him as a necromancer.$b$),
  ($t$Hamun Kost$t$, 2, $b$He isn't eager to fight. He calls off his zombies as soon as anyone speaks to him, and he's willing to trade.$b$),
  ($t$Hamun Kost$t$, 3, $b$He wants the marauders at Wyvern Tor gone, because they've been scouting his camp. Or he wants someone to ask the banshee Agatha the name of the wizard who built the tower.$b$),
  ($t$Iarno Albrek$t$, 0, $b$A Lords' Alliance wizard, a short, dark-bearded man in his thirties, who went to Phandalin several months ago to establish order. The Alliance hasn't heard from him since.$b$),
  ($t$Iarno Albrek$t$, 1, $b$He disappeared while exploring around Tresendar Manor about two months ago.$b$),
  ($t$Iarno Albrek$t$, 2, $b$He is Glasstaff, leader of the Redbrands.$b$),
  ($t$Darathra Shendrel$t$, 0, $b$Triboar's lord protector, a capable human woman who takes the defence of her town personally.$b$),
  ($t$Urgala Meltimer$t$, 0, $b$Proprietor of Northshield House, an inn in Triboar, and a former adventurer.$b$),
  ($t$Narth Tezrin$t$, 0, $b$Proprietor of the Lion's Share, a store in Triboar.$b$),
  ($t$Darz Helgar$t$, 0, $b$A retired member of a Waterdhavian thieves' guild, living quietly in Triboar.$b$),
  ($t$Othovir$t$, 0, $b$A quiet harness maker in Triboar who'd rather not discuss his family.$b$),
  ($t$Ghelryn Foehammer$t$, 0, $b$A dwarf smith who owns Foehammer's Forge in Triboar.$b$),
  ($t$Krowen Valharrow$t$, 0, $b$A dotty old archmage who lives in Moongleam Tower in Everlund, fond of adventurers and of tressym.$b$),
  ($t$Dral Thelev$t$, 0, $b$The one-eyed half-orc proprietor of Danivarr's House in Everlund.$b$),
  ($t$Lord Harthos Zymorven$t$, 0, $b$A wealthy knight of Silverymoon who holds Zymorven Hall on the Rauvin Road.$b$),
  ($t$Tamalin Zoar$t$, 0, $b$A spry sixty-year-old retired adventurer who rules the village of Calling Horns.$b$),
  ($t$Harshnag the Grim$t$, 0, $b$A huge frost giant in plate armour, wearing a white dragon's skull as a helm and carrying a jagged greataxe. In some taverns he's a monster; in others, a hero.$b$),
  ($t$Moog$t$, 0, $b$A hill giant sulking alone in an old tower, singing loud, sad songs.$b$),
  ($t$Princess Serissa$t$, 0, $b$The youngest daughter of King Hekaton, ruling the storm giants as regent from the Wyrmskull Throne.$b$),
  ($t$King Hekaton$t$, 0, $b$The storm giant king, missing since he went looking for his wife's killers.$b$),
  ($t$Imperator Uthor$t$, 0, $b$Hekaton's younger brother, commander of the garrison and castellan of Maelstrom.$b$),
  ($t$Klauth$t$, 0, $b$Old Snarl, an ancient red dragon who rules Klauthen Vale.$b$),
  ($t$Delsephine$t$, 0, $b$Leader of the masked crew on the airship that arrives at the Eye of the All-Father.$b$),
  ($t$Felgolos$t$, 0, $b$A bronze dragon whose roars of pain carry for miles from a cloud castle.$b$),
  ($t$Eigeron$t$, 0, $b$The ghost of a cloud giant who lingers in the Eye of the All-Father.$b$),
  ($t$Cinderhild$t$, 0, $b$Duke Zalto's eighteen-year-old daughter, sulking in her room in Ironslag.$b$),
  ($t$Elister Noggins$t$, 0, $b$A rock gnome clockmaker.$b$),
  ($t$Hekaton's Storm Giant Hunters$t$, 0, $b$Four storm giants of Maelstrom: Nimir, Orlekto, Shaldoor and Vaasha.$b$),
  ($t$Lord Dagult Neverember$t$, 0, $b$Lord Protector of Neverwinter and one of the great lords of the Lords' Alliance. Canny, charming, and good at being grateful.$b$),
  ($t$Morak Ur'gray$t$, 0, $b$The dwarf innkeeper of Nightstone.$b$),
  ($t$Zephyros$t$, 0, $b$An eccentric cloud giant wizard with a flying tower.$b$),
  ($t$Augrek Brighthelm$t$, 0, $b$A dwarf deputy of the sheriff in Bryn Shander.$b$),
  ($t$Beldora$t$, 0, $b$A woman in Bryn Shander who always seems to hear the news first.$b$),
  ($t$Duvessa Shane$t$, 0, $b$The town speaker of Bryn Shander.$b$),
  ($t$Markham Southwell$t$, 0, $b$The sheriff of Bryn Shander.$b$),
  ($t$Sir Baric Nylef$t$, 0, $b$A knight of the Order of the Gauntlet on the trail of a criminal.$b$),
  ($t$Sirac of Suzail$t$, 0, $b$A young man in Bryn Shander who seems to know why the frost giants came.$b$),
  ($t$Lifferlas$t$, 0, $b$An awakened tree in Goldenfields who watches over the farms.$b$),
  ($t$Miros Xelbrin$t$, 0, $b$Proprietor of Northfurrow's End, an inn in Goldenfields.$b$),
  ($t$Naxene Drathkala$t$, 0, $b$A mage of the Watchful Order of Magists and Protectors.$b$),
  ($t$Oren Yogilvy$t$, 0, $b$A halfling musician staying in Goldenfields.$b$),
  ($t$Shalvus Martholio$t$, 0, $b$A shepherd in Goldenfields.$b$),
  ($t$Zi Liang$t$, 0, $b$An acolyte of Chauntea at the Harvesthome Abbey.$b$),
  ($t$Eldon Keyward$t$, 0, $b$An elf scholar who specializes in the Outer Planes, kidnapped in Neverwinter.$b$),
  ($t$Indrina Lamsensettle$t$, 0, $b$A human actor who moves in Neverwinter's highest social circles, kidnapped by the cult.$b$),
  ($t$Sarcelle Malinosh$t$, 0, $b$A human wild magic sorcerer who studies the Outer Planes, kidnapped by the cult.$b$),
  ($t$Umberto Noblin$t$, 0, $b$A gnome historian who has written books on various gods, kidnapped by the cult.$b$),
  ($t$Sangora$t$, 0, $b$A centuries-old vampire merchant of Evernight's Corpse Market, with sunken eyes and long white hair. Curious and fond of gossip.$b$),
  ($t$Alustriel Silverhand$t$, 0, $b$The Shining Lady: an archmage, one of the immortal Seven Sisters, and Silverymoon's ruler for centuries. She looks young, with silver hair and a unicorn-headed staff.$b$),
  ($t$Tasha$t$, 0, $b$The witch Tasha, daughter of Baba Yaga, a wizard of terrible power and sharp temper.$b$),
  ($t$Malaina$t$, 0, $b$Alustriel's wife, who keeps the sanctum in Sigil.$b$),
  ($t$Gertrude$t$, 0, $b$The lone survivor of a caravan ambushed in the Underdark.$b$),
  ($t$Figaro$t$, 0, $b$The tiefling first mate of the spelljammer Lambent Zenith.$b$),
  ($t$Ikasa$t$, 0, $b$A blink dog, stranded in the wreck of the Lambent Zenith with his best friend, the elf Daveras.$b$),
  ($t$Mercy$t$, 0, $b$The leader of a band of warforged pilgrims on Mount Ironrot.$b$),
  ($t$Kalyth$t$, 0, $b$The leader of a band of veterans camped on Mount Ironrot, short of money.$b$),
  ($t$Sarusanda$t$, 0, $b$An inquisitor of the Ulmist Inquisition, met on the road to Death House.$b$),
  ($t$Riffel$t$, 0, $b$A Blue Fire Warden of Krynn.$b$),
  ($t$Valendar$t$, 0, $b$The werewolf leader of the Blue Fire Wardens, now a prisoner.$b$),
  ($t$Gazaia$t$, 0, $b$A dryad bound to the peylon tree.$b$),
  ($t$Marian Xavere$t$, 0, $b$An archaeologist exploring the Isle of Serpents.$b$),
  ($t$Rerak$t$, 0, $b$A lich who calls himself Rerak, master of the Tomb of Wayward Souls.$b$),
  ($t$Vaeve$t$, 0, $b$A drow mage on Pandesmos, loyal to neither Lolth nor Kas.$b$),
  ($t$Mordenkainen$t$, 0, $b$A legendary archmage of Oerth, famous across the multiverse.$b$)
)
INSERT INTO public.the8_reveal_blocks (campaign_id, lore_entry_id, body, is_revealed, sort_order)
SELECT c.id, e.id, s.body, false, s.sort_order
FROM seed s CROSS JOIN c
JOIN public.the8_lore_entries e ON e.campaign_id = c.id AND e.title = s.title
WHERE NOT EXISTS (SELECT 1 FROM public.the8_reveal_blocks b WHERE b.lore_entry_id = e.id);

-- ---------------------------------------------------------------------------
-- 5. FOES  (62 entries, 98 blocks)
-- ---------------------------------------------------------------------------
WITH c AS (SELECT id FROM public.campaigns WHERE slug = 'eve-of-giants'),
seed(category, title, gm_notes, preferred_habitat) AS (VALUES
  ($c$foes$c$, $t$The Spider$t$, $g$Nezznar, a drow wizard with a spider staff, headquartered in the temple of Dumathoin (W19) with two bugbears; casts invisibility if warned. He admits everything when confronted: using the Cragmaws and the Redbrands to keep the mine secret. The undead in W8 and W12 have stopped him reaching the Forge; he doesn't know about the old streambed (W17). If jailed in Phandalin without a guard, Halia breaks him out. Treasure: potion of healing, spider staff, anvil-headed key to W20, sack of coin and an electrum ale mug.$g$, NULL::text),
  ($c$foes$c$, $t$Glasstaff$t$, $g$Staff of defense (mage armor, shield). Warned by Zeond, he flees through a secret door, grabs the satchel in the R1 cistern and drinks a potion of invisibility. Surrenders at 8 hp and becomes a model prisoner, hoping the Spider will free him (he won't). Knows: the Spider is a drow; four bugbears were sent; the bugbears know the way to Wave Echo Cave; the Spider seeks the Forge; no other Alliance member knows he turned. Chest: coin, gems, scrolls of hold person and fireball. Desk: the Spider's sealed letter ordering the strangers captured or killed and any dwarven maps sent on.$g$, NULL::text),
  ($c$foes$c$, $t$Klarg$t$, $g$H8 with two goblin honour guards and Ripper. Warned, they hide behind stalagmites and crates. If his allies die he tries to squeeze down the chimney to H3 (DC 10 Dex or stuck). Treasure chest among the Lionshield crates.$g$, NULL::text),
  ($c$foes$c$, $t$Yeemik$t$, $g$Untrustworthy: if the party takes the deal, he tries to squeeze a ransom out of them afterwards. Refused, he shoves Sildar off the ledge. His crony Errk, another goblin boss, shouts along supportively.$g$, NULL::text),
  ($c$foes$c$, $t$King Grol$t$, $g$C14, haggling with Vyerith. Warned, he holds Gundren hostage. Hobgoblins in C12 are loyal to him.$g$, NULL::text),
  ($c$foes$c$, $t$Vyerith$t$, $g$Warned, she hides behind the north-east door to attack from behind.$g$, NULL::text),
  ($c$foes$c$, $t$Vhalak$t$, $g$W18. The Spider's divinations say something valuable lies in the rift (a dwarf's skeleton wearing gauntlets of ogre power, DC 20 Perception, one check per hour). If three bugbears fall, Vhalak runs to warn Nezznar and may pose as Nundro.$g$, NULL::text),
  ($c$foes$c$, $t$Ssarnak$t$, $g$R8. Watches intruders from behind a column and uses Weird Insight to learn their secrets. Knows everything the Redbrands know. The southern bridge is rigged to collapse.$g$, NULL::text),
  ($c$foes$c$, $t$Zeond$t$, $g$R11. Waits until the party is fighting, then strikes and turns invisible again; warns Glasstaff of anyone coming through the workshop.$g$, NULL::text),
  ($c$foes$c$, $t$Nosk$t$, $g$R9. They fear the Spider more than the party and won't talk willingly (charm person might do it). They avoid the human Redbrands; people in scarlet cloaks can trick them. Nosk carries the master key and 50 gp in stones.$g$, NULL::text),
  ($c$foes$c$, $t$Venomfang$t$, $g$Far above the party's weight at level 3–4: meant to be avoided, bargained with, or driven off. He flies away at a quarter of his hit points. Under the coins lies Hew, a +1 dwarven battleaxe that deals maximum damage to plants and wood. Reidoth trades directions to Cragmaw Castle for chasing him off. Eve seed (ours): the ancient giant–dragon war behind every giant lord's plan, and Iymrith's motive.$g$, NULL::text),
  ($c$foes$c$, $t$Favric$t$, $g$He means to offer his 'allies' to the dragon as tribute, and the cultists side with the dragon in a fight. Tribute coffer: six amethysts (50 gp each). Wears a potion of flying around his neck. His followers flee if he's caught or killed.$g$, NULL::text),
  ($c$foes$c$, $t$Brughor Axe-Biter$t$, $g$18 hit points. His band flees if he dies (except Gog). Eve seed (ours), with the Wyvern Tor prisoner.$g$, NULL::text),
  ($c$foes$c$, $t$Gog$t$, $g$Fights until slain.$g$, NULL::text),
  ($c$foes$c$, $t$Lhupo$t$, $g$C9 with two robed 'acolytes', none with real divine power. Chalice (180 gp) and censer (150 gp) on the altar.$g$, NULL::text),
  ($c$foes$c$, $t$Yegg$t$, $g$C7 with six goblins. If he dies, the rest flee.$g$, NULL::text),
  ($c$foes$c$, $t$Mormesk the Wraith$t$, $g$W14. Wants the spectator in the Forge destroyed. Chest: coin, malachites, a platinum-filigree pipe. Eve seed (ours): Vecna's sign, the first breadcrumb of Act III. Add the map to the chest.$g$, NULL::text),
  ($c$foes$c$, $t$The Flameskull$t$, $g$W12, with eight dwarf zombies (they don't pursue beyond 1 round). This is what stops the Spider reaching the Forge; the old streambed (W17) goes around it.$g$, NULL::text),
  ($c$foes$c$, $t$The Spectator of the Forge$t$, $g$W15. Attacks if anything is taken. DC 15 Deception convinces it the party works for the mine's owners and has come to end its service; it then vanishes home.$g$, NULL::text),
  ($c$foes$c$, $t$Iymrith$t$, $g$The spine villain of Act II (guide), until level 11. An ancient blue dragon disguised as a storm giant. She goaded Mirran and Nym into murder, set the Kraken Society on Neri and Hekaton, framed the Lords' Alliance, and wants giants and small folk to destroy each other, then the Wyrmskull Throne for her hoard. Plant her as a name, not a face. Attacks at the Eye (ch. 4); slips at Maelstrom and, if exposed, snatches the Korolnor Scepter and teleports away (ch. 10); dies in her Anauroch lair (ch. 12).$g$, NULL::text),
  ($c$foes$c$, $t$Mirran$t$, $g$Believes the Wyrmskull Throne is hers by right and plans to restore Ostoria and sweep away the small folk. A pawn of Iymrith; she helped plan her mother's murder.$g$, NULL::text),
  ($c$foes$c$, $t$Nym$t$, $g$Wants Mirran to take the throne and fail, so she can take it from her. Uneasy about the broken ordning, but Iymrith has convinced her the gods will reward her. Helped plan her mother's murder.$g$, NULL::text),
  ($c$foes$c$, $t$Slarkrethel$t$, $g$A spellcasting kraken, old even during the giant–dragon war forty thousand years ago, seeking a lost path to godhood. Founder of the Kraken Society. Kills Drylund by telepathy mid-sentence and destroys the Morkoth if the party lingers.$g$, NULL::text),
  ($c$foes$c$, $t$Tholtz Daggerdark$t$, $g$Kraken Society. Captain of the Morkoth and King Hekaton's jailer.$g$, NULL::text),
  ($c$foes$c$, $t$Rool$t$, $g$Kraken Society assassin and first mate of the Morkoth.$g$, NULL::text),
  ($c$foes$c$, $t$Lord Khaspere Drylund$t$, $g$Kraken Society. His golden goose chip was found by Queen Neri's body. Under pressure he reveals the Morkoth, then dies mid-sentence when Slarkrethel silences him.$g$, NULL::text),
  ($c$foes$c$, $t$Pow Ming$t$, $g$Tough, watchful, and in charge of making sure nobody bothers Lord Drylund.$g$, NULL::text),
  ($c$foes$c$, $t$Chief Guh$t$, $g$Plans to eat until she's the biggest giant in the world and the gods elevate hill giants to the top. Took Moog's husband Hruk among her mates. Refuses to give up her conch and orders her servants to attack. Comic and gross (guide).$g$, NULL::text),
  ($c$foes$c$, $t$Thane Kayalithica$t$, $g$A neutral evil extremist. After weeks of meditation she concluded the small folk corrupted the giants' dreams by building on Ostoria's bones, and means to wipe the land clean. Fine if the vote picks her (guide).$g$, NULL::text),
  ($c$foes$c$, $t$Jarl Storvald$t$, $g$Hunts the Ring of Winter to bring an Age of Everlasting Ice. Holds Cryovain and Isendraug through their eggs. His blood-powered runes lead his raiders to Artus Cimber's relatives instead of Artus.$g$, NULL::text),
  ($c$foes$c$, $t$Duke Zalto$t$, $g$Rebuilding the Vonindod; plans to steal Maegera from Gauntlgrym through House Xorlarrin. Under pressure from his wife, distracted by his children. He or Brimskarda will trade the conch for Zaltember's safe return, and renege if they have nothing to lose. The guide's recommended lord: the Vonindod has been the thread since Wave Echo Cave.$g$, NULL::text),
  ($c$foes$c$, $t$Duchess Brimskarda$t$, $g$Fears another giant lord will win the gods' favour first and nags Zalto to move faster.$g$, NULL::text),
  ($c$foes$c$, $t$Zaltember$t$, $g$Sadistic: found dangling a dwarf slave over a smelter. If captured, he declares who his father is; his parents will trade the conch for him.$g$, NULL::text),
  ($c$foes$c$, $t$Countess Sansuri$t$, $g$Searching for a lost Ostorian trove of dragon magic to destroy her rivals and Hekaton's court. Tortures Felgolos for clues. Bargains the conch for her life or her twins'.$g$, NULL::text),
  ($c$foes$c$, $t$Count Thullen$t$, $g$Lives in his own quarters in the castle (area 28).$g$, NULL::text),
  ($c$foes$c$, $t$Cressaro$t$, $g$Runs the castle for Sansuri.$g$, NULL::text),
  ($c$foes$c$, $t$Okssort and Ildmane$t$, $g$Zalto's servants, tracking a buried Vonindod fragment with a rod of the Vonindod. Both retreat if either drops to 81 hit points or fewer. The 'dowser' of Toblen's Act I rumour (ours).$g$, NULL::text),
  ($c$foes$c$, $t$Cryovain$t$, $g$Held, with his mate Isendraug, through their stolen eggs. Not a willing villain: free the eggs and his loyalty to Storvald ends.$g$, NULL::text),
  ($c$foes$c$, $t$Isendraug$t$, $g$Cryovain's mate, enslaved the same way.$g$, NULL::text),
  ($c$foes$c$, $t$Claugiyliamatar$t$, $g$OPTIONAL cameo (guide). Reclusive; drives other dragons away. Watches the giants' chaos with interest, and waits with Klauth after Iymrith falls.$g$, NULL::text),
  ($c$foes$c$, $t$The Weevil$t$, $g$Hiding as a stable hand at Xantharl's Keep. Worth 5,000 gp delivered alive to Mirabar.$g$, NULL::text),
  ($c$foes$c$, $t$The Daerivoss Brothers$t$, $g$Lawful evil, and they don't want company. The murder mystery at Noanar's Hold turns on them and a 10,000 gp inheritance.$g$, NULL::text),
  ($c$foes$c$, $t$Tholzar Brenner$t$, $g$Has the giant slayer greatsword from Urgala's quest.$g$, NULL::text),
  ($c$foes$c$, $t$Xamlyn Margaster$t$, $g$Comes out of her tower on the third round of any break-in at the carriage house.$g$, NULL::text),
  ($c$foes$c$, $t$Kella Darkhope$t$, $g$OPTIONAL (SKT ch. 1). Zhentarim spy waiting for the Seven Snakes to take Nightstone as a Black Network base.$g$, NULL::text),
  ($c$foes$c$, $t$Xolkin Alassandar$t$, $g$OPTIONAL (SKT ch. 1). Coming to seize Nightstone for the Zhentarim.$g$, NULL::text),
  ($c$foes$c$, $t$Vecna$t$, $g$The final villain. Weakened while weaving the Ritual of Remaking in the Cave of Shattered Reflection. Banished to Oerth if the party wins; far from undone.$g$, NULL::text),
  ($c$foes$c$, $t$Kas the Betrayer$t$, $g$Disguised as Mordenkainen with the Crown of Lies from ch. 2 until he reveals himself in ch. 9. Wants to kill Vecna at the last moment and remake the multiverse himself, and wants Alustriel and Tasha to witness his strength. Must be weakened enough to banish with the Chime of Exile; then he gives up Vecna's location (his secret). Pay off every hint about 'Mordenkainen' (guide).$g$, NULL::text),
  ($c$foes$c$, $t$Miska the Wolf-Spider$t$, $g$Kas's ally against Vecna. Kas uses the rod to tear a hole in his prison; Miska is widening it from the Ruinous Citadel.$g$, NULL::text),
  ($c$foes$c$, $t$Lolth$t$, $g$Vecna's ally. Her forces, under Camlash, fight Miska's on Pandesmos.$g$, NULL::text),
  ($c$foes$c$, $t$Camlash$t$, $g$Commands Lolth's forces from Hurricane Tower.$g$, NULL::text),
  ($c$foes$c$, $t$Naxa$t$, $g$In the Ruinous Citadel's vault after a cloak. Her secret: it's a key piece in a ritual they're planning.$g$, NULL::text),
  ($c$foes$c$, $t$Strahd von Zarovich$t$, $g$Arrives once the party has the fourth piece, to toy with them and block their escape from Death House.$g$, NULL::text),
  ($c$foes$c$, $t$Gustav and Elisabeth Durst$t$, $g$Run a small cult devoted to Strahd.$g$, NULL::text),
  ($c$foes$c$, $t$Galias$t$, $g$Joined the priests of Osybus.$g$, NULL::text),
  ($c$foes$c$, $t$Lord Soth$t$, $g$Teremini serves him; he doesn't appear in person by default.$g$, NULL::text),
  ($c$foes$c$, $t$Teremini Nightsedge$t$, $g$Serves Lord Soth. Her crimson-moonlight ritual warps the stolen rod piece.$g$, NULL::text),
  ($c$foes$c$, $t$Acererak$t$, $g$Off-stage: he built the Tomb of Wayward Souls and made Rerak. Some say he learned undeath from Vecna.$g$, NULL::text),
  ($c$foes$c$, $t$Tiamat$t$, $g$She holds the seventh piece. Tell her about Vecna's plan and she lets the party take it, because the Material Plane is partly her creation (guide). Act II link: her banishment upset the giant gods.$g$, NULL::text),
  ($c$foes$c$, $t$Windfall$t$, $g$Tiamat's champion; her blade sings with all five chromatic elements. Defeat her or convince her to surrender the piece.$g$, NULL::text),
  ($c$foes$c$, $t$The Lord of Blades$t$, $g$Worshipped by his blades; his strike squad races the party for Landro.$g$, NULL::text),
  ($c$foes$c$, $t$Hertilod$t$, $g$Swallowed the second rod piece and retreated into the Heart of Havock.$g$, NULL::text)
)
INSERT INTO public.the8_lore_entries (campaign_id, category, title, gm_notes, preferred_habitat, is_secret)
SELECT c.id, s.category, s.title, s.gm_notes, s.preferred_habitat, true
FROM seed s CROSS JOIN c
WHERE NOT EXISTS (SELECT 1 FROM public.the8_lore_entries e WHERE e.campaign_id = c.id AND e.title = s.title);
-- blocks: all hidden; only added to entries that have none yet, so your edits are never overwritten
WITH c AS (SELECT id FROM public.campaigns WHERE slug = 'eve-of-giants'),
seed(title, sort_order, body) AS (VALUES
  ($t$The Spider$t$, 0, $b$Someone called the Spider is paying the Cragmaw goblins. He wanted Gundren Rockseeker captured and brought to him, with everything Gundren carried.$b$),
  ($t$The Spider$t$, 1, $b$The Redbrands' leader takes orders from him too. His letters are sealed with a spider in wax.$b$),
  ($t$The Spider$t$, 2, $b$He's put a bounty on the party: hobgoblins on the Triboar Trail carry a sketch of one of them and the promise of 25 gold.$b$),
  ($t$The Spider$t$, 3, $b$The Spider is a drow.$b$),
  ($t$The Spider$t$, 4, $b$His name is Nezznar. He followed the Rockseekers to Wave Echo Cave, killed Tharden, took Nundro, and is searching the mine for the Forge of Spells.$b$),
  ($t$The Spider$t$, 5, $b$He's curious about everyone he meets, and he'll promise anything, surrender, alliance, cooperation, and break his word the moment it suits him.$b$),
  ($t$Glasstaff$t$, 0, $b$The leader of the Redbrands, known to the townsfolk by that name alone. The gang calls him that because he carries a staff of glass.$b$),
  ($t$Glasstaff$t$, 1, $b$He's a wizard. He lives under Tresendar Manor, with a workshop full of bubbling experiments.$b$),
  ($t$Glasstaff$t$, 2, $b$He puts on genteel manners: calls his thugs "my good fellows", calls kidnapping and arson "that unpleasant little business", and greets intruders as his "honoured guests".$b$),
  ($t$Glasstaff$t$, 3, $b$He takes his orders from the Spider, who promised him a share of the Forge of Spells.$b$),
  ($t$Glasstaff$t$, 4, $b$He is Iarno Albrek, the Lords' Alliance wizard Sildar came to find.$b$),
  ($t$Klarg$t$, 0, $b$The bugbear who leads the Cragmaw goblins at their hideout. He takes his orders from King Grol.$b$),
  ($t$Klarg$t$, 1, $b$He talks about himself in the third person and thinks he's a king at the start of a career of conquest: "Klarg will build a throne from your bones!"$b$),
  ($t$Klarg$t$, 2, $b$His goblins hate his bullying.$b$),
  ($t$Klarg$t$, 3, $b$He keeps a mangy pet wolf called Ripper and the best of the plunder in his own cave.$b$),
  ($t$Yeemik$t$, 0, $b$A goblin boss, second in command at the Cragmaw Hideout.$b$),
  ($t$Yeemik$t$, 1, $b$When the fight turned, he dragged Sildar to the edge of a ledge and shouted: "Truce, or this human dies!"$b$),
  ($t$Yeemik$t$, 2, $b$He wants Klarg dead so he can be leader, and promised to free Sildar in exchange for Klarg's head.$b$),
  ($t$King Grol$t$, 0, $b$The bugbear king whom every Cragmaw band grudgingly obeys, ruling from Cragmaw Castle.$b$),
  ($t$King Grol$t$, 1, $b$A fierce old bugbear, fur streaked with grey, shoulders stooped, wearing jeweled silver teeth over his own rotting fangs. Nobody crosses him.$b$),
  ($t$King Grol$t$, 2, $b$He keeps a dire wolf called Snarl.$b$),
  ($t$King Grol$t$, 3, $b$He has Gundren Rockseeker and his map, and wants to sell the map to the Spider rather than hand it over.$b$),
  ($t$Vyerith$t$, 0, $b$A drow woman with a silky voice, a guest in King Grol's quarters, come from the Spider to collect Gundren Rockseeker and his map.$b$),
  ($t$Vyerith$t$, 1, $b$She isn't a drow. She's a doppelganger.$b$),
  ($t$Vyerith$t$, 2, $b$She meant to betray the Spider: question Gundren to see who else knows where the mine is, then kill him and destroy the map.$b$),
  ($t$Vhalak$t$, 0, $b$A drow overseeing bugbears as they dig in a collapsed cavern of Wave Echo Cave.$b$),
  ($t$Vhalak$t$, 1, $b$Another doppelganger in drow guise, working for the Spider.$b$),
  ($t$Ssarnak$t$, 0, $b$A one-eyed, hunched monster that lurks by the bridges in the crevasse cave under Tresendar Manor, and speaks straight into the mind.$b$),
  ($t$Ssarnak$t$, 1, $b$It's a nothic. Glasstaff pays it in treasure and fresh meat to guard the hideout.$b$),
  ($t$Ssarnak$t$, 2, $b$It's loyal only for now, and will sell out the Redbrands for the right price, especially food.$b$),
  ($t$Zeond$t$, 0, $b$An invisible thing that watches over Glasstaff's workshop.$b$),
  ($t$Zeond$t$, 1, $b$Glasstaff's familiar: a quasit.$b$),
  ($t$Nosk$t$, 0, $b$The leader of four bugbears quartered in the Redbrand hideout.$b$),
  ($t$Nosk$t$, 1, $b$The bugbears were sent by the Spider to help Glasstaff keep Phandalin in line, and they know the way to Wave Echo Cave and to Cragmaw Castle.$b$),
  ($t$Venomfang$t$, 0, $b$A young green dragon that has taken the old tower in Thundertree, tearing in through the roof and killing the giant spiders that lived there.$b$),
  ($t$Venomfang$t$, 1, $b$He spends hours each day admiring the dead wizard's treasure.$b$),
  ($t$Venomfang$t$, 2, $b$He sneers that the big ones are stirring, and that dragons will not let a giant empire rise again.$b$),
  ($t$Favric$t$, 0, $b$An ambitious young man who leads the masked cultists hiding in Thundertree.$b$),
  ($t$Favric$t$, 1, $b$He's come to win the green dragon's allegiance and hopes to rise fast in the cult by doing it.$b$),
  ($t$Favric$t$, 2, $b$He suggests an alliance to anyone else interested in the dragon.$b$),
  ($t$Brughor Axe-Biter$t$, 0, $b$The orc who leads the marauders camped on Wyvern Tor.$b$),
  ($t$Brughor Axe-Biter$t$, 1, $b$His band noticed the extra traffic on the Triboar Trail and started ambushing travellers.$b$),
  ($t$Brughor Axe-Biter$t$, 2, $b$His band didn't come to the tor by choice. Something bigger drove them out of the hills further north.$b$),
  ($t$Gog$t$, 0, $b$An ogre who rides with the marauders on Wyvern Tor.$b$),
  ($t$Lhupo$t$, 0, $b$A goblin boss at Cragmaw Castle who calls herself a priest of the Jagged Tooth, a god the goblins made up.$b$),
  ($t$Lhupo$t$, 1, $b$She keeps a grick as a pet, and the other goblins are terrified of it.$b$),
  ($t$Yegg$t$, 0, $b$The cantankerous goblin cook of Cragmaw Castle, who shouts at his assistants all day.$b$),
  ($t$Mormesk the Wraith$t$, 0, $b$Something that was once a powerful mage still haunts the old wizards' quarters in Wave Echo Cave.$b$),
  ($t$Mormesk the Wraith$t$, 1, $b$He was the last wizard to die in the spell battle that closed the mine, and centuries of rage have poisoned his soul.$b$),
  ($t$Mormesk the Wraith$t$, 2, $b$He leads the undead of the mine, and he stays by the scorched chest that holds the treasure he can no longer touch.$b$),
  ($t$Mormesk the Wraith$t$, 3, $b$Among the things in his chest: an old map of the mine, marked with a small eye inside an open hand.$b$),
  ($t$The Flameskull$t$, 0, $b$A burning skull that guards the great smelter in Wave Echo Cave, along with a company of dead dwarf warriors.$b$),
  ($t$The Flameskull$t$, 1, $b$It served the pact's human wizards and still follows its ancient orders: nobody passes.$b$),
  ($t$The Spectator of the Forge$t$, 0, $b$A floating, many-eyed sphere that guards the Forge of Spells and speaks Common.$b$),
  ($t$The Spectator of the Forge$t$, 1, $b$A wizard of the pact summoned it to guard the forge's treasures for 101 years. The magic unravelled when the mine fell, and it still believes the mine is open for business.$b$),
  ($t$Iymrith$t$, 0, $b$A tall, matronly storm giant with a calm voice, counsellor to the storm giant court.$b$),
  ($t$Mirran$t$, 0, $b$Hekaton's eldest daughter: tempestuous, spoiled, as unpredictable as a typhoon.$b$),
  ($t$Nym$t$, 0, $b$Hekaton's middle daughter: cold, distant and calculating.$b$),
  ($t$Slarkrethel$t$, 0, $b$A legendary kraken of the Trackless Sea, worshipped on the Purple Rocks.$b$),
  ($t$Tholtz Daggerdark$t$, 0, $b$A human archmage who captains a ship nobody can find.$b$),
  ($t$Rool$t$, 0, $b$An orc on the deck of the Morkoth with a knife never far from his hand.$b$),
  ($t$Lord Khaspere Drylund$t$, 0, $b$A noble of Yartar who owns the gambling riverboat Grand Dame.$b$),
  ($t$Pow Ming$t$, 0, $b$A human mage who runs security aboard the Grand Dame.$b$),
  ($t$Chief Guh$t$, 0, $b$A monstrously fat hill giant chief who never stops eating.$b$),
  ($t$Thane Kayalithica$t$, 0, $b$An inscrutable stone giant thane whose clan has begun destroying the works of humans, dwarves and elves.$b$),
  ($t$Jarl Storvald$t$, 0, $b$A fierce, adventurous frost giant jarl who reclaimed an ancestral iceberg fortress in the Sea of Moving Ice.$b$),
  ($t$Duke Zalto$t$, 0, $b$A fire giant duke who believes he can rule all giants by slaughtering dragons.$b$),
  ($t$Duchess Brimskarda$t$, 0, $b$Duke Zalto's choleric wife, who oversees the kitchen workers at Ironslag.$b$),
  ($t$Zaltember$t$, 0, $b$Duke Zalto's teenage son.$b$),
  ($t$Countess Sansuri$t$, 0, $b$A vainglorious cloud giant countess and powerful wizard.$b$),
  ($t$Count Thullen$t$, 0, $b$Countess Sansuri's brother, a cloud giant count of Lyn Armaal.$b$),
  ($t$Cressaro$t$, 0, $b$The cloud giant castellan of Lyn Armaal.$b$),
  ($t$Okssort and Ildmane$t$, 0, $b$Two fire giants who lead an attack on Triboar.$b$),
  ($t$Cryovain$t$, 0, $b$An adult white dragon chained aboard a frost giant longship.$b$),
  ($t$Isendraug$t$, 0, $b$An adult white dragon confined in Svardborg.$b$),
  ($t$Claugiyliamatar$t$, 0, $b$Old Gnawbone, an ancient green dragon of the Kryptgarden Forest, usually seen with a mangled corpse in her jaws.$b$),
  ($t$The Weevil$t$, 0, $b$A wanted dwarf brigand.$b$),
  ($t$The Daerivoss Brothers$t$, 0, $b$Rantharl, Marthun and Lezryk Daerivoss, three middle-aged nobles from Neverwinter who came to Noanar's Hold to hunt hill giants.$b$),
  ($t$Tholzar Brenner$t$, 0, $b$A corrupt watch captain of Yartar.$b$),
  ($t$Xamlyn Margaster$t$, 0, $b$A mage of the Margaster family of Silverymoon.$b$),
  ($t$Kella Darkhope$t$, 0, $b$A woman lying low in the Nightstone Inn.$b$),
  ($t$Xolkin Alassandar$t$, 0, $b$Half-elf leader of the Seven Snakes mercenary band.$b$),
  ($t$Vecna$t$, 0, $b$The Whispered One: a lich who became a god of secrets and magic.$b$),
  ($t$Kas the Betrayer$t$, 0, $b$A vampire, legendary swordfighter and warlord: well-muscled, raven-haired, and older than he looks. Cruel, spiteful, and a liar.$b$),
  ($t$Miska the Wolf-Spider$t$, 0, $b$A demon lord imprisoned eons ago by the Wind Dukes of Aaqa.$b$),
  ($t$Lolth$t$, 0, $b$The Spider Queen, demon goddess of the drow.$b$),
  ($t$Camlash$t$, 0, $b$A demon surrounded by tiny biting spiders, wielding a flaming whip and a lightning blade.$b$),
  ($t$Naxa$t$, 0, $b$A drow mage on Pandesmos, with her sister.$b$),
  ($t$Strahd von Zarovich$t$, 0, $b$The vampire count of Barovia.$b$),
  ($t$Gustav and Elisabeth Durst$t$, 0, $b$The owners of Death House.$b$),
  ($t$Galias$t$, 0, $b$Sarusanda's father.$b$),
  ($t$Lord Soth$t$, 0, $b$A death knight and warlord, feared across Krynn.$b$),
  ($t$Teremini Nightsedge$t$, 0, $b$An archmage who holds Three Moons Vault.$b$),
  ($t$Acererak$t$, 0, $b$The Devourer, an archlich who lures adventurers into trap-filled tombs and feeds on their souls.$b$),
  ($t$Tiamat$t$, 0, $b$Queen of Evil Dragons, five-headed, whose lair lies in Avernus.$b$),
  ($t$Windfall$t$, 0, $b$The ostentatious, charismatic host of the Red Belvedere, glittering with multicoloured scales and a shimmering tailcoat.$b$),
  ($t$The Lord of Blades$t$, 0, $b$A warforged warlord of the Mournland.$b$),
  ($t$Hertilod$t$, 0, $b$A skinless, serpentine, lizardlike thing born from a dead god's corpse.$b$)
)
INSERT INTO public.the8_reveal_blocks (campaign_id, lore_entry_id, body, is_revealed, sort_order)
SELECT c.id, e.id, s.body, false, s.sort_order
FROM seed s CROSS JOIN c
JOIN public.the8_lore_entries e ON e.campaign_id = c.id AND e.title = s.title
WHERE NOT EXISTS (SELECT 1 FROM public.the8_reveal_blocks b WHERE b.lore_entry_id = e.id);

