INSERT INTO public.the8_lore_entries (campaign_id, category, title, gm_notes, preferred_habitat, is_secret)
SELECT c.id, s.category, s.title, s.gm_notes, s.preferred_habitat, true
FROM seed s CROSS JOIN c
WHERE NOT EXISTS (SELECT 1 FROM public.the8_lore_entries e WHERE e.campaign_id = c.id AND e.title = s.title);
-- blocks: all hidden; only added to entries that have none yet, so your edits are never overwritten
WITH c AS (SELECT id FROM public.campaigns WHERE slug = 'eve-of-giants'),
seed(title, sort_order, body) AS (VALUES
  ($t$Goblin$t$, 0, $b$Small, cruel raiders who strike from ambush and run when the odds turn. The Cragmaws file their teeth into points.$b$),
  ($t$Bugbear$t$, 0, $b$Big, hairy goblinoids with long arms, who move far more quietly than anything that size should.$b$),
  ($t$Hobgoblin$t$, 0, $b$Disciplined, martial goblinoids who fight in formation.$b$),
  ($t$Wolf and Dire Wolf$t$, 0, $b$Wolves run in packs. The Cragmaws keep foul-tempered ones and train them for battle.$b$),
  ($t$Owlbear$t$, 0, $b$A hulking predator with the body of a bear and the head and beak of an owl.$b$),
  ($t$Ogre$t$, 0, $b$A huge, dull-witted brute that lives to eat and smash.$b$),
  ($t$Orc$t$, 0, $b$Savage raiders who live for battle and plunder.$b$),
  ($t$Nothic$t$, 0, $b$A hunched, one-eyed creature that was once a wizard, ruined by forbidden knowledge. It can see into the secrets of others.$b$),
  ($t$Quasit$t$, 0, $b$A tiny, malicious demon that can turn invisible and change shape, often bound as a wizard's familiar.$b$),
  ($t$Skeleton$t$, 0, $b$The animated bones of the dead, bound to guard a place.$b$),
  ($t$Zombie$t$, 0, $b$Rotting dead raised by necromancy, slow and relentless.$b$),
  ($t$Ash Zombie$t$, 0, $b$Grey, ash-caked zombies left over from the plague that followed Mount Hotenow's eruption. They release a choking cloud of ash when struck.$b$),
  ($t$Ghoul$t$, 0, $b$Hungry undead that paralyse their prey with a touch and gnaw on bones.$b$),
  ($t$Twig, Needle and Vine Blights$t$, 0, $b$Plants twisted into walking, hungry things by dark magic. They stand perfectly still among ordinary bushes until prey comes close.$b$),
  ($t$Giant Spider$t$, 0, $b$Spiders the size of a horse that sense prey through their webs and drop on it.$b$),
  ($t$Stirge$t$, 0, $b$A bat-like bloodsucker with a needle nose that latches on and drinks.$b$),
  ($t$Grick$t$, 0, $b$A worm-like predator with a beaked maw ringed by tentacles, that hides on ledges and drops on prey.$b$),
  ($t$Grell$t$, 0, $b$A floating brain with a beak and long, barbed tentacles that hunts from the dark.$b$),
  ($t$Doppelganger$t$, 0, $b$A shapeshifter that can take any humanoid's form and read surface thoughts.$b$),
  ($t$Ochre Jelly$t$, 0, $b$A creeping, acidic ooze that splits when struck with blades or lightning.$b$),
  ($t$Violet Fungus$t$, 0, $b$A purple mushroom that lashes out with rotting tendrils, hidden among harmless fungi.$b$),
  ($t$Giant Constrictor Snake$t$, 0, $b$A snake long enough to wrap a horse.$b$),
  ($t$Giant Octopus$t$, 0, $b$A huge octopus drawn to light above the water.$b$),
  ($t$Flameskull$t$, 0, $b$A burning skull bound to undeath by wizardry, which casts spells and reforms unless destroyed properly.$b$),
  ($t$Wraith$t$, 0, $b$The hate-filled spirit of a powerful soul, whose touch drains life.$b$),
  ($t$Spectator$t$, 0, $b$A lesser beholder summoned from another plane to guard a treasure.$b$),
  ($t$Banshee$t$, 0, $b$The spirit of a vain elf woman, whose wail can kill.$b$),
  ($t$Young Green Dragon$t$, 0, $b$A green dragon not yet grown: cunning, cruel and greedy, with a poisonous breath.$b$),
  ($t$Hill Giant$t$, 0, $b$The smallest and dullest of the true giants, and always hungry. In their society, the biggest rules.$b$),
  ($t$Stone Giant$t$, 0, $b$Reclusive giants who live underground, see the surface as a dream, and rank themselves by sculpture.$b$),
  ($t$Frost Giant$t$, 0, $b$Merciless raiders of the cold north who rank themselves by martial prowess.$b$),
  ($t$Fire Giant$t$, 0, $b$Militaristic forge-masters who rank themselves by their craft.$b$),
  ($t$Cloud Giant$t$, 0, $b$Aloof aristocrats who live in castles on clouds and love wealth and wagers.$b$),
  ($t$Storm Giant$t$, 0, $b$The highest of the giants: seers who live in the sea and the storm.$b$),
  ($t$Ancient Blue Dragon$t$, 0, $b$A vast blue dragon of the deserts, master of lightning and of lies.$b$),
  ($t$White Dragon$t$, 0, $b$Savage, cold-loving dragons of ice and snow.$b$),
  ($t$Kraken$t$, 0, $b$A titan of the deep that drags ships under.$b$),
  ($t$Orog$t$, 0, $b$Big, disciplined orcs bred for war.$b$),
  ($t$Axe Beak$t$, 0, $b$A tall, flightless bird with a hatchet-shaped beak.$b$),
  ($t$Magmin$t$, 0, $b$A small, gleeful creature of living magma that sets everything alight.$b$),
  ($t$Yakfolk$t$, 0, $b$Yak-headed giants who seem kindly hosts. They aren't.$b$),
  ($t$Blood Hawk$t$, 0, $b$A crimson-feathered hawk that hunts in flocks.$b$),
  ($t$Tressym$t$, 0, $b$A winged cat.$b$),
  ($t$Gargoyle$t$, 0, $b$A winged fiend of living stone that can stand perfectly still.$b$),
  ($t$Cambion$t$, 0, $b$The child of a fiend and a mortal, often a schemer or enforcer.$b$),
  ($t$Crag Cat$t$, 0, $b$A big mountain cat whose hide turns spells aside.$b$),
  ($t$Hulking Crab$t$, 0, $b$A crab the size of a boulder, often mistaken for one.$b$),
  ($t$Uthgardt Shaman$t$, 0, $b$A barbarian spirit-talker who guards an Uthgardt tribe's traditions.$b$),
  ($t$Maegera$t$, 0, $b$A fire primordial of immense power, trapped beneath Gauntlgrym.$b$),
  ($t$Spyder-Fiend$t$, 0, $b$Demonic beasts with bloated spider bodies and wolf heads, usually coated in gore.$b$),
  ($t$Citadel Spider$t$, 0, $b$A titanic spider bred by Lolth's followers as a living war machine.$b$),
  ($t$Spiderdragon$t$, 0, $b$A black dragon raised from a wyrmling on a diet of spiders.$b$),
  ($t$Sorrowsworn$t$, 0, $b$Shadowfell creatures that embody suffering; the lonely and the lost kinds hunt those who wander alone.$b$),
  ($t$Star Angler$t$, 0, $b$A golden, eyeless astral anglerfish speckled with light.$b$),
  ($t$Night Scavver$t$, 0, $b$A sharklike scavenger that flies through space, trailing larger creatures.$b$),
  ($t$Eye Monger$t$, 0, $b$A one-eyed horror that looks like a 12-foot asteroid until it opens its mouth.$b$),
  ($t$Astral Dreadnought$t$, 0, $b$A titanic astral predator that has devoured everything in its path since the dawn of the multiverse.$b$),
  ($t$Cosmic Horror$t$, 0, $b$A colossal Far Realm entity adrift on the Astral Plane, drawn to distant stars.$b$),
  ($t$Warforged Warrior$t$, 0, $b$A soldier of wood and steel created for the Last War.$b$),
  ($t$Blazebear$t$, 0, $b$A hulking, bearlike monster of the Mournland with glowing eyes.$b$),
  ($t$Granite Juggernaut$t$, 0, $b$A lumbering, boxy construct that rolls on massive rollers.$b$),
  ($t$Inquisitor of the Tome$t$, 0, $b$An Ulmist inquisitor of Barovia.$b$),
  ($t$Priest of Osybus$t$, 0, $b$A soul-stealing necromancer of Barovia.$b$),
  ($t$Relentless Impaler$t$, 0, $b$A hulking fiendish killer made by a ritual with a ceremonial stake through the heart.$b$),
  ($t$Whirling Chandelier$t$, 0, $b$An animated chandelier with a capricious streak and a blazing spin.$b$),
  ($t$Black Rose Bearer$t$, 0, $b$A rotting corpse guardian carrying a preserved black rose in a bell jar.$b$),
  ($t$Moonlight Guardian$t$, 0, $b$A gleaming statue of silver and mithral made to fight lycanthropes.$b$),
  ($t$Deathwolf$t$, 0, $b$An undead werewolf empowered by the full moon.$b$),
  ($t$Borthak$t$, 0, $b$An irascible, wolflike behemoth with acid spittle and a lightning-quick tail.$b$),
  ($t$Deadbark Dryad$t$, 0, $b$A dryad turned wicked after failing to protect its home.$b$),
  ($t$Lunar Dragon$t$, 0, $b$A capricious, xenophobic dragon that burrows through rock; also called a moon or phase dragon.$b$),
  ($t$False Lich$t$, 0, $b$A corpse bound to a shred of a lich's life force to serve as a decoy or guardian.$b$),
  ($t$Abishai$t$, 0, $b$Draconic devils, mortals transformed by Tiamat to serve her in the Nine Hells.$b$),
  ($t$Cadaver Collector$t$, 0, $b$An ancient war machine from Acheron that gathers the dead for necromancers.$b$),
  ($t$Degloth$t$, 0, $b$A massive blue demon with razor-studded fists, used as shock troops.$b$),
  ($t$Vlazok$t$, 0, $b$A skeletal, four-legged horror that tramples battlefields after the fighting.$b$),
  ($t$Hazvongel$t$, 0, $b$A huge crimson crowlike demon with a dozen legs and wings that drip blood.$b$),
  ($t$Bone Roc$t$, 0, $b$A birdlike undead built from the bones of flying creatures.$b$),
  ($t$Mirror Shade$t$, 0, $b$The incorporeal spirit of a trickster who refused the afterlife, a shape of shining light.$b$),
  ($t$Wight$t$, 0, $b$Undead that drain the life of the living and command lesser dead.$b$),
  ($t$Vampire Spawn$t$, 0, $b$The thralls of a vampire, hungry and cunning.$b$)
)
INSERT INTO public.the8_reveal_blocks (campaign_id, lore_entry_id, body, is_revealed, sort_order)
SELECT c.id, e.id, s.body, false, s.sort_order
FROM seed s CROSS JOIN c
JOIN public.the8_lore_entries e ON e.campaign_id = c.id AND e.title = s.title
WHERE NOT EXISTS (SELECT 1 FROM public.the8_reveal_blocks b WHERE b.lore_entry_id = e.id);

