INSERT INTO public.the8_lore_entry_factions (lore_entry_id, faction_entry_id)
SELECT e.id, t.id
FROM links l CROSS JOIN c
JOIN public.the8_lore_entries e ON e.campaign_id = c.id AND e.title = l.entry_title
JOIN public.the8_lore_entries t ON t.campaign_id = c.id AND t.title = l.target_title AND t.category = 'factions'
ON CONFLICT (lore_entry_id, faction_entry_id) DO NOTHING;

