  ($a$Lord Soth$a$, $d$Krynn$d$),
  ($a$The Tomb of Wayward Souls$a$, $d$The Isle of Serpents$d$),
  ($a$Rerak$a$, $d$The Tomb of Wayward Souls$d$),
  ($a$Marian Xavere$a$, $d$The Isle of Serpents$d$),
  ($a$The Red Belvedere$a$, $d$Avernus$d$),
  ($a$Windfall$a$, $d$The Red Belvedere$d$),
  ($a$Tiamat$a$, $d$Avernus$d$),
  ($a$Abishai$a$, $d$Avernus$d$),
  ($a$Carapace Ridge$a$, $d$Pandemonium$d$),
  ($a$The Ruinous Sea$a$, $d$Pandemonium$d$),
  ($a$Hurricane Tower$a$, $d$Pandemonium$d$),
  ($a$The Ruinous Citadel$a$, $d$Pandemonium$d$),
