INSERT INTO public.the8_lore_entry_locations (lore_entry_id, location_entry_id)
SELECT e.id, t.id
FROM links l CROSS JOIN c
JOIN public.the8_lore_entries e ON e.campaign_id = c.id AND e.title = l.entry_title
JOIN public.the8_lore_entries t ON t.campaign_id = c.id AND t.title = l.target_title AND t.category = 'locations'
ON CONFLICT (lore_entry_id, location_entry_id) DO NOTHING;

-- ---------------------------------------------------------------------------
-- 9. QUESTS  (65, in rough story order)
-- ---------------------------------------------------------------------------
WITH c AS (SELECT id FROM public.campaigns WHERE slug = 'eve-of-giants'),
seed(title, sort_order, reward_gold, reward_other, gm_notes) AS (VALUES
  ($t$Escort the Supply Wagon$t$, 10, 10, $o$10 gp each from Elmina Barthen$o$, $g$Two oxen; cargo worth 100 gp. Ask how each character knows Gundren.$g$),
  ($t$Follow the Goblin Trail$t$, 20, 0, NULL::text, $g$Snare, then a pit; five miles to the Cragmaw Hideout.$g$),
  ($t$Rescue Sildar Hallwinter$t$, 30, 0, $o$Sildar's friendship and what he knows$o$, $g$He's at 1 hp in H6.$g$),
  ($t$Return the Lionshield Goods$t$, 40, 50, $o$50 gp and Linene's help$o$, NULL::text),
  ($t$Find Iarno Albrek$t$, 50, 0, NULL::text, $g$Once Sildar knows, he wants Iarno tried in Neverwinter.$g$),
  ($t$End the Redbrands$t$, 60, 200, $o$200 gp from Sildar$o$, $g$Level 3 on finishing the hideout.$g$),
  ($t$Halia's Job$t$, 70, 100, $o$100 gp$o$, $g$She wants Glasstaff out of the way so she can take over the Redbrands (DC 15 Insight).$g$),
  ($t$Rescue the Dendrar Family$t$, 80, 0, $o$Mirna tells of a family heirloom$o$, NULL::text),
  ($t$The Banshee's Bargain$t$, 90, 0, $o$Three potions of healing$o$, $g$Agatha answers only one question. The comb makes the Persuasion check automatic.$g$),
  ($t$Who Digs at Old Owl Well$t$, 100, 0, $o$Daran's boots of striding and springing$o$, $g$Hamun trades information for the Wyvern Tor marauders being driven off, or for Agatha's answer to who built the tower (Dresina).$g$),
  ($t$The Marauders of Wyvern Tor$t$, 110, 100, $o$100 gp from Harbin Wester$o$, $g$Also satisfies Hamun Kost.$g$),
  ($t$Find Reidoth$t$, 120, 0, $o$Directions to Cragmaw Castle$o$, $g$Reidoth gives them if the party respects her, or trades them for chasing off Venomfang.$g$),
  ($t$The Dendrar Heirloom$t$, 130, 0, $o$A gold necklace with an emerald pendant (200 gp)$o$, $g$In a case in a compartment under the storage shelves (U9).$g$),
  ($t$Find Cragmaw Castle$t$, 140, 500, $o$500 gp from Sildar$o$, $g$Sources: captured Cragmaws, Reidoth, Agatha, Hamun Kost, Nosk's bugbears (by force or charm).$g$),
  ($t$Rescue Gundren Rockseeker$t$, 150, 0, $o$25 gp each and a tenth share of the mine$o$, $g$He's unconscious in C14; Vyerith plans to kill him after questioning.$g$),
  ($t$Find Wave Echo Cave$t$, 160, 0, NULL::text, $g$Fifteen miles east of Phandalin. Map from Grol, or directions from Agatha, Reidoth, Hamun or the bugbears.$g$),
  ($t$Rescue Nundro Rockseeker$t$, 170, 0, NULL::text, $g$W20; Nezznar has the key.$g$),
  ($t$Stop the Spider$t$, 180, 0, $o$Level 5$o$, $g$W19. If jailed in Phandalin unguarded, Halia frees him.$g$),
  ($t$The Forge of Spells$t$, 190, 0, $o$Lightbringer, Tergon's breastplate, a few hours of +1 from the green flame$o$, $g$Its magic has faded: no permanent enchantments any more.$g$),
  ($t$The Feast and the Letters to Triboar$t$, 195, 0, $o$Passage into Act II$o$, $g$Act I cliffhanger (ours, built on SKT Appendix A's hooks). On the night of the feast, fire giant scouts with a glowing rod circle the hills above Wave Echo Cave, find the entrance collapsed, and march east. The party reaches Triboar as those same giants attack it (SKT ch. 2). Level 5 by now.$g$),
  ($t$Defend Triboar$t$, 200, 0, $o$Level 6; a quest from every townsperson who survives$o$, $g$SKT ch. 2. Okssort and Ildmane retreat if either drops to 81 hp or fewer. Each player runs one Triboar NPC during the battle; every NPC who survives gives a quest. The Vonindod fragment under the campground connects to Act I's plate (ours).$g$),
  ($t$Darathra's Badge$t$, 210, 0, $o$Free use of the Harper teleportation circles; a coffer of gifts$o$, $g$PUSH THIS ONE (guide). Dral's wine teleports the party to Moongleam Tower; Krowen Valharrow opens the circle network. Cures chapter 3's travel problem.$g$),
  ($t$The Giant Slayer$t$, 220, 0, $o$A giant slayer greatsword (or greataxe)$o$, $g$PUSH THIS ONE (guide). Harthos's disowned son Harthal stole it; the Hand of Yartar reveals Harthal's in jail and the sword is with Captain Tholzar Brenner. Introduces Yartar before ch. 11.$g$),
  ($t$Harnesses for Noanar's Hold$t$, 230, 100, $o$100 gp, plus the cart and its horse, Boris$o$, $g$The delivery is thankless; the night at the White Hart Inn starts the Daerivoss brothers' hill giant hunt and a murder mystery over a 10,000 gp inheritance.$g$),
  ($t$Catch the Weevil$t$, 240, 5000, $o$5,000 gp, if delivered alive to Mirabar$o$, $g$Good filler (guide), and a good side session.$g$),
  ($t$The Margaster Stash$t$, 250, 0, $o$Four magic items$o$, $g$Carriage house: arcane lock on the door, alarm on the carriage, two cambions disguised as guards, and Xamlyn Margaster on round three.$g$),
  ($t$A Letter to Citadel Felbarr$t$, 260, 0, $o$Two figurines of wondrous power (golden lions)$o$, $g$A long walk for a strong reward.$g$),
  ($t$Linene's Letter to Alaestra Ulgar$t$, 265, 0, NULL::text, $g$SKT Appendix A hook for parties coming from Lost Mine. Deliver it after the battle.$g$),
  ($t$Moog's Missing Husband$t$, 270, 0, $o$A guide to Grudd Haug$o$, $g$Chief Guh took Hruk. Moog leads the party to Grudd Haug but won't fight hill giants. A breather on any road (guide).$g$),
  ($t$Follow Harshnag to the Oracle$t$, 280, 0, $o$Level 7 on arrival$o$, $g$Use Harshnag when chapter 3 drifts; cap the sandbox at about six sessions (guide).$g$),
  ($t$Questions for the Oracle$t$, 290, 0, $o$The truth: Iymrith, the conch, and the giant lords$o$, $g$Make sure someone at the table speaks Giant (guide). The key answers are in the Eye of the All-Father entry.$g$),
  ($t$Relics from the Spirit Mounds$t$, 300, 0, $o$One giant lord revealed per relic$o$, $g$One or two relics are enough (guide). Beorunna's Well (cracked horn) and One Stone (magic boulder): Kayalithica. Flint Rock (mithral spear tip) and Shining White (porcelain mask): Sansuri. Grandfather Tree (electrum nose-ring): Guh. Great Worm Cavern (broken shield) and Stone Stand (frost giant skull): Storvald. Morgur's Mound (gold-plated tooth): Zalto. Raven Rock: magma ring (Zalto) and bone greatclub (Guh). Majority vote in the mithral circle chooses the foe. Klauth's airship arrives as the party leaves.$g$),
  ($t$Harshnag's Last Stand$t$, 310, 0, $o$Level 8$o$, $g$Iymrith arrives to consult the oracle. Harshnag charges her and shouts for the party to run; if they won't, he chips Annam's statue and the temple collapses on giant and dragon. The emotional peak of Act II (guide).$g$),
  ($t$The Conch of the Fire Giant Duke$t$, 320, 0, $o$A conch of teleportation; level 9$o$, $g$Recommended lord (guide). The conch is probably in his iron chest; Cinderhild or Zaltember can be leverage.$g$),
  ($t$The Conch of the Frost Giant Jarl$t$, 330, 0, $o$A conch of teleportation; level 9$o$, $g$Alternative lord (guide). The conch lies on the ice throne; the Krigvind is coming home.$g$),
  ($t$The Conch of the Hill Giant Chief$t$, 340, 0, $o$A conch of teleportation; level 9$o$, $g$OPTIONAL unless voted. It's hidden under her bulk.$g$),
  ($t$The Conch of the Stone Giant Thane$t$, 350, 0, $o$A conch of teleportation; level 9$o$, $g$OPTIONAL unless voted. In a pouch on her mithral belt.$g$),
  ($t$The Conch of the Cloud Giant Countess$t$, 360, 0, $o$A conch of teleportation; level 9$o$, $g$OPTIONAL unless voted. She'll trade it for her life or her twins'.$g$),
  ($t$Free Felgolos$t$, 365, 0, $o$A bronze dragon's gratitude$o$, $g$OPTIONAL; only in Lyn Armaal.$g$),
  ($t$The Court of the Storm Giants$t$, 370, 0, $o$The golden goose chip$o$, $g$SKT ch. 10, no level. Watch for Iymrith's 'abducted' slip (DC 15 Insight). Exposed early, she escapes with the Korolnor Scepter; that speeds up ch. 11, it doesn't break it (guide).$g$),
  ($t$The Golden Goose$t$, 380, 0, $o$Where Hekaton is held$o$, $g$SKT ch. 11: the chip is from Lord Drylund's Grand Dame in Yartar. Drylund names the Morkoth, then dies to Slarkrethel's telepathy.$g$),
  ($t$Rescue King Hekaton$t$, 390, 0, $o$Level 10$o$, $g$The Morkoth. Linger more than an hour after freeing him and Slarkrethel destroys the ship. The attempt earns the level.$g$),
  ($t$Doom of the Desert$t$, 400, 0, $o$Level 11; a potion of giant size each; the storm giants' alliance$o$, $g$SKT ch. 12. Hekaton or Serissa plus the storm giant hunters, riding whales and rocs. Afterwards Hekaton swears an alliance against dragons and leaves the remaining lords to the party: every two extra lords defeated is worth a level (guide).$g$),
  ($t$The Remaining Giant Lords$t$, 410, 0, $o$A level for every two lords defeated$o$, $g$OPTIONAL. Stay here a while if the table loves giants (guide).$g$),
  ($t$Shivering Death$t$, 420, 0, NULL::text, $g$OPTIONAL finale side quest (guide): Dragon Delves ch. 8, level 11, the adult white dragon Challidax.$g$),
  ($t$Nightstone's Missing Villagers$t$, 450, 0, NULL::text, $g$OPTIONAL (SKT ch. 1, low level). They're in the Dripping Caves with the goblins; Kella Darkhope and the Seven Snakes complicate things.$g$),
  ($t$Morak's Errand$t$, 455, 0, NULL::text, $g$OPTIONAL (SKT ch. 1). Zephyros offers a lift in his flying tower.$g$),
  ($t$The Frost Giants of Bryn Shander$t$, 460, 0, $o$Quests from six townsfolk$o$, $g$OPTIONAL. They hunt Sirac of Suzail, Artus Cimber's son.$g$),
  ($t$The Hill Giants of Goldenfields$t$, 470, 0, $o$Quests from six townsfolk$o$, $g$OPTIONAL. Guh's raiders.$g$),
  ($t$Bryn Shander Errands$t$, 480, 0, $o$Gems, a clockwork dog, titles, and contacts across the North$o$, $g$OPTIONAL. Augrek → Ironmaster; Beldora → Hundelstone; Duvessa → the Dancing Wave mystery; Markham → patrol Icewind Dale; Sir Baric → Sir Lanniver in Neverwinter; Sirac → the Roaringhorns in Waterdeep.$g$),
  ($t$Goldenfields Errands$t$, 490, 0, $o$Magic items, a summoning ring, and contacts across the North$o$, $g$OPTIONAL. Lifferlas → Turlang at Shadowtop Cathedral; Miros → Arleosa in Amphail; Naxene → Chazlauth in Waterdeep; Oren → the Happy Cow in Daggerford; Shalvus → Bargewright Inn; Zi Liang → House Thann in Waterdeep.$g$),
  ($t$The Vanished of Neverwinter$t$, 600, 9000, $o$A fine house in Neverwinter for each hero, and 9,000 gp; level 11 if not already$o$, $g$Eve of Ruin ch. 1. The bridge (guide): the famous heroes of the North are the obvious hire, and the rumour of missing people 'who knew things' was seeded in Act I. A level 11 party simply skips the level-up.$g$),
  ($t$Escape Evernight$t$, 610, 0, $o$Vecna's Link$o$, $g$Find a Crevice of Dusk via Sangora and the Dolindar Tomb.$g$),
  ($t$The Wizards' Summons$t$, 620, 0, NULL::text, $g$Eve of Ruin ch. 2. 'Mordenkainen' proposes the Rod of Seven Parts. Let a player notice Malaina's unease.$g$),
  ($t$The First Piece: Web's Edge$t$, 630, 0, $o$Rod piece 1 (commune); level 12$o$, $g$Area W12. Gertrude's secret in W6a.$g$),
  ($t$The Second Piece: The Lambent Zenith$t$, 640, 0, $o$Rod piece 2 (arcane gate); level 13$o$, $g$Eve of Ruin ch. 3. The hertilod swallowed it. Secrets: Figaro, Ikasa.$g$),
  ($t$The Third Piece: The Ruined Colossus$t$, 650, 0, $o$Rod piece 3 (reverse gravity); level 14$o$, $g$Eve of Ruin ch. 4. A docent tunes the rod to Landro's graymatter engine. Secrets: Mercy, Kalyth.$g$),
  ($t$The Fourth Piece: Death House$t$, 660, 0, $o$Rod piece 4 (regenerate); level 15$o$, $g$Eve of Ruin ch. 5. Sarusanda's secret. Strahd at the end.$g$),
  ($t$The Fifth Piece: Night of Blue Fire$t$, 670, 0, $o$Rod piece 5 (find the path); level 16$o$, $g$Eve of Ruin ch. 6. Peylon tree → Bittergrass Fen → Blue Fire Wardens → Three Moons Vault; rescue Valendar, disrupt Teremini's ritual. Secrets: Gazaia, Valendar.$g$),
  ($t$Rescue Valendar$t$, 675, 0, $o$The wardens' gratitude$o$, $g$Area V7.$g$),
  ($t$The Sixth Piece: Tomb of Wayward Souls$t$, 680, 0, $o$Rod piece 6 (mirage arcane); level 17$o$, $g$Eve of Ruin ch. 7. Help the archaeologists against the kraken or not. Rerak can become an ally. Secrets: Marian, Rerak.$g$),
  ($t$The Seventh Piece: The Dragon Queen's Pride$t$, 690, 0, $o$Rod piece 7 (simulacrum); level 18$o$, $g$Eve of Ruin ch. 8. Win entry to Dragon's Pride; beat Windfall, or tell Tiamat what Vecna intends.$g$),
  ($t$The Betrayer Revealed$t$, 700, 0, $o$Level 19, on reaching Carapace Ridge$o$, $g$Eve of Ruin ch. 9. Kas reveals himself, wounds Alustriel and Tasha, and flees to Pandemonium with the rod. Malaina's secret. Tell the players at the Act II break that the campaign is going planar (guide).$g$),
  ($t$The War of Pandesmos$t$, 710, 0, $o$Vecna's location; level 20$o$, $g$Eve of Ruin ch. 10. Weaken Kas enough to banish him with the Chime of Exile. Secrets: Naxa, Kas.$g$),
  ($t$Eve of Ruin$t$, 720, 0, $o$The multiverse$o$, $g$Eve of Ruin ch. 11. Torment of Kas, Neverwinter's New King, Dead Gods, then the Cave of Shattered Reflection. Show who Vecna would put on Neverwinter's throne (guide).$g$)
)
INSERT INTO public.the8_quests (campaign_id, title, status, sort_order, reward_gold, reward_other, gm_notes, is_secret)
SELECT c.id, s.title, 'available', s.sort_order, s.reward_gold, s.reward_other, s.gm_notes, true
FROM seed s CROSS JOIN c
WHERE NOT EXISTS (SELECT 1 FROM public.the8_quests x WHERE x.campaign_id = c.id AND x.title = s.title);
WITH c AS (SELECT id FROM public.campaigns WHERE slug = 'eve-of-giants'),
seed(title, sort_order, body) AS (VALUES
  ($t$Escort the Supply Wagon$t$, 0, $b$Gundren Rockseeker hired the party in Neverwinter to drive a wagon of mining supplies and food to Barthen's Provisions in Phandalin, where they'll be paid 10 gold pieces each.$b$),
  ($t$Escort the Supply Wagon$t$, 1, $b$Gundren rode ahead with Sildar Hallwinter to see to business in town.$b$),
  ($t$Follow the Goblin Trail$t$, 0, $b$Goblins ambushed Gundren and Sildar on the Triboar Trail. A trail leads north-west from the ambush site.$b$),
  ($t$Follow the Goblin Trail$t$, 1, $b$About a dozen goblins came and went this way, dragging two human-sized bodies.$b$),
  ($t$Rescue Sildar Hallwinter$t$, 0, $b$Sildar Hallwinter, Gundren's escort, is a prisoner in the Cragmaw Hideout.$b$),
  ($t$Rescue Sildar Hallwinter$t$, 1, $b$The goblin Yeemik offers to free him in exchange for Klarg's head.$b$),
  ($t$Return the Lionshield Goods$t$, 0, $b$Linene Graywind's latest Lionshield caravan never reached Phandalin.$b$),
  ($t$Return the Lionshield Goods$t$, 1, $b$The crates, marked with a blue lion, are in the Cragmaw Hideout.$b$),
  ($t$Find Iarno Albrek$t$, 0, $b$Sildar asks the party to find Iarno Albrek, a Lords' Alliance wizard who vanished while exploring around Tresendar Manor about two months ago.$b$),
  ($t$Find Iarno Albrek$t$, 1, $b$Iarno is Glasstaff.$b$),
  ($t$End the Redbrands$t$, 0, $b$The Redbrands bully all of Phandalin from their hideout under Tresendar Manor. Sildar will pay to see them ended.$b$),
  ($t$End the Redbrands$t$, 1, $b$Daran Edermath wants someone to stand up to them. The townmaster eventually admits they should be caught and tried.$b$),
  ($t$Halia's Job$t$, 0, $b$Halia Thornton offers 100 gold pieces to capture the Redbrands' leader, Glasstaff, and bring her any correspondence from his quarters.$b$),
  ($t$Rescue the Dendrar Family$t$, 0, $b$Thel Dendrar was murdered by the Redbrands. His wife Mirna and their children Nilsa and Nars disappeared the same day.$b$),
  ($t$Rescue the Dendrar Family$t$, 1, $b$They're held in cells under Tresendar Manor.$b$),
  ($t$The Banshee's Bargain$t$, 0, $b$Sister Garaele asks the party to take a jeweled silver comb to the banshee Agatha, near Conyberry, and ask where the spellbook of the mage Bowgentle is.$b$),
  ($t$The Banshee's Bargain$t$, 1, $b$Agatha answered: she traded it to a necromancer named Tsernoth, of Iriaebor, more than a hundred years ago.$b$),
  ($t$Who Digs at Old Owl Well$t$, 0, $b$Daran Edermath wants to know who is digging at Old Owl Well, where prospectors say undead chased them off.$b$),
  ($t$Who Digs at Old Owl Well$t$, 1, $b$A Red Wizard of Thay named Hamun Kost is excavating the ruins with zombie labour.$b$),
  ($t$The Marauders of Wyvern Tor$t$, 0, $b$The townmaster offers 100 gold pieces to drive off the marauders attacking caravans near Wyvern Tor.$b$),
  ($t$The Marauders of Wyvern Tor$t$, 1, $b$They're an orc, Brughor Axe-Biter, with bugbears and an ogre named Gog.$b$),
  ($t$Find Reidoth$t$, 0, $b$Qelline Alderleaf says her friend Reidoth the druid knows every inch of the land, and went to the ruins of Thundertree.$b$),
  ($t$The Dendrar Heirloom$t$, 0, $b$Mirna Dendrar's family hid an emerald necklace in their herb and alchemy shop in Thundertree when they fled. The shop is in the south-east of the ruins.$b$),
  ($t$Find Cragmaw Castle$t$, 0, $b$Gundren and his map were taken to King Grol at a place called Cragmaw Castle. Nobody in Phandalin knows where it is.$b$),
  ($t$Find Cragmaw Castle$t$, 1, $b$Sildar pays 500 gold pieces to whoever finds it and defeats or drives off its leader.$b$),
  ($t$Rescue Gundren Rockseeker$t$, 0, $b$Gundren is a prisoner of King Grol at Cragmaw Castle.$b$),
  ($t$Find Wave Echo Cave$t$, 0, $b$The lost mine of the Phandelver Pact lies somewhere in the hills. Gundren's map shows the way.$b$),
  ($t$Rescue Nundro Rockseeker$t$, 0, $b$Gundren's brothers Tharden and Nundro were guarding the find and haven't come back to town.$b$),
  ($t$Rescue Nundro Rockseeker$t$, 1, $b$Tharden is dead at the camp. Nundro is a prisoner somewhere in the mine.$b$),
  ($t$Stop the Spider$t$, 0, $b$Someone called the Spider is behind the Cragmaws and the Redbrands, and wants Wave Echo Cave for himself.$b$),
  ($t$Stop the Spider$t$, 1, $b$The Spider is Nezznar, a drow, searching the mine for the Forge of Spells.$b$),
  ($t$The Forge of Spells$t$, 0, $b$At the heart of the mine stands the forge the pact was built around, guarded by something that still thinks the mine is open.$b$),
  ($t$The Feast and the Letters to Triboar$t$, 0, $b$After the mine is won, Phandalin throws a feast. The next morning Linene Graywind has a letter for Alaestra Ulgar in Triboar, and Harbin Wester a much ruder one for Triboar's lord protector, Darathra Shendrel.$b$),
  ($t$Defend Triboar$t$, 0, $b$Fire giants march on Triboar with orcs, orogs and creatures of living flame. They're digging for something under the north campground.$b$),
  ($t$Darathra's Badge$t$, 0, $b$Darathra Shendrel asks the party to carry her platinum badge east along the Evermoor Way to Dral Thelev at Danivarr's House in Everlund.$b$),
  ($t$The Giant Slayer$t$, 0, $b$Urgala Meltimer's old comrade, Lord Harthos Zymorven, owns a giant slayer greatsword. She thinks he'd part with it for the right cause.$b$),
  ($t$Harnesses for Noanar's Hold$t$, 0, $b$Narth Tezrin needs five harnesses delivered to the castellan of Noanar's Hold, near the High Forest.$b$),
  ($t$Catch the Weevil$t$, 0, $b$Darz Helgar heard that a wanted brigand called the Weevil is cleaning stables at Xantharl's Keep on the Long Road.$b$),
  ($t$The Margaster Stash$t$, 0, $b$Othovir knows where his Margaster kin in Silverymoon hide magic items for emergencies.$b$),
  ($t$A Letter to Citadel Felbarr$t$, 0, $b$Ghelryn Foehammer writes a letter of recommendation for the king and queen of Citadel Felbarr.$b$),
  ($t$Linene's Letter to Alaestra Ulgar$t$, 0, $b$Linene Graywind's letter for Alaestra Ulgar in Triboar.$b$),
  ($t$Moog's Missing Husband$t$, 0, $b$A hill giant in an old tower is singing her heart out over a husband who was taken from her.$b$),
  ($t$Follow Harshnag to the Oracle$t$, 0, $b$A legendary frost giant offers to lead the party to an ancient giant temple under the Spine of the World, where an oracle might explain what has happened to the giants.$b$),
  ($t$Questions for the Oracle$t$, 0, $b$The oracle of the Eye of the All-Father answers six questions a day, in Giant.$b$),
  ($t$Relics from the Spirit Mounds$t$, 0, $b$The oracle demands tribute: giant relics buried under the Uthgardt spirit mounds. Each one offered reveals a giant lord who holds one of Hekaton's conchs.$b$),
  ($t$Harshnag's Last Stand$t$, 0, $b$Something vast comes to the Eye of the All-Father while the party is there.$b$),
  ($t$The Conch of the Fire Giant Duke$t$, 0, $b$Duke Zalto holds one of King Hekaton's conchs in Ironslag, beneath the Ice Spires.$b$),
  ($t$The Conch of the Frost Giant Jarl$t$, 0, $b$Jarl Storvald holds one of King Hekaton's conchs in Svardborg, in the Sea of Moving Ice.$b$),
  ($t$The Conch of the Hill Giant Chief$t$, 0, $b$Chief Guh holds one of King Hekaton's conchs in Grudd Haug.$b$),
  ($t$The Conch of the Stone Giant Thane$t$, 0, $b$Thane Kayalithica holds one of King Hekaton's conchs in Deadstone Cleft.$b$),
  ($t$The Conch of the Cloud Giant Countess$t$, 0, $b$Countess Sansuri holds one of King Hekaton's conchs in her drifting castle, Lyn Armaal.$b$),
  ($t$Free Felgolos$t$, 0, $b$A bronze dragon is being tortured aboard Countess Sansuri's cloud castle.$b$),
  ($t$The Court of the Storm Giants$t$, 0, $b$Hekaton's conch carries the party to Maelstrom, where Princess Serissa rules as regent.$b$),
  ($t$The Golden Goose$t$, 0, $b$A wooden gambling chip painted with a golden goose was found beside Queen Neri's body.$b$),
  ($t$Rescue King Hekaton$t$, 0, $b$The storm giant king is chained aboard a ship that circles the islands of the Trackless Sea, hidden from scrying.$b$),
  ($t$Doom of the Desert$t$, 0, $b$Storm giants and small folk ride together to Anauroch to end the dragon who started all of this.$b$),
  ($t$The Remaining Giant Lords$t$, 0, $b$With Iymrith dead, the other giant lords are still out there.$b$),
  ($t$Shivering Death$t$, 0, $b$Frost giant siblings are feuding inside a white dragon's ice caves.$b$),
  ($t$Nightstone's Missing Villagers$t$, 0, $b$Nightstone was bombarded from the sky and its people are missing.$b$),
  ($t$Morak's Errand$t$, 0, $b$Morak Ur'gray asks the party to carry news of the giant attack to a friend's family in Bryn Shander, Goldenfields or Triboar.$b$),
  ($t$The Frost Giants of Bryn Shander$t$, 0, $b$Frost giants descend on Bryn Shander looking for one person.$b$),
  ($t$The Hill Giants of Goldenfields$t$, 0, $b$Hill giants raid Goldenfields' fields and storehouses.$b$),
  ($t$Bryn Shander Errands$t$, 0, $b$The survivors of Bryn Shander each have a favour to ask.$b$),
  ($t$Goldenfields Errands$t$, 0, $b$The survivors of Goldenfields each have a favour to ask.$b$),
  ($t$The Vanished of Neverwinter$t$, 0, $b$Lord Neverember asks the party to investigate four kidnappings: a planar scholar, a society actor, a sorcerer and a historian. Divinations lead to Hallix Mausoleum in Neverdeath Graveyard.$b$),
  ($t$Escape Evernight$t$, 0, $b$Thrown into Neverwinter's shadow with a kidnapped scholar, the party needs a way home.$b$),
  ($t$The Wizards' Summons$t$, 0, $b$A spell goes wrong and drags the party to a sanctum in Sigil, where three great wizards ask for help against Vecna.$b$),
  ($t$The First Piece: Web's Edge$t$, 0, $b$The first piece of the Rod of Seven Parts is in a secret haven of Lolth's cultists in the Underdark.$b$),
  ($t$The Second Piece: The Lambent Zenith$t$, 0, $b$The second piece went down with a spelljamming ship that crashed into a dead god in the Astral Sea.$b$),
  ($t$The Third Piece: The Ruined Colossus$t$, 0, $b$The third piece lies on Mount Ironrot in Eberron's Mournland.$b$),
  ($t$The Fourth Piece: Death House$t$, 0, $b$The fourth piece was taken to Death House in the village of Barovia.$b$),
  ($t$The Fifth Piece: Night of Blue Fire$t$, 0, $b$The fifth piece seems to be near a gigantic tree on Krynn, but its location keeps slipping.$b$),
  ($t$Rescue Valendar$t$, 0, $b$The Blue Fire Wardens' leader is a prisoner in Three Moons Vault.$b$),
  ($t$The Sixth Piece: Tomb of Wayward Souls$t$, 0, $b$The sixth piece is in a deadly tomb on the Isle of Serpents.$b$),
  ($t$The Seventh Piece: The Dragon Queen's Pride$t$, 0, $b$The final piece is in the Red Belvedere, Tiamat's casino in Avernus.$b$),
  ($t$The Betrayer Revealed$t$, 0, $b$With the rod complete, the party returns to the sanctum in Sigil.$b$),
  ($t$The War of Pandesmos$t$, 0, $b$Kas has fled to Pandemonium to free Miska the Wolf-Spider, and a war has broken out on the shore of the Ruinous Sea.$b$),
  ($t$Eve of Ruin$t$, 0, $b$Vecna is nearly finished. Break his three drafts of a new reality, then stop the ritual.$b$)
)
INSERT INTO public.the8_reveal_blocks (campaign_id, quest_id, body, is_revealed, sort_order)
SELECT c.id, x.id, s.body, false, s.sort_order
FROM seed s CROSS JOIN c
JOIN public.the8_quests x ON x.campaign_id = c.id AND x.title = s.title
WHERE NOT EXISTS (SELECT 1 FROM public.the8_reveal_blocks b WHERE b.quest_id = x.id);

-- ---------------------------------------------------------------------------
-- 10. TIMELINE  (33)
-- ---------------------------------------------------------------------------
WITH c AS (SELECT id FROM public.campaigns WHERE slug = 'eve-of-giants'),
seed(event_date, title, description, sort_order) AS (VALUES
  ($w$Eons ago$w$, $t$Miska Imprisoned$t$, $d$Seven Wind Dukes of Aaqa weave the Rod of Law and imprison the demon lord Miska the Wolf-Spider on Pandemonium. The rod shatters into seven pieces.$d$, 900),
  ($w$About 40,000 years ago$w$, $t$The War of Giants and Dragons$t$, $d$The giant empire of Ostoria fights a long, brutal war against the dragons and falls. The dragon-slaying colossus Vonindod is broken and dismantled.$d$, 1000),
  ($w$Centuries ago$w$, $t$Kas Betrays Vecna$t$, $d$On Oerth, the warlord Kas strikes down his master, the lich Vecna. Vecna flings him across the multiverse; only a hand and an eye remain of the lich.$d$, 1200),
  ($w$Since then$w$, $t$Vecna Becomes a God$t$, $d$Vecna rises again as a god of secrets and magic. Kas becomes a vampire, trapped in the Domain of Dread called Tovag.$d$, 1300),
  ($w$More than 500 years ago$w$, $t$The Phandelver Pact$t$, $d$Dwarf and gnome clans agree to share Wave Echo Cave. Human spellcasters join them and build the Forge of Spells. Old Phandalin prospers.$d$, 1500),
  ($w$About 500 years ago$w$, $t$The Fall of Wave Echo Cave$t$, $d$Bandits backed by mercenary wizards storm the mine. The spell battle brings the caverns down, and the mine's location is lost. Old Phandalin is sacked and abandoned.$d$, 1510),
  ($w$Thirty years ago$w$, $t$Mount Hotenow Erupts$t$, $d$The eruption devastates Thundertree, and a plague of strange zombies finishes it.$d$, 2000),
  ($w$Three or four years ago$w$, $t$Phandalin Resettled$t$, $d$Settlers from Neverwinter and Waterdeep start building a new town on the ruins.$d$, 2100),
  ($w$Recent years$w$, $t$The Tyranny of Dragons$t$, $d$Evil dragons rise for Tiamat and are beaten back; the Dragon Queen is banished to the Nine Hells.$d$, 2500),
  ($w$Over a year ago$w$, $t$Serissa Named Heir$t$, $d$King Hekaton divines that his elder daughters are unfit to rule and names his youngest, Serissa, heir to the Wyrmskull Throne.$d$, 2600),
  ($w$Months ago$w$, $t$The Ordning Shatters$t$, $d$Annam the All-Father breaks the order of the giants. Every giant in the world feels it at once.$d$, 2700),
  ($w$Months ago$w$, $t$Queen Neri Is Murdered$t$, $d$The storm giant queen is killed on a small island where she met with humans. Rumours in the storm giant court blame the Lords' Alliance.$d$, 2710),
  ($w$Months ago$w$, $t$King Hekaton Vanishes$t$, $d$Hekaton sets out to find his wife's killers and disappears. A month later Serissa takes the throne as regent.$d$, 2720),
  ($w$Months ago$w$, $t$The Giant Lords Strike Out$t$, $d$Guh, Kayalithica, Storvald, Zalto and Sansuri leave the storm giant court to win the gods' favour their own way.$d$, 2730),
  ($w$Recently$w$, $t$The Ritual of Remaking Begins$t$, $d$Vecna's cults across the worlds begin draining secrets from kidnap victims. The Dark Powers tell Kas, give him the Crown of Lies, and let him go.$d$, 2800),
  ($w$A couple of months ago$w$, $t$The Redbrands Arrive$t$, $d$Iarno Albrek, sent by the Lords' Alliance, vanishes near Tresendar Manor. A gang in scarlet cloaks led by 'Glasstaff' takes over the town. Marauders camp on Wyvern Tor.$d$, 2900),
  ($w$A month ago$w$, $t$The Rockseekers Find the Mine$t$, $d$The three Rockseeker brothers find the entrance to Wave Echo Cave. They are followed.$d$, 2950),
  ($w$A tenday ago$w$, $t$Thel Dendrar Murdered$t$, $d$The Redbrands kill a woodcarver who stood up to them, and his family vanishes.$d$, 2980),
  ($w$Act I · Level 1$w$, $t$The Ambush on the Triboar Trail$t$, $d$Gundren Rockseeker and Sildar Hallwinter are taken by Cragmaw goblins on the road to Phandalin.$d$, 3010),
  ($w$Act I · Level 5$w$, $t$Wave Echo Cave Is Won$t$, $d$The Spider falls and the Forge of Spells is found.$d$, 3050),
  ($w$Act I · Final night$w$, $t$Giants Above Wave Echo Cave$t$, $d$During Phandalin's victory feast, fire giants with a glowing rod circle the hills above the mine, then march east toward Triboar.$d$, 3060),
  ($w$Act II · Level 5$w$, $t$Fire Giants Attack Triboar$t$, $d$Okssort and Ildmane lead a fire giant war band into Triboar, digging for something buried under the north campground.$d$, 4010),
  ($w$Act II · Level 7$w$, $t$The Oracle Speaks$t$, $d$At the Eye of the All-Father the oracle names Iymrith and sends the party after a giant lord's conch.$d$, 4030),
  ($w$Act II · Level 8$w$, $t$Harshnag Falls$t$, $d$Iymrith comes to the Eye of the All-Father. Harshnag the Grim holds her off.$d$, 4040),
  ($w$Act II · Level 9$w$, $t$A Giant Lord Brought Down$t$, $d$The party takes one of Hekaton's conchs from a giant lord's stronghold.$d$, 4050),
  ($w$Act II · Level 10$w$, $t$Hekaton Freed$t$, $d$The trail of the golden goose chip leads to Yartar and the Morkoth, where King Hekaton lies in chains.$d$, 4070),
  ($w$Act II · Level 11$w$, $t$Doom of the Desert$t$, $d$Storm giants and small folk strike Iymrith's lair in Anauroch together. Hekaton swears an alliance against dragons.$d$, 4080),
  ($w$Act III · Level 10$w$, $t$The Neverdeath Ritual$t$, $d$Under Neverdeath Graveyard the party breaks a Vecna cult's ritual, and is flung into Evernight.$d$, 5010),
  ($w$Act III · Level 11$w$, $t$The Wizards Three$t$, $d$A botched wish pulls the party to Sigil, where 'Mordenkainen' sends them after the Rod of Seven Parts.$d$, 5020),
  ($w$Act III · Levels 12–17$w$, $t$The Hunt for the Rod$t$, $d$The Astral Sea, the Mournland, Barovia, Krynn, the Isle of Serpents and Avernus, one rod piece in each.$d$, 5030),
  ($w$Act III · Level 18$w$, $t$The Betrayer Revealed$t$, $d$Mordenkainen is unmasked as Kas, who wounds Alustriel and Tasha and flees with the rod.$d$, 5040),
  ($w$Act III · Level 19$w$, $t$The War of Pandesmos$t$, $d$Kas frees Miska; Lolth's forces fight his. Banished, Kas gives up where Vecna is.$d$, 5050),
  ($w$Act III · Level 20$w$, $t$Eve of Ruin$t$, $d$The party breaks Vecna's three unrealities and enters the Cave of Shattered Reflection.$d$, 5060)
)
INSERT INTO public.the8_timeline_events (campaign_id, event_date, title, description, sort_order, is_secret)
SELECT c.id, s.event_date, s.title, s.description, s.sort_order, true
FROM seed s CROSS JOIN c
WHERE NOT EXISTS (SELECT 1 FROM public.the8_timeline_events x WHERE x.campaign_id = c.id AND x.title = s.title);

COMMIT;

